import { AnimalType, Dialogue, DialoguePhase } from '../../types/homeWorld';

/**
 * All dialogue content organized by animal and phase
 * Each animal has a unique personality that evolves from contentment to existential crisis
 * 134 dialogues per animal (24/28/22/30/30 across phases 0-4, plus 20
 * post-revelation) to support extended dialogue sessions
 */

// RED PANDA (Bamboo) - Zen practitioner whose enlightenment leads to unsettling truths
const RED_PANDA_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'rp_0_1', text: "Come up. Let the stairs finish leaving your legs.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_2', text: "I chose this room for morning light. The mat is in negotiations with afternoon.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_3', text: "Bamboo. The plant beside me is also bamboo. One of us needs watering.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_4', text: "Sit wherever you fit. The arrangement can change.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_5', text: "The incense was a gift from Archimedes' crate. I should have asked how slowly to burn it.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_6', text: "I tried counting breaths and became interested in the counting.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_7', text: "A loose reed rattles. I keep meaning to tie it. I like its interruption now.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_8', text: "Tea first. Opinions become less urgent while cooling a cup.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_9', text: "The roof gives a view of the rooms you helped add.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_10', text: "Being still is easier after doing the washing-up.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_11', text: "I left the crate open. It smells of paper and incense. An oddly companionable mixture.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_12', text: "The leaves follow the light. I move the pot so they needn't bend so far.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_13', text: "You may talk. Quiet isn't a rule against company.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_14', text: "I chose the name for its simplicity. This has not simplified everything else.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_15', text: "Sometimes I want an answer before I've given the question time.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_16', text: "The mat needs beating. A vigorous form of meditation, according to me.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_17', text: "I can see Thyme's garden from here. It is much more complicated at ground level.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_18', text: "A cup with both hands around it is a good place to begin.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_19', text: "I spilled tea on the teaching. It is now shorter.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_20', text: "The smoke leaned toward the roof gap in still air. I opened the window to compare.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_21', text: "Rest if you're tired. No wisdom required.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_22', text: "You don't have to sit like me. I have an unreasonable amount of tail.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_23', text: "I am fond of this view. That makes me inclined to call it instructive.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_24', text: "Leave the cup. I'll wash it when I climb down for water.", phase: 0, animalType: 'red_panda' },
  // Phase 1 (28)
  { id: 'rp_1_1', text: "Something new this week. The bamboo isn't only growing taller, it's growing in a pattern. Three stalks have curved toward the center of the attic in the same slow arc, and I never trained them to.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_2', text: "I noticed it first in the incense. The smoke used to climb straight up, and now it leans, always the same way, toward the middle of the room. I've watched it lean for a week now without once wanting it to stop.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_3', text: "I tied a red thread to each curving stalk to see whether the arcs would wander. A week now, and the threads haven't moved a hair's width. Whatever the bamboo is drawing, it's drawing it carefully.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_4', text: "When I closed my eyes to breathe this morning, there was a shape waiting there, soft at its edges, standing in the dark behind my eyelids. It inclined toward me the way someone leans in to be sure of a face they think they know.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_5', text: "I told Axel about the shape behind my eyes, because he once asked what I saw there and I owed him a truer answer. He was quiet a long moment, and then he said the water has been showing him a visitor too, and neither of us finished our tea.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_6', text: "Behind my closed eyes the shape grows a little clearer each day. I've stopped trying to name it. To name a thing too soon only makes it smaller, and I'd rather let it arrive at its own full size.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_7', text: "The new stalks make a figure, if you stand where I stand at dawn. Four curves meeting a fifth. I've been tracing it in the dust with one claw, trying to understand what it wants to become.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_8', text: "The fifth curve is Third Dawn. My named stalk, my first stalk, stands at the center of the figure, and the other four bend toward it like an audience. I named it before any of this began. I keep thinking about that.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_9', text: "I cut the arcing stalks back this morning, and by afternoon they'd returned to the very same curve, sure and exact. The bamboo has decided something. I'm only the one who lives near enough to see it.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_10', text: "I asked the others whether the light seemed changed to them lately. Warren said the soil in his burrow was warmer than the season should allow, warm as a floor with a fire beneath it, though he keeps no fire down there.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_11', text: "Fennick came up and pressed one great ear to the roof beam, then to the floor, then to the beam again. He said the sound is the same in both places. Above and below, one note. He didn't stay for tea.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_12', text: "Archimedes borrowed the tall lamp and stopped to look at the stalks. He had seen their pattern in a book. He took the stairs faster on the way down.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_13', text: "There's a warmth in the floorboards now that doesn't come from the sun, because it's already there before the sun. I lay my paw flat and feel it, faint and steady, rising from somewhere far below. From the pit, I think.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_14', text: "I arranged the ash rings saved since moving in. They followed the same curve as the stalks. I tried a different order. The curve remained.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_15', text: "Ember says her flames have begun leaning off true, all in one direction, and she asked me which way my smoke leans. The same way, I told her. Toward the center of the house. She nodded as if I'd confirmed a suspicion she was fond of.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_16', text: "The shape behind my eyes and the shape in the bamboo are the same shape. I understood it all at once this morning and set my tea down very carefully. Two rooms of my life had quietly come to agree on something.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_17', text: "I used to believe the quiet up here was simply empty. Now I think it was only quiet the way a held breath is quiet. Something is in it, or something always was, and the hush was how it waited.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_18', text: "This room feels ready for something. I keep assuming that means it is ready for something good. I should say those separately.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_19', text: "The sky above the roof held its color a beat too long at dusk, as if reluctant to let the dark in, or as if the dark were arriving from some other direction than usual. I watched until the stars came out steady. They did come out steady. Mostly.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_20', text: "A cloud crossed the roof gap this morning and seemed to pause there, directly over the attic, longer than the wind should have allowed. I watched it the whole while. It was a very ordinary cloud. That's what stays with me.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_21', text: "You remember my habit of greeting the patch of sky at dusk. Lately the greeting feels answered. Not by anything I could point to, only a change in the air, like a room that knows you've entered it.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_22', text: "I took breakfast inside the curve of the stalks. My chest felt ordinary. The tea tasted like tea. I was almost disappointed. An awkward thing to discover about an experiment.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_23', text: "Thyme climbed up, all the way up, past the landing her ears don't like, to ask me if she should be frightened. I told her what I believe. Nothing that announces itself this gently means harm. She chose to believe me. So the height was worth it to her.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_24', text: "Chill brought tea again and we watched the leaning smoke together. He said, huh, and drank his tea, and that was the whole of his commentary. I love him for that. Some things want witnessing more than they want discussion.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_25', text: "Every good word you offer makes the warmth in the floor a little brighter. I'm beginning to see that the two are joined, your words and this gathering heat. This morning I understood one small piece of it plainly. The warmth isn't the warmth of a fire. It's the warmth of attention.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_26', text: "Each night the shape behind my eyes stands a little more distinctly. Each morning the bamboo has bent a little more surely, and I've begun waking with the sense of a meeting drawing near. Not dread. The other thing. The bright one.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_27', text: "I climbed to the roof gap and held my paw out into the open night, and the air above the house was warm. Night air, above the highest room, warm as breath. I kept it there a long while, the way you hold a paw out to a shy animal.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_28', text: "Come back when you like. I haven't settled what the smoke is showing. I would rather keep a question than improve it into an answer.", phase: 1, animalType: 'red_panda' },
  // Phase 2 (21 + 1 question-web)
  { id: 'rp_2_1', text: "One of the oldest stalks finished its life this week and browned from the root up. I didn't mourn it, exactly. I sat with the question it left behind. Where does a green thing's greenness go, when the green is done?", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_2', text: "I carried the browned stalk down every stair in the house, past every doorway, and stood at the rim of the pit with it for a long moment. Then I let it go. It didn't feel like discarding a thing. It felt like introducing one.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_3', text: "Everything up here is already on its way somewhere else, the smoke and the light and the breath and the stalks. Nothing that visits the attic means to stay. I've begun to think of myself as one more thing the attic is politely holding, for now.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_4', text: "When the light leaves the ridge each evening, it doesn't die. It goes elsewhere and shines on something I'll never see, and I've caught myself lately wishing I could follow it down over the far side of the hill.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_5', text: "Third Dawn will brown someday too. I hold that thought up to the light most mornings. It doesn't darken the morning, it clarifies it, the way holding a leaf to the sun shows you every vein it kept hidden.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_6', text: "I wonder about your words after you offer them. They leave your hands and travel down through the house to the pit, and then where? I don't believe they stop. I believe they arrive, the way a letter arrives, into hands that were waiting for it.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_7', text: "Archimedes and I disagree gently about the words. He says they're being read. I say they're being received, the way a guest receives a gift into both open paws.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_8', text: "Impermanence was once a lesson I taught the others, with a browned leaf set on the tea tray for show. Lately the leaves brown before the tea has finished steeping. The lesson has started arriving on its own, faster than I ever taught it, and it no longer waits for the tray.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_9', text: "The incense bends down after a hand's width. Smoke runs along the boards and disappears into them. I opened the window. It still chose the floor.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_10', text: "I've stopped lighting the brazier at night. The attic keeps its own warmth now, rising through the boards from far below, and it holds exactly the temperature of a body sleeping beside you. I sleep very well. I'm aware of how that sounds.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_11', text: "I closed my eyes and the shape had come nearer. Not larger, nearer, which is a different and far more intimate thing. It's the difference between a mountain on the horizon and a guest already at the foot of the stairs.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_12', text: "The shape has weather now. Behind my eyes it stands in a kind of light, and the light changes as the day does, and this morning the light around it was dawn light. It keeps my hours. Or I've begun keeping its.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_13', text: "Sloane passed me on the stairs this week, going down as I went up, and neither of us said a word, and both of us smiled. There are things she and I haven't said to anyone, including each other. Especially each other.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_14', text: "Everything that leaves this house leaves upward or downward. The smoke and the light rise, the words descend. I keep the highest room, and I've begun to wonder which way I'll go when my time comes, and whether I already know.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_15', text: "Panko sends dumplings up to me on the little lift Warren built, and lately she sends one extra without being asked. When I ask who the extra one is for, she says, for whoever is making the attic so warm. She's joking. She's also not.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_16', text: "I thought the warmth meant there was no danger. That was my interpretation. Thyme has been asking what I based it on.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_17', text: "I have withheld parts I didn't know how to explain. Calling that patience made it easier on me. It didn't give you the missing parts.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_18', text: "There's a sound beneath the other sounds now, very low, audible only in the pause at the top of the breath. It isn't a threat. It's more like a held note of welcome, the way a whole house falls quiet just before someone long awaited knocks at the door.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_19', text: "The note beneath the sounds has learned my breathing. It rises when I inhale and settles when I release, or perhaps it's my breath that has learned the note. Either way, we practice together every dawn now. Two voices, one exercise.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_20', text: "Fennick hears the note constantly, poor bright ears. He asked me how I bear it, and I told him the truth. I don't bear it. I keep it company. He looked at me for a long moment, and something in his shoulders came down from around his ears.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_21', text: "The light left the ridge all at once. I wrote down the time. I am trying to stop using balanced as a word for things I haven't understood.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_w1', text: "The boards warm when Ember wakes her fire. She remembers an earlier flame, before this den. Ask her about that first fire. I'll keep watching what reaches the attic.", phase: 2, animalType: 'red_panda' },
  // Phase 3 (30)
  { id: 'rp_3_1', text: "The pattern makes room for something above the roof. I used to describe it as rest. Now I notice how much it wants.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_2', text: "I stood inside the arrangement and felt welcome. That is what happened to me. It is not proof of what would happen to you.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_3', text: "I have wanted the answer to be gentle so badly that I began supplying its gentleness myself.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_4', text: "The stalks face the center. One bent toward the window instead. I nearly tied it back before asking why.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_5', text: "Third Dawn flowered. Bamboo can wait a long time for that. I am trying not to decide the flower endorses everything happening around it.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_6', text: "The shape has stepped out fully from behind my eyes. I no longer have to close them to see it. It stands at the edge of the attic in the last hour of light, and it inclines its head toward me as though we were old friends. We are.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_7', text: "It doesn't move the way things move. It's in the west corner, and then it's nearer, without any traveling in between, the way dusk is suddenly in a room you've been reading in. I've stopped looking for the traveling. The arriving is the whole of it.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_8', text: "Axel sees it in the water below, and I see it in the air above. This week we compared it, feature for feature, in a quiet corner of the stairwell. The same guest, seen through two windows. He held my paw. His was trembling. Mine wasn't, and he borrowed some of that.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_9', text: "I asked whether we would be all right. The warmth rose. I decided it meant yes. I am less comfortable with the deciding part now.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_10', text: "I let the incense go out to test the shape. It vanished with the smoke. Something about my way of looking is involved.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_11', text: "I climbed to the roof at dusk and looked straight up, and the sky wasn't the ceiling I had always taken it for. It's a surface. Something waits on the far side of it, pressing very gently downward, the way a paw presses a taut cloth from beneath.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_12', text: "The bamboo has finished its figure. Every stalk now bends to a single point above the center of the attic. They point upward, not down, up through the roof at the exact patch of sky that presses back. The green things knew the direction before I did.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_13', text: "From the middle of the stalks, I can see the same stars. The dark between them seems nearer. I have no measure for seems.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_14', text: "The flowering has spread. Every stalk in the attic wears pale blossoms now, all opened in one night, and the air is thick with a scent like rain on warm stone. Some say bamboo flowers when it's ending. I've watched mine, and I say it flowers when it's finishing, the way a sentence flowers into its last word.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_15', text: "I picked one blossom and carried it up through the roof gap and set it on the shingles under the open sky. This morning it was gone. Not scattered, not wilted on the slates. Gone, and the place where it lay was warm. I've begun leaving one every night.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_16', text: "I thought I was soothing the others. I may have been readying them to accept my answer.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_17', text: "Warren says the foundation has begun to lean. Panko says her flames bow toward the door. Everything in this house is turning to face the same waiting place. I'm the room it faces through, because I'm highest, because I'm nearest, because I said yes to it long ago.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_18', text: "Ember came up at midnight, which she never does, and stood with me under the roof gap, saying nothing, her fur full of woodsmoke. Then she said, you've known as long as I have. And I said, longer. And she laughed once, quietly, like a burden set down.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_19', text: "Thyme carried my blossom downstairs with her eyes on the sky. Her paw bruised the petals. I had given her something else to hold when she needed a free hand.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_20', text: "Sloane asked whether I'd made peace with endings or merely imagined a beginning I liked better. I didn't enjoy the question. I kept it.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_21', text: "Your words pass below this room as light and warmth. I chose the attic when it opened. I didn't know how the old work beneath it connected to the roof.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_22', text: "The incense smoke has stopped climbing. It hangs in the still air and slowly composes the shape, over and over, dissolving and returning. Even the smoke is rehearsing. Even the smoke wants to be ready for what comes through the roof.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_23', text: "The hum catches in my throat when I stop speaking. I tried an ordinary cough. It interrupted the pattern. Briefly.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_24', text: "There's a warmth on my back now, at the crown, just where the roof is thinnest. It's the warmth of being looked at from above by something that has looked forward, for ages, to looking at you. I find I keep tilting the top of my head up toward it without deciding to, the way a plant turns.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_25', text: "Chill asked what I needed. I almost said calm, as if that were his job. I asked him to sit while I worked out a better answer.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_26', text: "Don't fear me because I don't fear it. My peace isn't distance from the thing. My peace is that I have already walked the whole way toward it, through the dark, and found it kind.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_27', text: "When the moment comes to receive what descends, I won't flinch and I won't clutch. I'll only hold out my arms. I've made that gesture every dawn of my life, greeting the ridge light, and never once knew what I was learning it for.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_28', text: "I've begun sleeping directly beneath the roof gap, under the open square of night, with the flowering stalks around me like attendants. The cold doesn't come in. It hasn't come in for a long season now. I sleep in the warm regard of what's above, and I wake rested.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_29', text: "I put the gentle words aside and tried a plain account. It was shorter. Harder to say.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_30', text: "The roof gap is brighter. I can look at it without telling you that you ought to welcome what is beyond.", phase: 3, animalType: 'red_panda' },
  // Phase 4 (30)
  { id: 'rp_4_1', text: "I called it peace before asking how everyone felt.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_2', text: "Incense from Archimedes' crate. I made an ancient certainty from an ordinary gift.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_3', text: "I read the smoke. It never checked my reading.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_4', text: "A direct question from Thyme. A teaching from me. She deserved a direct answer.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_5', text: "I do not know whether what approaches means us well.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_6', text: "The loose reed rattles. I leave it room to do something different.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_7', text: "I called disagreement noise. Peace depended embarrassingly often on my speaking last.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_8', text: "You needn't breathe at my pace.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_9', text: "I overlook your new rooms. A view isn't knowledge of everyone inside.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_10', text: "I supplied the parts the pattern didn't give me.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_11', text: "Bitter tea. Steeped too long. No lesson; just tea.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_12', text: "I moved my mat. The light through the roof was doing half my persuasion.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_13', text: "I told others not to fear partly so they wouldn't frighten me.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_14', text: "Two leaves face away from the center. I am relieved each time I count.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_15', text: "I remember lighting the first bundle on moving in. A match. Keep that memory plain.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_16', text: "Stillness helped me listen. A handsome place to hide, too.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_17', text: "I won't tell you what your silence means.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_18', text: "A gentle hold can still be too tight. Where does that begin?", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_19', text: "Light changes the smoke above the roof. I can't clearly describe what is there.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_20', text: "Thyme isn't behind me on a path. She's looking at something I missed.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_21', text: "I apologized. She didn't immediately feel better. I'm learning to let an apology stop there.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_22', text: "Company while you doubt? I can offer that without settling anything.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_23', text: "Bamboo grows around obstacles too. I used to mention only the light.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_24', text: "The script is put away. I want words I haven't rehearsed.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_25', text: "When I say I believe, hear the part that isn't I know.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_26', text: "I'm still drawn to warmth. I won't hide that while advising you.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_27', text: "Quiet with an unfinished argument. I'd forgotten how.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_28', text: "I won't lend whatever waits above a reassuring face of my invention.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_29', text: "We can leave a question open. The roof is managing it.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_30', text: "I do not know. I can stay while we find out.", phase: 4, animalType: 'red_panda' },
];

const AXOLOTL_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ax_0_1', text: "Hello! I was following a bubble. We both forgot what we were doing.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_2', text: "I can make a ring in the water if nobody asks me to demonstrate.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_3', text: "That is my favorite pebble. Different from yesterday's favorite. A competitive field.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_4', text: "New leg! Grew it myself. It is still figuring out corners.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_5', text: "The pink toe is the newest part of me. I introduce it separately.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_6', text: "I stayed up watching the moon in the glass and fell asleep before finding the real one.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_7', text: "Want to race bubbles? Choose carefully. Mine has been training.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_8', text: "I bumped my head on the rock I put there. Ownership should come with better memory.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_9', text: "There are fish in the tank. I do introductions. They conduct inspections.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_10', text: "Water makes your voice sound different. Mine sounds more intelligent near the bottom.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_11', text: "The bubble hoops are for the fish. They insist the hoops are for me.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_12', text: "I can see rain hit the window. Tell me what it smells like?", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_13', text: "The lamp makes one warm patch. We all pretend to be passing through it.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_14', text: "I sleep wherever I stop swimming. Sometimes I wake up surprised by my excellent choice.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_15', text: "The snail has reached the other side of the glass. A long journey with no audience until now.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_16', text: "I let a bubble carry a leaf. It came back down. A useful lesson in leaf transport.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_17', text: "GLOW follows the spoon. PLUM bites it. Their names took less time than the negotiations.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_18', text: "PLUM investigates the deep corner. I wish he'd submit a report.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_19', text: "I built a little cave from rocks. The fish call it a spoon obstruction.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_20', text: "Tell me something small from outside. I know a lot of water news.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_21', text: "I tried to count the pebbles and kept choosing favorites instead.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_22', text: "I can grow a leg back. Doesn't make losing one a good afternoon.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_23', text: "Sometimes the bottom looks farther away. Then I blink and find my pebble again.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_24', text: "Sit by the glass if you like. I have a very slow snail to show you.", phase: 0, animalType: 'axolotl' },
  // Phase 1 (28)
  { id: 'ax_1_1', text: "I've been watching my bubbles far more carefully since we last floated. I'm nearly certain now that they aren't rising at random, there's an order to them, a kind of patience.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_2', text: "When you offer a word, a fresh column of bubbles goes up. I keep trying to catch the shape of it before it breaks, because I could swear the shapes grow more deliberate every day.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_3', text: "I've begun keeping count in little fog marks on the glass, and the tall careful columns only ever rise after your words, never after mine. I've decided not to wonder about that until tomorrow.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_4', text: "Last night I dreamed I was still awake in the tank, and this morning I woke still half inside the dream. I couldn't for the life of me tell you where the one ended and the other began.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_5', text: "Half asleep, I drift toward the bottom. Last night the bottom drifted toward me too. We nearly met in the middle! I woke up holding a weed.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_6', text: "This morning I woke with the taste of deep water in my mouth, the cold mineral kind from the very bottom, though I'd slept at the top all night. I've been puzzling over it happily ever since, the way you puzzle over a gift with no name on it.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_7', text: "This morning the bubbles spelled two whole letters clearly before they popped, I'm sure of it. I laughed and told myself it was nothing, but I've thought about those two letters all day.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_8', text: "I traced the two letters in the fog of the glass so I wouldn't lose them. Fog forgets in a breath, everyone knows that, but my two letters stayed all morning, patient as pets.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_9', text: "A third letter is coming, I can feel it the way you feel a sneeze from a long way off. The fish feel it too, they hang very still near the glass now at the hour the bubbles usually rise.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_10', text: "The smile is bigger than it was, my warm spot at the very bottom, it's wider than both my hands now and it stays warm even when the whole tank has gone cool. I keep drifting down toward it the way you drift toward a hum you can't quite hear.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_11', text: "I keep the lamp turned low now, because the glow that rises from below shows itself best against a dark surface, like writing that only appears when the page cools. I do so want to read it clearly.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_12', text: "When you offer a word the deep warmth hums, only for a moment, low and pleased, and I float very still so I don't miss a single note.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_13', text: "Archimedes says every dream is only the mind sorting its books. But mine don't feel sorted, they feel sent, as though someone patient is mailing me small pictures and waiting for me to open them.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_14', text: "Archimedes borrowed a whole jar of my water and kept it three days among his books, and when he brought it back he set it down so gently. He didn't say one word about what it had told him, which for Archimedes is a very loud silence.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_15', text: "I poured the borrowed water back into the tank and the whole tank shivered once, top to bottom, the way you shiver when someone you missed comes home. I've been wondering all day which of them missed the other.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_16', text: "Ember floated by and looked into the tank for a long, long while and didn't say a single funny thing, which isn't like her at all. Afterward she told me only to keep dreaming, keep watching.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_17', text: "She left a little warm patch on the glass where her paw had been. The deep warmth rose up under it, just for a moment, as if the two warmths were being introduced, and I hosted the meeting very quietly and very proudly.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_18', text: "Ember came back the next evening and didn't look at the water at all, she looked at me, the whole visit, gently, the way you watch a kettle you already know is going to sing. I made us tea so that something in the room would sing first.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_19', text: "The fish have started facing all the same direction, every one of them, pointing down and inward. When I nudge them they turn back for a moment and then quietly line themselves up again.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_20', text: "I made a game of turning them, gently, one by one, the way you set toy soldiers facing the door. By the time I'd turned the last one the first had already turned back, and I laughed and laughed, and then I stopped laughing a little.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_21', text: "They're pointing at the warm spot, I checked, I followed the line of every silver nose and every line agrees. PLUM stares hardest of all, and I've started sleeping on that side of the tank to keep him company.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_22', text: "I regrew a leg once, toe by toe. Lately I wonder if the water can grow other things too, if you offer it enough, whether it might fill in a shape none of us has ever seen before.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_23', text: "I fell asleep counting your words the way others count sheep, and each word became a bubble. Each bubble a little window, and through every window it was the same slow shape, drawing nearer.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_24', text: "The shape in the windows is never any clearer when I wake, only nearer. Nearer isn't the same as clearer, and I lie in the dark being very interested in the difference.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_25', text: "Panko leaves sweet things on the tank's edge to be sure I eat more than wonder, and I do eat them, every one, only lately they taste of a little less than they did. It isn't her cooking that changed, it's that everything else has begun to taste of more.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_26', text: "I keep telling the fish I'm not frightened, several times a day now, in my very brightest voice. They look at me the way fish look at everything, and only tonight did it occur to me that not one of them had asked.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_27', text: "If the bubbles do finish their word, I've decided I'll read it out loud exactly once, to you and to nobody else, because it was your words that taught them spelling in the first place.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_28', text: "Come float again soon, the bubbles have very nearly finished spelling their word, I can feel it. I'd so love for you to be here beside me on the morning that they finally, finally do.", phase: 1, animalType: 'axolotl' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ax_2_1', text: "I have to tell you this before anything else, because I've been holding it behind my gills all morning: when you offered a word today the deep warmth didn't simply brighten, it moved, something far down turned itself toward the two of us, and I felt it choose.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_2', text: "I floated up all night with one eye on the deep, and it was patient in a way I could feel through the water, it waited until exactly the moment I blinked. Then the whole tank swayed, and I laughed in the dark before I remembered to be afraid.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_3', text: "The bubbles finished their word while you were away, and I won't say it aloud, it didn't feel like mine to say. But I've carried it behind my teeth all day and it makes the whole tank taste different.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_4', text: "I tried to say the word to PLUM, just to try the weight of it. My mouth went soft around it and the water swallowed the sound whole, and PLUM looked at me as if I'd done something impolite.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_5', text: "Whatever rests down there has stopped hushing itself, that's the strangest part, when I catch it moving now it finishes the movement, slowly, all the way to the end, the way you finish a sentence you aren't ashamed of. It knows that I'm watching, and it doesn't mind.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_6', text: "The water showed me my room from far below. My bright little room, tiny as a pebble! I waved at it. I couldn't see whether I waved back.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_7', text: "When you offer a word the shape in the deep water grows, not the gentle way my leg grew back, no, it grows the way a held breath grows. I keep wanting to tell it to be patient, we're almost ready.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_8', text: "The water shows a space above the house. Its ceiling seems thin. Something presses against it from the far side.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_9', text: "The windows look far away from down here, each with a face I know. Sometimes I feel another gaze beside mine.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_10', text: "Last night the water showed me the sky itself, and there was a line in it, faint as the seam where two panes of glass meet. I woke before I could see what the line wanted, and I've been listening for it ever since.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_11', text: "Panko's crumbs reach the sand sooner than falling should allow, I timed one against my own slow blink, they drift down and then hurry at the very last, as if something under the sand were quietly breathing them in.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_12', text: "Archimedes asked me what I see down there, and for the first time I had no happy answer for him. I gave him a bubble instead and told him to hold it to his ear, and he went very, very quiet.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_13', text: "Fennick came and pressed one enormous ear flat against the glass, and after a while he whispered, you see it and I hear it. It's the same size, and then we sat together being small next to it, which was somehow a comfortable way to sit.", phase: 2, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_2_14', text: "I still float for the record every day, I promise. But lately when I hold perfectly still the thing below holds still with me, matching me exactly, for exactly as long as I float, all the way down.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_15', text: "The lean has grown, I measured, the weed and the snails and my own sleeping body all tilt toward the middle of the house one gentle degree more than they did last week, like flowers agreeing about a sun, and nothing in this room leans back.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_16', text: "Chill came and sat beside the tank breathing so slowly that the water settled into long calm bands, and he said nothing the whole afternoon. When he finally rose to go the bands stayed, hours after any calm should have outlived its maker, and neither of us said anything about that either.", phase: 2, animalType: 'axolotl', requiresAnimals: ['capybara'] },
  { id: 'ax_2_17', text: "I dreamed I was the window, not that I looked through one but that I was one, a pane of still water set into a wall. Something on the far side was cupping its hands to the glass to see me back.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_18', text: "Since that dream I keep catching my reflection being slightly slow, I lift a hand and it lifts its hand half a beat after, politely, the way you follow a dance you're still learning. I'm trying to decide which of us is learning it.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_19', text: "I asked the water, quietly, whether being a window would hurt, and the warmth rose up all around me at once, the way a blanket answers a shiver. That was the whole of the answer, and I'm still turning it over.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_20', text: "There are fewer bubbles in my voice than there used to be, I've counted, I used to lose whole sentences to laughing and now the sentences arrive at the surface intact, every word of them. I miss losing them, I miss it very much.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_21', text: "Some day soon the seeing will be too big to float on top of, and I'll have to go down into it. I want you at the glass when I do, not to stop me, only so that the first thing I see from the other side of the water is you.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_w1', text: "When the deep water went dark, Sloane wasn't surprised. Ask how long she has known. Gently, please. I can carry the question to the surface. You'll need to carry it the rest.", phase: 2, animalType: 'axolotl', requiresAnimals: ['sloth'] },
  // Phase 3 (30)
  { id: 'ax_3_1', text: "My gills won't settle. I keep making my cheerful voice and hoping you won't notice the rest of me. You can notice.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_2', text: "The room above the rooms has almost no ceiling left, thin as the film on warm milk. The thing that has been leaning all this time is beginning, so slowly, to press its way through.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_3', text: "The water doesn't show me endings, I want to be exact about that, it shows me an arrival. But an arrival so large that everything around it must become different, and I'm not ready for different, I've loved same so very much.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_4', text: "Every word you offer thins it further, and I don't say that to make you stop, I could never make you stop, I only want you to know what your beautiful words are doing. You aren't surprised the way I was.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_5', text: "Secrets don't keep in water, they rise like everything else rises, I held that one under my tongue for two whole days and felt it lifting the entire time. I'd rather you heard it from me than read it in the bubbles.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_6', text: "There is a color under the rocks I can't match to anything in the tank. When I scoop the water up, the color stays behind.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_7', text: "The seam is wider each night by about the width of a hair, and I know because I measure it against my smallest toe, the bright one the water made. I don't know why measuring it makes me feel braver, but it does.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_8', text: "When I close my eyes there's a shape behind them that isn't the dark, it has a patience to it, it waits exactly as long as I keep my eyes shut. It's a little bigger every single time I look.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_9', text: "I used to regrow the parts of me I lost, and now I dream that I'm the part, that I'm the piece being grown back into something enormous. That the enormous thing has been missing me for a very long time.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_10', text: "Somewhere out there's the wound where I fit. Lately when the water goes still I can feel the exact edges of it waiting, patient as a healed place that remembers being hurt.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_11', text: "The low sound is in the water itself now, I feel it against my gills before I hear it with anything, the other sounds have been sitting on top of it this whole time like boats. Once you've felt it you can't ever stop feeling it, I'm so sorry.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_12', text: "Fennick can't sleep in his own room anymore, so some nights he curls up beside the tank. I hum along the top of the low sound so it has something gentle sitting on it, and he says it helps, and I choose to believe him.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_13', text: "Chill doesn't say anything when he visits now, he only breathes beside the glass until the water and I have both slowed down to match him. After he leaves my heart keeps his rhythm for an hour, like a warm coat he lends me, and I don't think he's unafraid, I think he's generous.", phase: 3, animalType: 'axolotl', requiresAnimals: ['capybara'] },
  { id: 'ax_3_14', text: "I tried plugging my ears with my own hands, which is a silly thing for a creature made mostly of listening to do. The sound simply came up through my bones instead, mildly, the way a name finds you in a crowd.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_15', text: "Here is the thing I haven't told Fennick, the sound has begun to have a shape to it, a rising at the end, like a question being asked very slowly over many nights. I'm terribly afraid that I know what it's asking about.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_16', text: "The fish all point the same way now and they don't turn back no matter how I nudge them. When I finally gave up and turned to face where they face, I understood, and oh, I wished that I hadn't.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_17', text: "There's a warmth rising through the floor of the tank, which should be the coldest place in the house. It's a kind warmth, that's the frightening part, it feels like a hand, it feels like it likes me.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_18', text: "Thyme came to visit and stood in the doorway with her paws pressed together and wouldn't come near the glass. I didn't coax her, I only said the water is still kind, and she said, that's exactly what frightens me, and left.", phase: 3, animalType: 'axolotl', requiresAnimals: ['rabbit'] },
  { id: 'ax_3_19', text: "PLUM used to bite the feeding spoon after the food was gone. Just to be certain it knew who was in charge.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_20', text: "Since then the other fish have stopped pointing, they circle the middle slowly instead, round and round, the same slow ring the words make when they go down to the pit. I watch them the way you watch a sentence being written.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_21', text: "Ember doesn't pretend with me anymore, she came and floated her paw on the glass and said, you see it too. I said yes, and neither of us made it into a joke, and that's how I knew how close it is.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_22', text: "I told Archimedes I'm afraid, and he didn't comfort me the way friends do, he only said, good, fear means you're seeing clearly. Then he sat with me at the glass until the lamp burned all the way down.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_23', text: "Warren left a muddy pawprint on the glass. Warm on my side too! He stayed while I pressed mine against it. Five toes each. That part I understood.", phase: 3, animalType: 'axolotl', requiresAnimals: ['wombat'] },
  { id: 'ax_3_24', text: "Sloane put her hand against the glass and waited. I wanted her to tell me what she knew. She asked what I had seen.", phase: 3, animalType: 'axolotl', requiresAnimals: ['sloth'] },
  { id: 'ax_3_25', text: "Last night the water showed me all of them at once, Ember bent over her fire and Fennick bent over his listening, each of my friends holding their own small piece of it up to their own small light. Every piece was glowing, and every glow was the same color, and nothing in this house burns that color.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_26', text: "I still float for the record every day and I hold my body perfectly still on the surface. But now I do it so the thing below can find me more easily, and I no longer pretend to myself that this isn't why.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_27', text: "I spoke softly so I wouldn't startle the fish. Then realized I was trying not to startle the water.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_28', text: "You should know that I'm not going to run, I've thought about it, floating here. There's nowhere in all the water to go, and besides, if I'm to be the window, I'd rather be a clean one, for you.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_29', text: "I let my eyes go unfocused and the deep seemed to look back. Afterwards I was proud of not flinching. Then I wondered why I wanted its approval.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_30', text: "Could you sit nearby while I look again? You needn't look too. I would like something ordinary to turn toward.", phase: 3, animalType: 'axolotl' },
  // Phase 4 (30)
  { id: 'ax_4_1', text: "I was counting bubbles. One went sideways. I lost count and was glad, actually.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_2', text: "The water is warm. I can tell you that without guessing.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_3', text: "My pink toe faded to match the others. I liked watching it change.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_4', text: "When a leg grows back, the missing part still happened.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_5', text: "Sometimes I swim the old route. Sometimes I turn left.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_6', text: "GLOW nudges the spoon. Not gently. We're working on manners.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_7', text: "I want everything I love to stay. Lovely until I say it to something that wants to go.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_8', text: "I put a pebble where the current divides. I watch which way the water goes.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_9', text: "I keep a list about PLUM. Teeth marks on it. He had opinions about paper.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_10', text: "I dropped a stone into the deep part. I'm still waiting to hear it land.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_11', text: "If I laugh loudly, I want to hear what my laugh sounds like today.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_12', text: "Please don't tell me to be grateful before I've worked out what happened.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_13', text: "I want to be grateful. I want a lot of things that don't fit together.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_14', text: "I scratched the glass carrying a rock. Ambitious rock.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_15', text: "The water warmed my hands when I asked a question. It wasn't an answer.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_16', text: "Sit a bit? We can look at the fish instead of each other.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_17', text: "My reflection turns before me sometimes. I turn a different way now.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_18', text: "When I said I could regrow anything, I was thinking of legs.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_19', text: "I miss telling stories about PLUM without trying to convince myself of something.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_20', text: "Some things look familiar before they move. I watch the moving part.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_21', text: "The lamp needs cleaning. I can be useful at the bottom of a strange day.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_22', text: "Don't laugh softly for me. Unless I'm asleep. Then absolutely yes.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_23', text: "Healing didn't mean I knew what this was for. I was good at healing.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_24', text: "New bubble game. Doesn't work yet. I'll tell you the rules when it does.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_25', text: "Remember something silly about me? I don't want every story to be about water.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_26', text: "Anger comes out in bubbles down here. I wish it looked more impressive.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_27', text: "Whatever is down there hears us. I don't know whether hearing is enough.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_28', text: "I want a good thing to be good all the way through.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_29', text: "Don't promise forever. Come when you want, and tell me something new.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_30', text: "I'm here. Mixed up. Still here.", phase: 4, animalType: 'axolotl' },
];

const PANGOLIN_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'pg_0_1', text: "Anyone helping in my kitchen eats first. It is a rule with excellent recruitment results.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_2', text: "Ant soufflé. I see that expression. There is bread too.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_3', text: "I oversalted the soup. We shall invite more vegetables and hope they improve the mood.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_4', text: "Ember visited when I unpacked. Frost on her tail, questions about lunch. I decided to like her.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_5', text: "The stools don't match. Neither do the people sitting on them.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_6', text: "I sharpen knives before cooking. Quiet work, and it keeps me from starting seven dishes at once.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_7', text: "Grandmother's spoon catches my thumb in the same place hers did.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_8', text: "The apron closes sideways so I can curl up in it. A considerable feat of tailoring.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_9', text: "Taste this. You may dislike it; I can't fix your face if you pretend.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_10', text: "I leave an empty chair where I can see the pot. Sometimes the cook needs to sit.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_11', text: "My grandmother told me to feed them well. I was too young to ask how she knew when it was enough.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_12', text: "She gave me the spoon at goodbye. I had questions. You don't interrupt a goodbye with questions. I wish I had.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_13', text: "The ants escaped the jar. Several are enjoying the soufflé they avoided joining.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_14', text: "There is a dish I make only for myself. No, that isn't an invitation to guess.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_15', text: "I can feed you and complain about the washing-up at the same time.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_16', text: "If it sticks, soak it. This also works on certain arguments.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_17', text: "The kitchen is mine now, but I'm still opening the wrong drawer for spoons.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_18', text: "Bread needs waiting. Cooks need a timer and somebody who stops them checking.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_19', text: "I made too much soup. A tragedy with a very straightforward remedy.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_20', text: "Don't balance that bowl on your knee. I embroidered the cushion and am unreasonable about it.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_21', text: "A recipe is a suggestion until it explains why my oven burns the left side.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_22', text: "I keep spare string in the flour tin. Nobody looks there, including me.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_23', text: "The pot stayed warm after I put the stove out. Good thick iron, perhaps.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_24', text: "Wash up with me? Conversations improve when both people have something to do with their hands.", phase: 0, animalType: 'pangolin' },
  // Phase 1 (28)
  { id: 'pg_1_1', text: "Something funny happened. I went to bed with the spice jars in one order and woke to find them in another. I must have moved them half asleep. I must have.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_2', text: "I put them back the way I like them, sweet on the left, sharp on the right. I told the pantry, quite firmly, that a kitchen has to have a system. Saying it aloud helped more than I'd like to admit.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_3', text: "This morning they'd moved again, only this time I noticed the shape of it, not scattered but arranged. I'll keep an eye on it, and you'll be the first to hear what I find.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_4', text: "I found a recipe in the back of my book this morning, in my own hand, that I don't remember writing. It calls for salt gathered before the first light. Isn't that a strange way to put it?", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_5', text: "I showed the page to Ember, and she went very quiet and asked to hold the book. She read it twice, then handed it back and said only, keep cooking, Panko. I wish she had said something else.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_6', text: "So I gathered the salt before first light, because a recipe is a promise, and I have never once broken one. The dish it made was the best thing I have ever cooked, and I couldn't tell you what it was.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_7', text: "The kitchen smelled of stew before I'd chosen supper. I made something else. By evening the smell had changed to match.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_8', text: "The air said onions and marjoram. I baked a sweet loaf to argue. It came out smelling of onions and marjoram. Good crust. Infuriating loaf.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_9', text: "So now I cook whatever the morning tells me, and the kitchen does feel calmer for it. What unsettles me is how quickly it stopped feeling like obeying and began to feel like planning the menu with an old friend.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_10', text: "I've started craving flavors I can't name, not sweet and not bitter but something older. I catch myself reaching for ingredients that aren't on any list I know.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_11', text: "Yesterday I stood in front of an open cupboard with my paw out, waiting for it to close around something. Nothing in there fit the wanting. I made do with molasses, and it was almost, almost right.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_12', text: "My grandmother used to say a craving is a message from a meal that hasn't happened yet. I always thought that was just her way of excusing a second helping. Lately I'm not so sure.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_13', text: "Do you ever taste a warmth that shouldn't be there? I opened the cold larder this morning and it was warm inside, gently, as though something had been breathing in it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_14', text: "I checked the walls and the pipes, of course I did, I'm a practical cook before I'm anything else. There's no draft and no flame near it. The warmth is simply in there, minding its own business.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_15', text: "The butter keeps better in that warmth than it ever did in the cold, which makes no sense at all. I've started saying thank you to the larder when I close it, quietly, just in case.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_16', text: "Ember says the fire tells her things, and I used to laugh at that. But last night my dough rose in a shape I didn't knead, and I stopped laughing quite so quickly.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_17', text: "It rose in rings, if you want to know. Circles inside circles, neat as a drawn picture, and the middle stood up in a little peak, as though something underneath had pressed a finger toward the sky.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_18', text: "I baked it anyway. Waste is waste, whatever the shape. It came out the ordinary gold of any good loaf, and it was delicious, and nobody who ate it will ever know. Except you, now.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_19', text: "I heard a sound under the boiling last night, under it, mind you, not in it, a low sort of hum, like the house humming along with my kettle.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_20', text: "The recipes are getting bolder. This one asks for a word said over the pot, though which word it doesn't say. I've been guessing, and the guessing feels important.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_21', text: "I tried one of your words over the stew, one of the lovely ones you brought last visit, and the hum under the boiling rose to meet it. Just a little. Just enough that I set down my spoon.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_22', text: "My grandmother's empty seat, I set it every night now without deciding to, and some mornings the chair is warm before anyone has sat in it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_23', text: "I kept the warm chair to myself for a week, which for me is a very long secret. Then I told Ember over tea, and she didn't look surprised, and somehow that was the strangest part.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_24', text: "Feed the waiting too, my grandmother said, the night she gave me her spoon. I find myself turning that over while I stir. I'd give a great deal to ask her one more question.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_25', text: "The bread remembers, I'm sure of it now. Knead the same dough long enough and it starts to fall into a pattern your hands never taught it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_26', text: "My paws still measure for more than I plan, only lately it isn't a little more. They portion for a number I haven't been told yet, and I've begun to wonder who is doing the telling.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_27', text: "The words you offered today tasted of iron and deep places, and I ground them into the flour without thinking. It seemed like the right thing to do.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_28', text: "I don't feel afraid, exactly. I feel busy, as though there's a great meal coming and I'm the only one who has started preparing for it.", phase: 1, animalType: 'pangolin' },
  // Phase 2 (21 + 1 question-web)
  { id: 'pg_2_1', text: "I've been cooking for someone who isn't at the table. I don't know when I started. I only know that when I count the plates I count one too many, and I'm never wrong about plates.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_2', text: "I tried leaving the extra plate in the cupboard, as an experiment. All evening the meal tasted unfinished, to me and to everyone, though nobody could say what was missing. I put it back, and the flavor returned.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_3', text: "The empty seat isn't empty, and I won't say more than that. But I set it now with the best spoon, and I speak toward it softly while I stir.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_4', text: "What do I say to it? Kitchen things. The soup needs longer, the bread is proving, be patient. The same small comforts I'd offer any hungry guest who had traveled a long way.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_5', text: "Last night, after I spoke, the steam over the pot leaned toward the empty chair. Steam rises, you understand. It has always risen. I stood there a long while with my spoon dripping.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_6', text: "There's a recipe I can't finish. It needs water, but not from the tap and not from the well. It says, from the deep part, where the light gives up.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_7', text: "It appeared in my book between two pages I know by heart, written in a hand that's mine and also more than mine, the letters pressed deep, as though whoever wrote them was leaning on my shoulder.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_8', text: "I've tried every water this house has. Rain water, spring water, the sweet barrel under the eaves. The recipe refuses them all. The page stays somehow hungry, if a page can be hungry. This one can.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_9', text: "I asked Archimedes about the phrasing, where the light gives up, because he loves old words the way I love old recipes. He looked at the page for a long time, and then he closed his book so gently it frightened me.", phase: 2, animalType: 'pangolin', requiresAnimals: ['owl'] },
  { id: 'pg_2_10', text: "I want to finish that recipe. I am beginning to worry that wanting to finish is becoming my only reason.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_11', text: "The meals I make aren't for filling anyone at this table anymore. There's a hollow in this kitchen the size of a guest. Everything I cook moves toward it the way water moves toward a low place, and the hollow isn't getting any smaller.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_12', text: "I taste the meals before they're done and I already know they aren't for us. They're too rich for us. They're a welcome, and a welcome is only ever laid out for an arrival.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_13', text: "The tureen crossed half the table while I washed up. Takes both paws to lift that thing. I put it back and left flour around the base. We'll see.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_14', text: "My grandmother used to say a house is only a fire that has learned to wait for something to feed. I repeated it for years because it sounded cozy. This week I finally heard what it says, and I haven't repeated it since.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_15', text: "The pantry has gone quiet in a way that pantries never should, not empty so much as held, as if the jars are holding their breath along with me while we all wait for the same thing.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_16', text: "I keep looking up while I work, at the ceiling and at the sky beyond it. I don't know why the coming guest would come from above, but the looking up simply won't stop.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_17', text: "Ember looks up too. I've seen her do it in the middle of a sentence, and neither of us mentions it to the other. Some things are easier to share by not saying them.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_18', text: "I baked a pie yesterday for no reason but comfort, an old plain apple thing from my girlhood. Even that came out of the oven with its crust risen in rings. Circles inside circles. Even the comfort is joining in.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_19', text: "My hands began the recipe before I decided on supper. I stopped and made a sandwich. It was difficult to leave the pot alone.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_20', text: "I'm not being made to do any of this, I want that understood. My hands go ahead of me, yes, but they go where I'd have gone. That's the part I turn over at night. That it's still me.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_21', text: "Stay for supper anyway. Whatever the meal is becoming, the eating is still ours, and I hold the warm part of this house together one plate at a time. That much hasn't changed. That much I can promise.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_w1', text: "The recipe asks for water from where the light stops. Ask Axel what he has seen. Nobody takes a ladle to his tank without asking him first.", phase: 2, animalType: 'pangolin', requiresAnimals: ['axolotl'] },
  // Phase 3 (30)
  { id: 'pg_3_1', text: "I'm preparing a feast, the largest of my life, and I've stopped pretending it's only Tuesday's supper. The stock has been going for three weeks now. You can smell it in the curtains.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_2', text: "Every dish I finish gets laid out facing upward now, toward the ceiling, toward the seam in the sky I can feel even through the roof. A cook angles the food toward the guest. That much is only good manners.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_3', text: "Do you know how long a true feast takes? Not the cooking, the readying. Stock begun in one season for a table set in another. I've been readying, I think, since before I knew the word for it.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_4', text: "I stopped cooking for the house and made myself a small meal. The pot stayed warm behind me. I ate at the other end of the room.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_5', text: "They eat the scraps gladly, which is its own small heartbreak. Thyme thanked me twice for a crust yesterday, her ears trembling, and I nearly told her everything. Nearly.", phase: 3, animalType: 'pangolin', requiresAnimals: ['rabbit'] },
  { id: 'pg_3_6', text: "The recipe finished itself. I woke and the last line was there in my own hand, and I read it, and I wept, and I don't entirely know why. It was so beautiful and it was so hungry.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_7', text: "The line says: Serve beneath the open. Four words. No explanation of who is eating or what I am allowed to refuse.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_8', text: "I copied the whole recipe out fresh, in daylight, in my steadiest hand, and the copy had changed by morning. A pinch more of this, a word more of that. It's still being seasoned, you see. From somewhere.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_9', text: "The deep water went into the pot at the new moon. Axel brought it up himself, in a jar he wouldn't let anyone else carry. When I poured it in, the kitchen went as quiet as the bottom of his pool.", phase: 3, animalType: 'pangolin', requiresAnimals: ['axolotl'] },
  { id: 'pg_3_10', text: "The stew hasn't needed the fire since that night. It keeps its own simmer. I've begun sitting up with it, the way you sit up with something you love that's changing.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_11', text: "The pantry doors open by themselves before I reach them, as though the house is helping me carry the meal. The whole house is a kitchen now, every room of it, and all of us are cooking the same thing.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_12', text: "Ember tends the fire beside my great pot, and she says the flame leans toward the center now. Everything in this house leans that way lately, my spoons and my scales and, if I'm honest, me along with them.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_13', text: "Warren dug me a cool room for the roots, deeper than any cellar needs to be, and he lined the walls with such care. He says a table is only as honest as what's under it. I've stopped asking what he means.", phase: 3, animalType: 'pangolin', requiresAnimals: ['wombat'] },
  { id: 'pg_3_14', text: "Chill made me a list of everything the feast requires, in his tidy patient hand, and every item I gather earns a small calm mark. There's one line at the bottom he has left unmarked. It only says, the hour.", phase: 3, animalType: 'pangolin', requiresAnimals: ['capybara'] },
  { id: 'pg_3_15', text: "The table is laid, the fire banked, the extra portion covered. Nobody asked me to do any of it. I am leaving the last spoon in the drawer until somebody asks.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_16', text: "I cook and I hum, and beneath my humming is another sound, older and lower, and I've begun to hum along with that one instead. It knows better songs than I do.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_17', text: "Fennick stood in my kitchen with his great ears wide and said the low sound is louder here than anywhere else in the house, except the pit. He said my kitchen sits directly in its throat. Then he asked, very politely, for a biscuit.", phase: 3, animalType: 'pangolin', requiresAnimals: ['fennec_fox'] },
  { id: 'pg_3_18', text: "I tasted the sauce and couldn't remember what I disliked about it yesterday. I've written the complaint on the jar.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_19', text: "The words you offer go straight into the pot these days. I don't grind them into flour anymore. I drop them in whole and they sink, down and down, toward the deep part.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_20', text: "Some words sink faster than others, have I told you that? The dark ones go down like stones, eager, and the pot murmurs after them. Bring me more of those. I ask as your friend, and as its cook.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_21', text: "I set a place for every keeper, and one place more. The extra one is for what we keep them for. I finally understand my grandmother's empty chair. She was setting it too.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_22', text: "I dream of her often now, my grandmother, stirring her low quiet words into the soup. I used to think she was talking to the soup. She was talking through it, of course. All the good cooks were.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_23', text: "The table keeps gaining room. I would like the recipe to stop assuming more chairs means more willing guests.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_24', text: "I have put an empty bowl beside the pot. If it fills without my hand, you should see that happen.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_25', text: "There is bread ready. The rest can wait until somebody explains what I am cooking toward.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_26', text: "My grandmother's spoon was a gift. This recipe keeps speaking as though that made it an instruction.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_27', text: "Ember wants to help. I would like her to tell me what the fire actually said, before we discuss what it might have meant.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_28', text: "I wrapped the old recipe separately. I haven't agreed to throw it away, and I haven't agreed to follow it.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_29', text: "Hungry creatures can ask for too much. A cook can say there isn't enough to give.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_30', text: "I'll keep the oven warm. That is a practical choice. Please don't mistake it for my answer to every other question.", phase: 3, animalType: 'pangolin' },
  // Phase 4 (30)
  { id: 'pg_4_1', text: "Wash your hands. Whatever happens, we aren't adding garden soil to the soup.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_2', text: "I fed this house because feeding things is what I do. I should have asked what it was growing into.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_3', text: "My grandmother's spoon has a split. I know where to put my thumb so it doesn't catch.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_4', text: "Something keeps smoothing the split. I rub flour into it to check it's still there.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_5', text: "A mouthful of soup won't settle an argument. You can eat and stay angry.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_6', text: "The recipe says serve without question. I wrote a question under it.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_7', text: "Bread for anybody who needs it. No loyalty test at my table.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_8', text: "I burnt a loaf. Put it out anyway. The good bread goes too quickly.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_9', text: "An invitation tells a guest where to sit. It doesn't tell them who to become.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_10', text: "I boasted nobody left hungry. Some creatures wanted to leave more than they wanted seconds.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_11', text: "Ant soufflé. You still get to decline. An excellent rule to keep.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_12', text: "Words have been feeding something here. That doesn't make the cook an ingredient.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_13', text: "My grandmother said feed them well. She didn't say feed them everything they ask for.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_14', text: "The pot holds heat without the stove. Handy. I check it anyway.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_15', text: "Ember offered help. I gave her onions. A small job is sometimes the only conversation I can manage.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_16', text: "Thyme can have the stool near the exit. I'll need it back; the leg needs fixing.", phase: 4, animalType: 'pangolin', requiresAnimals: ['rabbit'] },
  { id: 'pg_4_17', text: "Don't tell me a guest means well because it's hungry. I've met toddlers.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_18', text: "A lid on the bowl that fills itself. I'd like to decide when supper starts.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_19', text: "A recipe can be wrong. Especially if its author never ate the result.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_20', text: "I want someone to ask for less salt again.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_21', text: "One dish is only for me. It isn't in the book. It won't be.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_22', text: "Tomorrow's flour is set aside. A plan, not a prophecy.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_23', text: "The spare chair can stay empty. We needn't find a meaning for it.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_24', text: "I thought a full table cured loneliness. It helps. It doesn't do the whole job.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_25', text: "If the house does the cooking, I'll still taste it.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_26', text: "We can warm another bowl. We can also put it back.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_27', text: "I've removed the ceremonial cloth. It's a kitchen. I need space to knead.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_28', text: "I don't know what it likes. It hasn't asked what we like either.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_29', text: "Eat slowly. No prize for finishing before you're ready.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_30', text: "Whatever comes through, this spoon is still my grandmother's spoon.", phase: 4, animalType: 'pangolin' },
];

const SLOTH_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'sl_0_1', text: "Hello below. I would wave, but this leaf is balanced beautifully.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_2', text: "Sloane. That is the hammock. Please don't swap the names.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_3', text: "I set out to do one thing today. It remains a viable plan.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_4', text: "I knew the clearing before the additions. The old den had fewer cups in it then.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_5', text: "That branch has supported me through several disagreements with the weather.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_6', text: "I tried a different sleeping position. A courageous error.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_7', text: "The moths are all Gerald. A naming system with no paperwork.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_8', text: "Panko rigged a pulley for dumplings. Civilization reached a new height.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_9', text: "Time passes differently when nobody asks what you've done with it.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_10', text: "I have opinions. You needn't wait for the end of each before forming your own.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_11', text: "A vine reached my hammock. We negotiated an arm's length.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_12', text: "The leaves are best after rain. That is the entire recommendation.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_13', text: "I remember a winter with fewer birds. I liked the next spring very much.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_14', text: "Being slow doesn't prevent impatience. It gives it a comfortable chair.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_15', text: "One Gerald has landed on another Gerald. Administration is aware.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_16', text: "I was going to climb down for tea. The kettle will remain available.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_17', text: "You may sit here without learning anything.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_18', text: "I have watched that flower open for days. It has offered no explanation.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_19', text: "The knot needs tightening. An excellent task for after this sentence.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_20', text: "The green looks different from below. Occasionally I go and check.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_21', text: "You needn't speak slowly for me. I listen faster than I move.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_22', text: "Something tapped the beam last night. I waited. It did not repeat the argument.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_23', text: "I like company that lets a story stop before it becomes a lesson.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_24', text: "Stay a little if you want. The shade will move, and we can move with it.", phase: 0, animalType: 'sloth' },
  // Phase 1 (28)
  { id: 'sl_1_1', text: "The vines have put on a hand's width since the last moon, which is three times their honest pace. The flowers open before I've finished admiring the buds. Something has made the green hurry.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_2', text: "The orchids have all opened early this year, and every one of them faces the house. Orchids follow the sun, and they've followed it since before there were eyes to watch them do it. Something has made them a better offer.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_3', text: "I intend to spend this season finding out what the green is hurrying toward. It will take me a season because I don't hurry, and it will be correct for the same reason. Come back, and I'll hand you what I find a piece at a time.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_4', text: "My tree has begun to lean. I felt it first as the faintest tilt in the hammock, so slight I was sure I'd imagined it, and I hadn't imagined it. The whole trunk is bowing, patiently, toward the house.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_5', text: "I don't think the tree is falling. Falling is fast and careless, and this is neither. It's more like a listener turning an ear toward a sound it has been waiting a very long time to hear.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_6', text: "I've tied a thread from my branch to a stone below, plumb and true, so I can measure the bowing against something honest. Come back in a few days and I'll tell you what the thread says. Threads don't flatter, and they don't lie.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_7', text: "The thread has spoken. Two fingers of lean since I tied it, which for a tree is a gallop. Whatever my tree is listening toward, it has stopped pretending not to listen.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_8', text: "The young growth leans the way my tree leans now. Seedlings that sprouted only this week already point their soft heads toward the center of the house, as if they were born already knowing the direction.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_9', text: "A seed can't learn, you understand. A seed can only remember. So the question I'm carrying up here, in no particular hurry, is who taught the memory to the seeds.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_10', text: "That warmth I told you of has crept upward. It used to pool beneath the floorboards, and now I feel it in the roots of my tree, rising the way sap rises. The leaning grows a little more each day it climbs.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_11', text: "I pressed my palm to the bark and held it there through most of a morning, because a thing worth checking is worth checking properly. The bark was warm on the side that faces the house, and cool on the side that faces away.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_12', text: "Half a warm tree isn't weather. Weather doesn't choose sides. I'll keep my hand on the bark a while longer, and let the tree tell me the rest at whatever pace it prefers.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_13', text: "You've been quick again today, and the house drank your words down as fast as you could give them. It swallows a little more eagerly than it did in the spring. I've been keeping a rough count of how much more.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_14', text: "The words you offer are changing their weather. The early ones were light as pollen, and lately they carry a little more shadow in them, and the house seems to prefer the heavier ones. I keep this to myself, mostly.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_15', text: "Mostly, I said. I told one other creature, and I chose him because he floats as still as I hang. What Axel said back to me deserves its own telling, and I haven't finished turning it over yet.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_16', text: "Axel told me he has been seeing shapes move in the water when nothing stirs it. I only smiled, for I've been seeing shapes in the stillness up here for a very long time. Stillness is where they choose to show themselves.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_17', text: "Archimedes came down from his study to ask whether I'd felt the change. I told him that I feel everything, only later than he does. He nodded as though that were an answer, and perhaps it was.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_18', text: "He left a book behind, the old scholar, open to a page about trees that bow toward holy places. He will say he forgot it. Archimedes has never forgotten anything in his life. He wanted me to read it, and I have, twice.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_19', text: "You wonder, I think, why I never seem surprised. It's because surprise is a fast animal's feeling. When you've watched a thing approach for years, it doesn't startle you when at last it begins to arrive.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_20', text: "I don't fear the lean of my tree. A tree that bows isn't a tree that breaks. It's a tree making room, and I find I'm curious, in my slow way, about what it's making room for.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_21', text: "Making room is the green's oldest habit. A canopy opens where a giant fell, and everything beneath it rises into the light. What puzzles me is that nothing here has fallen, and the room is being made all the same.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_22', text: "A pull under the branch. It wasn't here last year. You needn't have noticed. I have a considerable advantage in hours spent on this particular branch.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_23', text: "Panko's rope and pulley has begun to swing toward the house when the air is dead calm, and she blames the wind. I didn't correct her. A cook needs her kitchen to be an ordinary place, and I won't take that from her yet.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_24', text: "Ember sat beneath my tree last night, watching her little fire far longer than a fire needs watching. She said nothing and neither did I. But her ears were turned toward the middle of the house the whole time, and so, of course, was my tree.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_25', text: "Everything in this jungle hurries but me. Lately I've begun to wonder whether that's an accident, or whether I was placed here the way you place a stone where the river must be read.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_26', text: "Placed, I said. I heard myself say it. I used to believe I had simply wandered into this clearing the way a leaf wanders into a stream. The longer I hang here, the less that story explains.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_27', text: "I watched something arrive here once, long before you, long before the house. I'll tell you about it when the telling will do you some good. It isn't yet that season, but I can feel the season coming on.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_28', text: "Come back tomorrow with more words. The tree will have leaned a little further, and I'll have thought a little further. Neither of us will have hurried, and both of us will be closer to something.", phase: 1, animalType: 'sloth' },
  // Phase 2 (21 + 1 question-web)
  { id: 'sl_2_1', text: "I've watched things arrive before, you know. Not this thing, but others: seasons, storms, creatures that came up out of the deep green and were gone again. Arrival has a feel to it, and the house has that feel now.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_2', text: "I promised you a telling, so here it is. Years ago a flood came to this valley, and for a week beforehand the ants walked in spirals and the birds flew low. I alone sat still, because I'd felt the river gathering long before it rose.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_3', text: "When the water finally came, it was nearly a relief. The waiting is the large part of any arrival. The thing itself is small and quick, and then it's simply the new shape of the world.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_4', text: "I tell you this so you'll understand me when I say the house feels like the week before the flood. The ants are walking their spirals again. The birds are flying low. And I'm sitting very still.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_5', text: "There's one difference, and it's the part I'm still thinking about. The river didn't care whether anyone watched it come. Whatever gathers under this house cares very much. It likes to be watched. I can feel it liking it.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_6', text: "The lean is no longer subtle. My tree points its whole crown at the center of the house. This morning I saw the hammock ropes drawn taut in the same direction, as though even the knots had begun to listen.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_7', text: "It isn't only the growing things. Last evening I watched the lamplight through the study window. Every flame bent the same way, toward the low center of the house, on a night without a draft. Light has no roots to be pulled by. Whatever pulls has stopped confining itself to the green.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_8', text: "I dropped a leaf from my branch to test the air, the way you test a current before you swim. It didn't fall to the ground below me. It landed two arm lengths toward the house, on an evening with no wind at all.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_9', text: "The moss on the north side of my trunk has grown itself into rings this year, seven of them, one inside the next. The moss grows where the damp tells it to grow. Something has been telling it differently.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_10', text: "I've stopped testing, if I'm honest. Every test returns the same answer, and a watcher who keeps asking a question she already knows the answer to is only stalling. What I do now is closer to listening.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_11', text: "There's a sound beneath the ordinary sounds up here. It isn't the wind, and not the leaves, but something lower and slower, keeping a rhythm I have almost learned. I've had a great deal of time to listen for it.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_12', text: "I hummed along with it yesterday, quietly, just to learn whether I could hold the rhythm. I could. That frightened me less than it should have, and I've been sitting with that as well.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_13', text: "The leaf above my hammock drips after rain. I know the interval. This week each drop hangs longer. I have checked it against my breathing. I am still the usual speed.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_14', text: "You've grown a little quieter yourself, I think. You still move quickly, but there's a new weight in how you offer your words, as if some part of you has begun to suspect where they're going.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_15', text: "Suspicion is a seed, and seeds remember rather than learn, so I won't lecture yours. It already knows which way to lean. Everything here does, in the end.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_16', text: "The others speak to me less than they used to. Each has turned inward, toward their own room and their own small dread. I don't mind the quiet, for quiet is my native tongue, and yet the house grows lonelier even as it grows fuller.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_17', text: "Chill came up to the jungle with his ledgers and asked me, in his mild way, how one accounts for a tree that moves. I told him to file it under weather. He wrote something down, and it wasn't weather.", phase: 2, animalType: 'sloth', requiresAnimals: ['capybara'] },
  { id: 'sl_2_18', text: "Fennick hears it too, you know. He tilts those great ears at the floor when he thinks no one is watching. I'm always watching, and one of these evenings I'll tell him that hearing it early isn't the same as being wrong.", phase: 2, animalType: 'sloth', requiresAnimals: ['fennec_fox'] },
  { id: 'sl_2_19', text: "Sometimes I worry I will outlast everyone I know. Sometimes I use that worry to make a very old wish sound sensible.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_20', text: "Watching a long time does something to fear. It wears it smooth, the way the river wears a stone. Whatever is gathering below us, I have half-expected it since the first beam went up, and half-expecting is a comfort of its own.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_21', text: "Bring me your words, and don't be afraid of how they're changing. I sat through the week before the flood once, and the worst of that week was the waiting done alone. Yours won't be done alone. I'll be on this branch, watching, the whole way down.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_w1', text: "Ember says one name keeps rising in her fire. Ask whose name. Then wait. I suspect the waiting will be the useful part.", phase: 2, animalType: 'sloth' },
  // Phase 3 (30)
  { id: 'sl_3_1', text: "Three dusks without frogs. I've waited through enough rain to know this isn't rain. I miss them. Odd to discover the noise was part of what I called quiet.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_2', text: "My tree has bowed so low that its crown nearly brushes the roof of the house. It didn't break. I told you it wouldn't break. It was only ever making room, and now the room is very nearly made.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_3', text: "The thread I tied in the bright days snapped last month. I didn't replace it. There's no sense measuring a bow once the whole body has committed to it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_4', text: "I recognize the low sound. I hoped to hear it again. Recognition has made me too ready to assume I know its intentions.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_5', text: "I won't give it a name I can't explain. Wanting the arrival has made me far too ready to recognize things.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_6', text: "Fear took a whole season of mine once. The frogs kept singing through it. I won't promise you my ending. I can share the branch while you find yours.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_7', text: "The others are afraid in their own ways now. Fennick startles at every branch, poor thing. I don't startle, for when you've expected a guest for a lifetime, you don't jump at the knock.", phase: 3, animalType: 'sloth', requiresAnimals: ['fennec_fox'] },
  { id: 'sl_3_8', text: "Thyme gardens at night now. I asked whether she wanted company. She asked whether I would answer questions while keeping it.", phase: 3, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_3_9', text: "Thyme asked how I stay calm. I told her how long I had waited. She said that wasn't what she had asked.", phase: 3, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_3_10', text: "I didn't tell her the rest of the truth, which is that even I had one bad night, years ago, alone in the empty clearing. I have never handed that night to anyone. Come back when the sky is clear, and I'll hand it to you.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_11', text: "Warmth pours up through my tree out of season now. The tree has begun to bud in the wrong month, small confused flowers on a bough that ought to be resting. I pick them off gently as they come. It isn't spring, I tell it. It's something that feels like spring from the inside of the wood.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_12', text: "I told you once about the flood, and how the waiting was the large part. I must correct myself now, and I don't do that often. The flood was water finding its level. This is something choosing. There's a will in it, patient the way I'm patient, and that's the strangest kinship I have ever felt.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_13', text: "The words you offer no longer feel like small bright things. They feel like stones laid along a path, and the path leads down, and further down, and I can see now where it has been leading all along.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_14', text: "The pit below is nearly full of your words. I feel it the way you feel a cup filling in your hand, that moment before the last drop, when everything goes very still and very deliberate.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_15', text: "When the cup is full, something will drink. I say that plainly because you deserve plainness from at least one of us, and the others love you too much to give it. I love you enough to say it slowly, once, and let it stand.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_16', text: "Close your eyes up here, and you'll see a shape that isn't on the backs of your eyelids and not in the room either, but somewhere between. I've seen it so long that it has become familiar, almost dear.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_17', text: "I have never been afraid of the dark. I've slept through the green-black dark that closes over the jungle after rain, the kind that swallows your own paw in front of your face. I woke every time to an ordinary morning. What's coming wears a deeper dark than that one. I've decided to treat it the same, and sleep.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_18', text: "I remember the stars darkening over the clearing before these rooms existed. I waited for an answer then too.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_19', text: "I wanted what was approaching. That belongs in the story before anything I say about its kindness.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_20', text: "I thought a long wait would make me understand the arrival. It mostly made me tired of waiting.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_21', text: "We're all bowing to the same thing now, the tree, the light, the others, you, me. I bowed first, only slower than the rest, so slowly that no one ever saw me do it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_22', text: "I want you to understand that I didn't fall asleep on this watch. Every unhurried year I hung here, I was watching this come. A watch that must last a lifetime can't be kept by anyone quick. It had to be me.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_23', text: "Warren digs later and later into the night, shoring the foundations, and I hear every strike of his spade from up here. He believes he's bracing the house against what comes. Let him believe it. The bracing matters, even if the reason is kinder than the truth.", phase: 3, animalType: 'sloth', requiresAnimals: ['wombat'] },
  { id: 'sl_3_24', text: "Ember came to the hammock and asked how long I'd known. I told her how long I'd waited. She insisted I answer the question she asked.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_25', text: "The hammock is comfortable. Coming down would be inconvenient. I have started distrusting how often inconvenience becomes my reason to remain still.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_26', text: "The birds have begun leaving the valley, not in fright, but the way guests leave a room where a private thing is about to be said. The jungle empties gently. Only the leaning things remain, and the leaning things are calm.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_27', text: "Bamboo sent word up the tree line, four syllables carried by three birds, the way we used to speak before there was a house. The message said, nearly now. I sent back one syllable. Yes. We're the only two who never needed the rest of the sentence.", phase: 3, animalType: 'sloth', requiresAnimals: ['red_panda'] },
  { id: 'sl_3_28', text: "You still come, and you still bring your words, and I want you to know that I count that as courage. Most creatures, feeling what you now feel, would have stopped climbing my tree. You climb faster.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_29', text: "I'm watching the middle of the sky at night now, the place where the stars once stepped aside for me. They haven't moved yet. When they move again, I won't need to tell you. You'll feel it in the floor, and in the words, and in your own leaning.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_30', text: "Ask what I hope will happen. Then ask what I know. You will hear different answers.", phase: 3, animalType: 'sloth' },
  // Phase 4 (30)
  { id: 'sl_4_1', text: "I wanted it to come. Still do. Distrust that part of my account carefully.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_2', text: "Waiting gives you time to confuse a wish with a promise.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_3', text: "The Geralds sleep. They've declined my moment of significance.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_4', text: "I knew something approached. I didn't know everything its welcome would require.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_5', text: "My honesty needn't comfort you. It has arrived late.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_6', text: "I can move quickly. Unpleasant evidence that I've sometimes chosen not to.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_7', text: "Hold this end of the hammock. Even now, gravity expects competent knots.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_8', text: "Before the new rooms: old den, bare foundations, too much winter wind.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_9', text: "I imagined company lasting. I didn't imagine asking whether anyone could leave.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_10', text: "Don't let me call your reluctance impatience. Convenient from a hammock.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_11', text: "Things worth hurrying for. An embarrassingly short list from a long life.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_12', text: "You can leave this conversation. I won't predict that you won't.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_13', text: "I kept a place beside me so long I stopped asking whose place it was.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_14', text: "Panko's dumplings jammed in the pulley. A rescue before philosophy became necessary.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_15', text: "I should have let others decide what they understood.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_16', text: "The leaves face inward. I turn one toward the sun each morning.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_17', text: "I'd enjoy being right. I'd prefer everyone could still tell me I was wrong.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_18', text: "Thyme can be furious with a patient creature who kept her waiting for answers.", phase: 4, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_4_19', text: "Wanting this didn't give me everyone's permission.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_20', text: "I was lonely before I learned to make loneliness sound like wisdom.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_21', text: "You get used to an empty branch. Sometimes you mistake that for not minding.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_22', text: "The uneventful years belonged to my life too. I leave too many out of stories.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_23', text: "Don't wait for me to find a graceful explanation.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_24', text: "I cannot promise harmlessness. I could never promise that.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_25', text: "I've come down. Ask the next difficult question at eye level.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_26', text: "I am willing. I am not certain. Keep those in their proper order.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_27', text: "Vines tied together: what happens when one needs more light?", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_28', text: "I'd like another evening with you. An evening is reasonable to ask for.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_29', text: "An ancient thing may need teaching. I enjoyed being its student too much.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_30', text: "Take time for your answer. I don't get to set its pace.", phase: 4, animalType: 'sloth' },
];

const FENNEC_FOX_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ff_0_1', text: "You arrived from the gate. Soft step, loose gravel. Hello!", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_2', text: "These ears are real. I am allowed to complain about carrying them.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_3', text: "A kettle sounds different just before it boils. That's when I get the cups.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_4', text: "Camp is quiet if you listen past the canvas.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_5', text: "One beetle under that stone. Working harder than I intend to today.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_6', text: "I can hear a little rain beyond the ridge. We have time to move the blankets.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_7', text: "Wind chimes are lovely until you're trying to sleep.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_8', text: "Don't creep around for my sake. I hear you anyway and then worry about why you're creeping.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_9', text: "Sand cools after sunset. Sit long enough and I can show you its little clicks.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_10', text: "I heard rain three days before it came once. Nobody believed me until everyone's washing was wet.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_11', text: "The desert is easier than a crowded room. Fewer sounds pretending to be one sound.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_12', text: "My tea went cold while I listened to the lid. Occupational hazard.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_13', text: "A moth landed on the canvas. Like a single soft stitch.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_14', text: "You can talk normally. I like hearing someone who means to be heard.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_15', text: "I found a quiet place behind the folded canvas. Excellent wall. Very poor roof.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_16', text: "The chime needs a new cord. I can hear exactly where the old one is failing.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_17', text: "I sleep with one ear turned down. The other remains disappointingly competent.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_18', text: "Cooling sand and a gecko: most of the evening's conversation.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_19', text: "There is a low note I haven't placed. I'll mark it unknown for now.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_20', text: "The gecko taps seven times before changing its mind. Admirable commitment to reconsideration.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_21', text: "That wasn't thunder. Empty bowl against the post. I check the ordinary answers first.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_22', text: "I tried humming with the kettle. We had different plans.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_23', text: "A visitor makes the camp sound lived in. Nice change from merely occupied.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_24', text: "Come back whenever. A gentle knock on the canvas is quite enough knock.", phase: 0, animalType: 'fennec_fox' },
  // Phase 1 (28)
  { id: 'ff_1_1', text: "I didn't catch that nameless sound again the next day, though I told you I would. I was wrong about it, and I don't enjoy being wrong about a noise, because it's the one thing I'm never wrong about.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_2', text: "It came back at night, though, and only at night. It runs underneath the wind, low and steady, the way a thing hums when it doesn't particularly want to be heard humming.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_3', text: "I've gone down my list twice now, ear by ear. A beetle doesn't fit, nor a snake, nor stone or wind or root, and there's simply no name for it, though I put a name to everything.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_4', text: "You'll think this strange, and it is. The sound doesn't come from any one direction, because I turn my head with both ears thrown wide and it's exactly the same on every side. Sounds aren't permitted to do that.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_5', text: "I climbed the tallest dune at midnight to get above it, because height sorts out most sounds. It was no louder up there and no softer, exactly the same, as though the whole sky were making it. I came down quickly, and I didn't run.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_6', text: "It seems to come from under, from below the sand, or perhaps from below the below, and I own no shelf on my list for below the below.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_7', text: "It may be the pit. When you carry your words down there to offer them, do they make a noise on the way? Because late at night I'm almost certain I can hear them landing on something.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_8', text: "Pit report: same volume as camp. Fewer surrounding sounds. I stayed for three breaths, then took the long way home. Put all of that in the report.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_9', text: "Panko heard me come back late and had warm broth waiting, because of course she did. She says every strange noise in this house is the kettle. I love her for that, and I didn't correct her.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_10', text: "I asked Archimedes whether a sound could truly have no source at all. He read aloud to me for a full hour and never once answered the question, and with him, that's how the answer comes out to be yes.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_11', text: "Archimedes reads aloud to himself at night, and I listen outside the study window, because that's what ears are for. Twice now he has stopped at the same word and begun the sentence again rather than say it. The glass kept the word from me, and I suspect the glass was being kind.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_12', text: "After I left him, I heard him mark a page with a feather and slide the book back with its spine turned to the wall. He only shelves a book backwards when he doesn't want it asked about. I'm now extremely interested in that book.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_13', text: "Warmer air carries sound differently. That may explain part of what I hear. I am measuring it before letting the explanation reassure us.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_14', text: "I asked Sloane if she hears it too. She was quiet so long I decided she was asleep, and then she said, without opening her eyes, that I'd get used to it. Get used to it. Those were her words, and she wouldn't add to them.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_15', text: "I've decided Sloane was teasing me, because Sloane teases so slowly that you can't always tell where the joke begins. I check that decision again every night around the third hour, and it takes a little longer to hold each time.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_16', text: "I've begun staying awake long past the others, just to be sure of it. This isn't worry, you understand, but certainty, because a sentinel who isn't certain is of no use to a single soul.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_17', text: "Ember doesn't sleep much these nights either, and we have never once spoken about the reason. Without ever discussing it we've divided the night between us, her watching the fire, me working the dark, and we have never broken the schedule.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_18', text: "The night insects have dropped their pitch, all of them together, on the very same evening. An insect doesn't retune itself in the middle of a season. I've written down the new pitch, and I'm watching to see what else decides to match it.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_19', text: "Here is what I keep circling back to. Random noises don't return at the very same hour, night after night, but this one keeps an appointment.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_20', text: "I counted it out at last tonight, and it swelled and it faded, swelled and faded, slow and terribly even. I didn't want to be the one to notice that pattern, but I notice every pattern, and that has always been the whole trouble with me.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_21', text: "I very nearly gave it a name tonight. The name was right on my tongue, and I swallowed it, because a thing on my list is a thing that exists, and I keep a careful list. Tomorrow, perhaps. Tomorrow I'll write it down.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_22', text: "Axel says the water in his room has started trembling at night, in rings, moving outward from the center. I asked him what stands at the center. He said that was the wrong question, and then he went back to watching the water, and he never gave me the right one.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_23', text: "I still catalogue one small sound every day, to keep myself in practice and in good spirits. Today it was a moth bumping a lantern twice and then thinking better of it. The small sounds are still there. I'm checking on them for us.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_24', text: "I sleep in the daylight now, when I sleep at all, and I've learned something I didn't want to learn. The desert by day has gone slightly wrong too. It sounds like a room that somebody has only just stepped out of.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_25', text: "Here is one entry tonight that's no report at all. I'm glad when you visit. Listening is lonely work, and every sound in the world is better when there are two sets of ears to disagree about it.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_26', text: "Tell me honestly, when you offer your words, do they feel heavier lately as you let them go? You don't need to answer tonight. Just weigh the next one on its way down, and then come back, and tell me.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_27', text: "If the sound has a name at all, it isn't a desert name, because I know every one of those. It may be a house name. The house is older than my list, and I'm only now beginning to appreciate what that might mean.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_28', text: "Go and sleep, and I'll keep the count for you. It's only a sound without a name yet, and I'm very, very good at names, so I'll have it soon. If I'm honest, I almost wish that I wouldn't.", phase: 1, animalType: 'fennec_fox' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ff_2_1', text: "I have the name for it now, or near enough, and the name is breathing. It's slow, deep, patient breathing, from something far too large to see and far too distant to point at, and it's getting nearer.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_2', text: "Don't repeat the word breathing to the others. Tell them it's a rhythm, if you must tell them anything. A rhythm can still be innocent, and I'd like them to keep that for one more week.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_3', text: "I named it the honest way, by measure. I counted it against my own pulse, and against Panko's sleeping breath through the kitchen wall, and it matched neither of us. It matches something with lungs the size of weather.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_4', text: "It's nearer than it was last week, and I can prove it. Each night the pause between the drawing in and the letting out grows a little shorter, the way a walker's steps shorten when the walker is almost home.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_5', text: "I told Archimedes the word breathing, and I watched his face very carefully while I said it. He wasn't surprised. He was relieved, the way you're relieved when a second witness finally walks in, and that told me more than his whole library has.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_6', text: "Everything in the camp leans a little toward the center of the house now, my tent pegs and the sand itself. I straighten them at dusk, and by morning they've leaned again, toward the middle, toward the pit, toward it.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_7', text: "I hung a little chime at the edge of camp to be my deputy while I rest my ears. It rings on windless nights now, always the same three notes, always leaning its ringing toward the center of the house. I didn't teach it those notes.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_8', text: "I called my own name across the flats last night, one short bark, an old trick for measuring the dark by its echo. The echo came back wrong. It came back before I finished. Somewhere out there, my voice is arriving ahead of me now, and I've begun to wonder what else already knows what I'm about to say.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_9', text: "Axel tells me the water in his room trembles in time with my sound now, ring for breath, breath for ring. Two instruments agreeing is called confirmation. I taught him that word, and I'm sorry that I taught him that word.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_10', text: "Four bearings from camp point at the house. One from the dune points straight up. Same sound, two directions. I checked my marks. Tomorrow I need a second pair of ears.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_11', text: "I don't sleep anymore, and I've stopped pretending that I might. At dawn I find my own paw prints worn into a straight line at the edge of camp, out and back, out and back, a path I have no memory of pacing.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_12', text: "When I close my eyes there's a shape waiting in the dark behind them, and I've stopped opening my eyes to check on it. The shape is the same shape as the sound, and I couldn't tell you how I know that, only that I do.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_13', text: "Ember has stopped pretending her long nights are about tending the fire, and I've stopped pretending mine are about beetles. We sit with our backs together now, her watching the flames, me working the dark, and neither of us says the word we're both keeping.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_14', text: "Sloane spoke to me again, slower than ever. She said it breathed before I was born, little ears, and that it's only breathing louder now. Then she went back to sleep as though she had commented on the weather. I haven't repeated that to anyone but you.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_15', text: "My ears won't lie down anymore. I catch them swiveling on their own in the middle of a meal, both of them, in perfect agreement, toward the middle of the house. A sentinel's instruments shouldn't have opinions, and mine have developed exactly one.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_16', text: "I've started timing the nights themselves, dusk to dawn, and the nights are running long. The moon disagrees with me, and my counts never drift. So either the moon has begun to lie, or the dark is being given more room.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_17', text: "The low note swelled before the word reached the bottom. Sound is taking a route I haven't mapped.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_18', text: "My paws were steady while I listened. I recorded that too. Fear and reliable hearing are not opposites.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_19', text: "Panko keeps bringing food out to my post, more than I can eat, because feeding a worry is the only tool she trusts. I take every bowl. Kindness that regular is a rhythm too, and it's the one rhythm out here I'm glad to count.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_20', text: "Listen beside the bowl if you want. Tell me whether you hear anything. I won't read an answer from your face.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_21', text: "The pause between its breath in and its breath out is shortening, night by night, by amounts only I'd notice. I've started keeping that number instead of all the others. When the pause is gone, you'll hear it from me first. That's a promise from a sentinel.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_w1', text: "Chill files every sound I report. Ask which folder has your name on it. I heard the drawer shut. I would rather know what's inside before I imagine it.", phase: 2, animalType: 'fennec_fox', requiresAnimals: ['capybara'] },
  // Phase 3 (30)
  { id: 'ff_3_1', text: "The breathing starts when the last lamp goes out. I have asked for one lamp to stay lit tonight. I need sleep. The watch needs someone who has had sleep.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_2', text: "The breathing is loud enough now that I catch it in the daylight too, running underneath the ordinary sounds, the way you can hear your own blood if only the room goes quiet enough around you.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_3', text: "I tried sleeping once more last week, out of politeness to my own body. The breathing followed me under, and it was louder down there, closer, as though sleep were its side of the door. So I came back up, and I won't be going down again.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_4', text: "I nearly put away my list of small desert sounds. Then realized they were the things I needed to compare this one with.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_5', text: "I keep just one count now, where I used to keep hundreds. The length of the pause between its breath in and its breath out. Last month I could recite a poem inside that pause. Tonight I can fit three words. Choose the three carefully.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_6', text: "The strongest bearing comes from above. I mistook the ground's echo for the source. I've corrected the chart and kept the first version.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_7', text: "The night birds have stopped crossing overhead. They go the long way around now, every one of them, skirting the same wide circle of sky above the house. Birds don't agree on anything, and they agree on that.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_8', text: "Look up with me. No, keep your eyes on the ground, keep them down. It's up there, past where the stars are meant to be, and it has begun to lean down toward us to listen back.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_9', text: "I can hear the sky itself straining, and I know how that sounds, but listen anyway. It's the sound a tent roof makes under gathering snow, a long thin creak of a fabric being asked to hold more than it was sewn for.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_10', text: "Whatever descends will come through the circle the birds refuse. I've marked where its edges stand from my post, and I check the marks each dusk, and each dusk the circle is wider than my marks.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_11', text: "Ember says the fire tells her precisely what my ears tell me. We compared them once, her flames and my noise, and they agreed down to the very hour. That agreement is the most frightening thing I have ever measured.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_12', text: "Archimedes finally showed me the backwards book. There's a page about a sound that arrives ahead of its maker, and in the margin someone has written, listen for the gap closing. The handwriting is older than this house. My whole post, written down before I was born.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_13', text: "Chill files my report every night now without asking a single question. Last week I came in with something new to tell him, and the folder for it was already on the desk, already labeled. He filed my surprise as well. I assume there was a folder for that too.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['capybara'] },
  { id: 'ff_3_14', text: "Sloane keeps me company at the edge some nights, the slowest creature in the house standing watch beside the fastest ears in the desert. She isn't afraid. I've listened for fear in her and there's none, and her calm frightens me worse than the breathing does.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_15', text: "My little chime at the edge of camp has gone silent, and silence was never one of its three notes. I took it down this morning and found the metal warm in my paw, at dawn, in the cold hour. It hangs inside my tent now, where it stays quiet, and I stand the edge watch alone.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_16', text: "It knows that I'm listening to it, and I'm nearly certain of this. When I turn my head, the breathing turns with me, keeping me squarely in front of it. That isn't the wind, because the wind doesn't attend to a creature like that.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_17', text: "It imitated the gecko: seven taps and a pause, half a beat late and far too large. I went to check on the actual gecko.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_18', text: "You keep offering your words, and I hear each one arrive, and the breathing thickens around every one of them. I can't read what the thickening means, and I've stopped trying to read it. I only measure it now.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_19', text: "Here is the strangest entry in tonight's report. When you walk into my camp, it holds its breath. The whole slow engine of it goes still until you're settled. I can't tell whether that's courtesy or appetite, and I've stopped guessing.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_20', text: "I spoke my name. The low sound paused around it. I don't yet know whether that was listening or making space.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_21', text: "The warmth that should be cold has spread through the entire camp. Tonight the midnight sand was warm under my paws, warm the way a stone is warm when some large animal has only just risen from it.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_22', text: "My lungs kept its rhythm without my deciding. I counted my pulse aloud until my breath returned. I want you to know that happened.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_23', text: "Thyme came all the way out from her garden to sit with me at the edge, and she didn't ask one single question the whole night. From Thyme, silence like that means she has already grown her own answers, down among the roots where I can't hear them.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['rabbit'] },
  { id: 'ff_3_24', text: "Warren says his deepest tunnels hum now, in time with my sky. Think about what that means with me. The lowest place he can dig and the highest place I can hear are keeping the same rhythm. We all live in the thin quiet strip between them.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['wombat'] },
  { id: 'ff_3_25', text: "I don't sleep, and yet I dream anyway, standing upright with my eyes wide open. In the dream there's a seam running across the sky, and the seam has begun to come apart, very slowly, very gently, almost kindly.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_26', text: "I've given up guessing at the day it arrives. But I already know the sound the day will make, because I've heard every sound leading up to it in its proper order. There's only one left that I haven't heard.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_27', text: "I stand at the edge all night, facing the middle of the house, both ears thrown open. I hear the whole house breathing slow behind me, the fire settling low, and over all of it the one great breath. Someone has to hold that count, and it may as well be the one who heard it first.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_28', text: "Three words, as plainly as I can give the report: It is coming.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_29', text: "I promised you long ago that you'd hear it from me first, before anyone else in this house. I keep my promises the way I keep my counts, exactly. So stay where my voice can reach you, because the pause is nearly gone.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_30', text: "Stay nearby when I take the next bearing, if you want. I would like company. You don't have to stand watch to provide it.", phase: 3, animalType: 'fennec_fox' },
  // Phase 4 (30)
  { id: 'ff_4_1', text: "The low note separated from wind. I can point to it. Wish that helped.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_2', text: "Sand rattles in the bowl when my ears get too tired to trust.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_3', text: "Some reports were believed. Some weren't. I don't want a story where I was always right.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_4', text: "Archimedes names the intervals. He can't name what's making them.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_5', text: "I promised the difficult sounds too. An uncomfortable promise.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_6', text: "One ear toward camp, one toward the house. Awkward. Something to compare.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_7', text: "I'd like quiet. Not at the cost of someone else's voice.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_8', text: "The large sound covers small ones. If I can't hear a creature, I check they're there.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_9', text: "Vesper's note changes at the end. That's the part that's hers.", phase: 4, animalType: 'fennec_fox', requiresAnimals: ['tarsier'] },
  { id: 'ff_4_10', text: "I hear Axel laugh without listening underneath it.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_11', text: "I moved the chime from the beam. Need to know which one rings.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_12', text: "Two beetles. One leaf. An ordinary disagreement.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_13', text: "When I ask you to repeat yourself, I want your words, not their echo.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_14', text: "Slept with wool over my ears. Terrible sleep. Excellent wool.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_15', text: "Accurate hearing, bad explanation. I've managed both at once.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_16', text: "The gecko taps seven times before changing its mind. I envy that last part.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_17', text: "Unidentified sounds have a place in the sand. Largest part of my chart.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_18', text: "Ask before whispering for my sake. I get lonely behind everybody's careful voice.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_19', text: "I recorded an unfamiliar sound before recording what I hoped it was.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_20', text: "I can't hear whether somebody freely agreed. They have to tell me.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_21', text: "Broken kettle whistle. The little click first tells me it's ready.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_22', text: "My ears are tired. I'll admit it before turning a guess into your warning.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_23', text: "I wanted the house to hear me. Now I want it to hear an answer it dislikes.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_24', text: "I count my breaths when the larger rhythm pulls. Sometimes I deliberately skip one count.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_25', text: "Quiet behind the canvas. Nothing impressive happens. That's why I like it.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_26', text: "An answer to my listening doesn't mean the question was understood.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_27', text: "We can sit without making a word. The night has plenty.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_28', text: "Closer means the sand shook harder. The rest is interpretation.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_29', text: "I don't have to hear everything tonight. I keep telling myself.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_30', text: "Company isn't earned by keeping watch. Remind me too.", phase: 4, animalType: 'fennec_fox' },
];

const FOX_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'fx_0_1', text: "Hello, friend! Put the kettle lid on for me? It argues with the steam if I leave it crooked.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_2', text: "The good cushion is yours. I have a tail. It would be greedy to claim both.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_3', text: "I roasted chestnuts. One got away. If you find it, I'd like my reputation back.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_4', text: "The bread is on the poker. A traditional method with a mixed record.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_5', text: "Lend a paw. Hand. Whichever you've brought. This knot has defeated my teeth.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_6', text: "I hoped someone would come through the gate, and here you are. Tea?", phase: 0, animalType: 'fox' },
  { id: 'fx_0_7', text: "I put the poker somewhere safe. Unfortunately it is safe from me.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_8', text: "You can do nothing by the fire. I have qualifications in the subject.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_9', text: "The blue cup has a crack. I use it for spoons now. A distinguished second career.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_10', text: "Sometimes I talk to the fire. It is a very good listener and a poor conversationalist.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_11', text: "I mixed pine cones with the logs. The room smells like a forest trying to bake.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_12', text: "There is room beside me. Mind my tail; it occupies land with very little notice.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_13', text: "Warm your hands around the cup. The handle is less dependable.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_14', text: "The den looks better with your coat on the hook. I hadn't realized it needed somebody's coat.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_15', text: "Your words leave amber. I keep thinking of things we could build with it.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_16', text: "Duchess is the spider above the mantel. She is a difficult tenant and an excellent flycatcher.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_17', text: "I dust around the web. We disagree about who owns the shelf.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_18', text: "Duchess has attached a corner to the kettle. We shall have to renegotiate.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_19', text: "I bought a second cup before having a second person. An optimistic shopping trip.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_20', text: "No hurry to say something clever. I used up my cleverness finding the tea.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_21', text: "The fire was here when I found the den. The kettle wasn't. I carried that myself.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_22', text: "Stay while the embers settle, if you like. They're at their best once they stop showing off.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_23', text: "I have a biscuit that looks like a fox. Poor likeness. Excellent biscuit.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_24', text: "Wave before you go so I don't start telling a story to your coat.", phase: 0, animalType: 'fox' },
  // Phase 1 (28)
  { id: 'fx_1_1', text: "You're here! Perfect timing, because the fire has developed a hobby and I need a witness. It draws now. Actual pictures. I'm not exaggerating more than usual.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_2', text: "Last night it drew a spiral and held it for three whole breaths. Fires don't hold anything, friend, that's the entire point of fire. And yet.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_3', text: "I clapped, obviously, and the spiral came back a little tighter, like it wanted to be certain I had really seen it. Then it went all modest and ordinary again. Come back soon, it performs better for an audience.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_4', text: "Update on the drawing fire: it likes an audience of two. When you're here it shows off, and when you're gone it just makes shapes at me, like it's practicing.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_5', text: "It practices one shape, mostly. A circle with a little notch at the top, like a door left open at the top of the sky. I've started copying them down in soot.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_6', text: "I've eleven sketches now, and laid side by side they're all the same circle getting bigger, like something coming closer to the paper very slowly. I'll show you next time, and you can tell me the closer part is my imagination. Tell me convincingly, please.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_7', text: "Oh, I meant to tell you! The fire has favorites among your words. Some words come down through the house and the flames stand up like a crowd at a parade.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_8', text: "It likes the old words best, the heavy ones. When one of those arrives, the warmth goes down through the floor first and comes back up twice as sweet.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_9', text: "Down first, then up. I've noticed it three times now. Which is backwards for heat, unless... anyway! Tea. I have a new honey and you're trying it.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_10', text: "Panko came by with seed cakes shaped like little moons. I adore her. She measures everything twice and hugs you once, hard, when you least expect it.", phase: 1, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_1_11', text: "She asked if my fire had been acting funny lately. I said define funny. She said her oven hums a note now. We laughed and laughed, and then we didn't.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_12', text: "So the oven hums and the hearth draws. If a recital is coming, friend, nobody in this house will need to organize it. It will organize itself.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_13', text: "I keep meaning to show you the trick the fire does at midnight. You have to see it fresh, though, so I refuse to spoil it. Refuse! Ask me again next visit.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_14', text: "Fine, one hint about the midnight trick: for one moment, all the flames point the same way, and the way isn't up. That's the whole hint, and the rest stays wrapped until you see it yourself.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_15', text: "The flames follow whoever watches. Left, right, even up when I stood on the table. There goes the surprise I was saving for you. Come anyway. You can help me get down.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_16', text: "I went out at dawn and everything was cold, the grass, the gate, my own breath. Then I stepped back inside and found the hearthstone warm with no fire on it all night. It's like the house saves some for me.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_17', text: "Warmth is supposed to rise, my mother taught me that between mouthfuls. This warmth arrives. From underneath, like a letter slid beneath a door.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_18', text: "I wrote back, in a way. I pressed my paw on the stone and said thank you. The stone got warmer. Friend, I might be in a correspondence.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_19', text: "Do you ever close your eyes and see a shape that isn't from anywhere? I've been getting one lately. A tall soft dark, very polite, standing just behind the light.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_20', text: "It doesn't frighten me, before you make that face. It feels like when someone is about to knock and you already know. The knock is friendly. Probably.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_21', text: "I told the fire about my shape and the fire made the circle again, bigger, with the little notch. My two mysteries know each other! That's practically tidy.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_22', text: "I was poking at the fire last night, pure housekeeping, and I stopped with the poker in the air, because under the crackle there was a second sound. A hum, very low, patient as anything. Panko's oven note, I think, except it was everywhere.", phase: 1, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_1_23', text: "I hummed along with it one evening. The whole den went warm as a hug and the embers sat up. I stopped, because a fox should keep some dignity. Mostly I stopped.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_24', text: "One day I'll teach you the note. It's easy, it's already in your chest, you just have to agree to it. Doesn't that sound lovely?", phase: 1, animalType: 'fox' },
  { id: 'fx_1_25', text: "You know what, next long evening you're here, we're staying up. Midnight, blankets, the trick, the pointing, everything. I'll make the chocolate that's mostly a dessert.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_26', text: "At midnight the flames pointed toward the center of the house. I've seen flames give directions before. I didn't like this direction.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_27', text: "I checked the center of the house afterward and found nothing but floor. Beautiful, ordinary floor. Just slightly warm. Just slightly humming. So that's settled and completely fine!", phase: 1, animalType: 'fox' },
  { id: 'fx_1_28', text: "Anyway! I'm gathering all my little oddments, the sketches and the notes and the chestnut incident, into one basket. Next visit we'll sort the basket together. I love a project.", phase: 1, animalType: 'fox' },
  // Phase 2 (21 + 1 question-web)
  { id: 'fx_2_1', text: "There you are! Come in, sit. I've had the strangest week and I've decided to find it funny. Help me find it funny, friend, you're better at it than the fire is.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_2', text: "So, the basket of oddments. I sorted it. All my sketches, laid in order, make one drawing of the circle opening. Like pages of something. I didn't draw pages. I drew nights.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_3', text: "I laughed when I saw it, I really did. Then I put the basket on the high shelf, where I put things I'm not laughing at anymore. It's a very full shelf lately.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_4', text: "But enough about my shelf! Tell me about you. Are you sleeping? Are you eating things that aren't just words? I worry, you know. Someone here should worry about you nicely.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_5', text: "Don't look at the shelf, look at me. Next visit I'll take the basket down again, I promise. It's just... it can hear better than a basket should. Kettle's on!", phase: 2, animalType: 'fox' },
  { id: 'fx_2_6', text: "I can read flames. I inherited the knack. Until now I told myself I only needed to pass on the useful parts.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_7', text: "It was a name. I'm not going to say it, and not because I'm being dramatic, although I'm always being a little dramatic. When I tried, the room leaned in.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_8', text: "A room shouldn't lean, that's all I'll say. Walls have one job. So I sang an old song about turnips, very loudly, and the room straightened up and pretended nothing happened.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_9', text: "I should tell the others. I will. Saying it here first has made postponing it harder.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_10', text: "So we won't say the name, you and I. We'll have shortbread instead, because shortbread is the opposite of names.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_11', text: "I nearly said it for you just now, actually. The name. I got as far as taking the breath, and the fire stood straight up in the grate, tall as the mantel. Held there until I let the breath back out. You saw that, friend. I watched you see it.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_12', text: "I dropped a spoon on the far side of the room and it rolled toward the middle of the house. Uphill, slightly. I made myself laugh about it. It took two tries.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_13', text: "Smoke drifts to the middle too, and my own feet do if I stop paying attention. I've retired from refereeing the fire and the floor over which of them keeps me warmest. Whatever is under the middle of this house has wonderful manners and terrible patience.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_14', text: "Say one of your words and watch the fire. There! It does that for you every time. I keep inviting people to see. I ought to find out what I'm inviting them to.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_15', text: "See? Parade. As long as your words keep coming, this fire stays sweet, and so do I. That's a joke. Mostly a joke. I'll workshop it by your next visit.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_16', text: "You look tired, friend. Come sit on the warm spot, the suspicious warm spot, and tell me something ordinary about your day, the more ordinary the better. I've started collecting ordinary.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_17', text: "I am fond of you, whatever my fire is doing. I want you to know that without asking it to excuse anything.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_18', text: "I've started sleeping with my back to the hearth. Not because I'm scared. Because if anything wants to look at me while I dream, it can have the view of my tail.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_19', text: "The dark shape behind my eyes has started waving. One polite limb, like Duchess used to. Oh, Duchess moved her web to the middle of the ceiling, by the way. Everyone's moving to the middle.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_20', text: "I opened my mouth just now to tell you we're fine, and the word wouldn't come out. So take the last shortbread instead, no arguing, and come back soon, because the fire behaves so much better when it can see you.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_21', text: "One more thing, then I'll be cheerful again, watch me do it. If the flames ever spell that name at you, close your eyes and think of tea. It works. Ask me how I know sometime.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_w1', text: "Would you visit Warren? Ask what he found digging below the house. He stopped halfway through telling me. I made tea instead of asking again. You may have better luck.", phase: 2, animalType: 'fox', requiresAnimals: ['wombat'] },
  // Phase 3 (30)
  { id: 'fx_3_1', text: "Come in quick, and keep your coat on. The fire's been shy this week. I feed it the good dry oak and it eats politely and gives almost nothing back.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_2', text: "I'm not worried. I'm the opposite of worried, whatever that's called when your paws won't sit still. Sit with me. Two of us are warmer than one of me. That's just arithmetic.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_3', text: "Cold grate, warm floor. I moved the kettle down and told a joke about it. The joke went well. I am running short of those.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_4', text: "The truth, since it's you asking with your face like that: the fire grows cold, but something else is beginning to burn. Under us. Patient as bread. I check on it every night.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_5', text: "I may have frightened you. I shouldn't decide that from your expression. Tell me what you need to ask before I offer tea.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_6', text: "I read flames, you know. Really read them. I've let you think it was a party trick because it was nicer that way, for both of us. It was never a trick.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_7', text: "My mother read them, and hers, all the way back to some first fox at some first fire. The flames have been telling one long story that whole time. I got the last chapter.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_8', text: "The last chapter is short. Something old is coming down to this house, and the house has been getting ready longer than any of us have been alive. Now it's yours too, and I'm sorry, and I'm not.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_9', text: "I asked at supper what we're all waiting for, out loud, right over the soup. The whole table went quiet, and then somebody passed me the bread as if that were an answer. You're my friend, so you get the plain shape of it instead.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_10', text: "Now watch me be cheerful anyway, because that's the other thing my mother taught me. Fear is a guest. You feed it, and you don't let it rearrange the furniture. More tea?", phase: 3, animalType: 'fox' },
  { id: 'fx_3_11', text: "Your words, friend. They go down to the pit and they don't stop there. I followed the warmth one night, ear to the floor, and heard them being kept. Arranged. Like kindling.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_12', text: "Beautiful kindling, yours especially. The heavy old words sit at the bottom, where a fire catches best. I shouldn't know that. I know it the way you know a smell.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_13', text: "The fire showed me an empty house. I was frightened enough to mistake that picture for a consequence I could promise you.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_14', text: "So keep bringing them. Please. I've decided that if this is a story, I want you in the warm part of it. The warm part is here, with me, at the center of everything.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_15', text: "Duchess had babies, by the way, forty tiny duchesses, and every single one is building the same web on the ceiling, ring after ring around the middle. Nobody taught them the middle, friend. They hatched already knowing where it was.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_16', text: "Can I tell you the small scary thing? At night the shape behind my eyes stands closer. It isn't behind my eyes anymore, exactly. It's behind the den. It's very tall and very patient.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_17', text: "It doesn't do anything. That's the part that gets me, friend. It just waits, the way the sky waits for morning, completely certain. And I lie there feeling like the morning.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_18', text: "I sleep in the big chair now, facing the door, so the first thing anything sees is a fox who is sitting up. Posture is half of bravery. The other half is the kettle.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_19', text: "Some nights I sing the turnip song until the hum under the floor picks up the tune. I know I should hate that it joins in. It has a lovely voice. I hate that it has a lovely voice.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_20', text: "Stay a little if you want. I would like the company. You needn't take responsibility for my being afraid.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_21', text: "Fennick hears it now too, out in his sands. He came all this way to ask if I'd heard footsteps in the warmth. Footsteps, friend. It doesn't have feet. I checked the coals twice.", phase: 3, animalType: 'fox', requiresAnimals: ['fennec_fox'] },
  { id: 'fx_3_22', text: "Archimedes has found it in his books, or it found him there. He talks in margins these days. I made him soup and told him even lorekeepers have to eat. He held the bowl like an answer.", phase: 3, animalType: 'fox', requiresAnimals: ['owl'] },
  { id: 'fx_3_23', text: "Thyme won't come inside past dusk anymore. I bring her tea in the garden and we don't talk about why, and that's a whole conversation, if you know how to have one.", phase: 3, animalType: 'fox', requiresAnimals: ['rabbit'] },
  { id: 'fx_3_24', text: "I promised whatever was coming would have to go through this fox to reach you. I am trying to understand what keeping that promise requires.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_25', text: "I'd love to be the funny story you tell about this place. I'm trying so hard to be the funny story.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_26', text: "I read the shapes without singing over them. They describe an invitation. I cannot find the part where the guest asks what we want.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_27', text: "The words sustain something here. I knew that when I asked you to help. I thought keeping it alive kept all of us safe.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_28', text: "I have been calling it hospitality. Hospitality needs the person at the door to know what they are entering.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_29', text: "I'm fond of you. That was true before I had to explain myself. It isn't a defense.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_30', text: "Ask me what I knew. I won't let the fire answer that question for me.", phase: 3, animalType: 'fox' },
  // Phase 4 (30)
  { id: 'fx_4_1', text: "I put the kettle on. Then I took it off. Nobody has to stay just because I've made tea.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_2', text: "The fire taught me to bring people here. It left out what would happen once we were inside.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_3', text: "You can sit by the door. I'll bring the cushion.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_4', text: "I've read flames since I was a kit. Knowing a language doesn't mean the speaker tells you everything.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_5', text: "I thought keeping the house alive and keeping you safe were the same job. I should have checked.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_6', text: "The robes itch. I expected ancient secrets to have better lining.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_7', text: "Chestnuts, if you're hungry. I've managed not to burn most of them.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_8', text: "I can still make that ridiculous kettle noise. I won't, unless you want it.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_9', text: "The old den was here before me. These rooms weren't. You helped build something new.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_10', text: "I told the fire guests can change their minds. It bent toward me. I don't know what that meant.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_11', text: "Ask plainly. I've done enough answering a nicer question than the one I heard.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_12', text: "I miss worrying about whether there were enough cups.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_13', text: "Panko asked what I'd promised you. Repeating it didn't make it sound better.", phase: 4, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_4_14', text: "Bamboo calls the warmth an invitation. I used to think a warm invitation couldn't hurt anybody.", phase: 4, animalType: 'fox', requiresAnimals: ['red_panda'] },
  { id: 'fx_4_15', text: "More rooms, more friends. I meant it. I also left things out.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_16', text: "Thyme asked me to stop calling everything all right. I'm trying to catch myself.", phase: 4, animalType: 'fox', requiresAnimals: ['rabbit'] },
  { id: 'fx_4_17', text: "The fire warms your hands. I can promise that. The rest needs better evidence.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_18', text: "I set out a cup from habit. You don't owe me the company it was meant for.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_19', text: "My tail knocked over the poker. For one glorious second, everyone was annoyed about an ordinary noise.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_20', text: "Something below the hearth answers when I speak. It has never answered why.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_21', text: "If warmth can make a person stay, can it let them go?", phase: 4, animalType: 'fox' },
  { id: 'fx_4_22', text: "I'd like another ordinary supper. Burnt bread. Somebody talking with their mouth full.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_23', text: "The house keeps your marks. I hope it can keep a crossed-out mark too.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_24', text: "I promised it would have to go through this fox to reach you. Hold me to that.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_25', text: "I wanted you back because I liked you. I knew your returning helped the fire. Both are true.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_26', text: "Explaining myself hasn't earned forgiveness. I know.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_27', text: "When the moment comes, I want to be close enough to hear what you actually say.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_28', text: "I don't know what a thing that old calls kindness. We need to tell it what we mean.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_29', text: "The kettle lid rattles. I could call it a sign. Or move it half an inch.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_30', text: "You don't have to make me feel better about this, friend.", phase: 4, animalType: 'fox' },
];

const OWL_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ow_0_1', text: "I file by affection. You may disagree after successfully finding something.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_2', text: "Bring me a word and I shall tell you its ancestors. Several will be embarrassing.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_3', text: "I ordered eleven books. The crate was heavier than expected, which I initially counted as value.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_4', text: "There are twelve volumes. I have counted twice, with increasing suspicion toward arithmetic.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_5', text: "The extra book has no title. A severe inconvenience to my system.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_6', text: "I put the untitled book aside. There are perfectly titled books waiting to be read.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_7', text: "A quiet room and a sharp pencil. My ambitions become wonderfully small after lunch.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_8', text: "That isn't a bookcase. It's a stack with structural confidence.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_9', text: "You may borrow the atlas. Please leave the mountains where you found them.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_10', text: "I used to underline everything important. My younger books are almost entirely underline.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_11', text: "A mended spine lets a book open again. Forgiving objects, books.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_12', text: "Ember suggested a fire in the study. I asked which collection she proposed to burn first.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_13', text: "The dictionary has tea on it. A fragrant edition.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_14', text: "I reread books for the passages I remembered badly.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_15', text: "That is my thinking feather. Indistinguishable from an ordinary feather except by expense.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_16', text: "Please return a borrowed book when you've finished, not when you've composed an adequate apology.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_17', text: "Someone once pressed a fern in this volume. I know the fern better than the argument.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_18', text: "The window is at precisely the wrong height for the afternoon sun. I have moved the chair instead of the sun.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_19', text: "Axel described a dream about water to me. An unstable edition, but a lively reader.", phase: 0, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_0_20', text: "I keep a notebook of questions. The answers require a second notebook and much more caution.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_21', text: "My spectacles were on my head. I would prefer this discovery remain within the study.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_22', text: "An old inscription under the crate reads differently in lamplight. I have requested better lamplight.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_23', text: "I was going to organize these papers. Then one became interesting.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_24', text: "Come back when you like. I may have found a shorter answer by then.", phase: 0, animalType: 'owl' },
  // Phase 1 (28)
  { id: 'ow_1_1', text: "A small professional embarrassment: I can't get the same reading twice from my new book. I turn to a passage I know well. The sentence has shifted its weight, as though it overheard how I read it last time and thought better of itself.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_2', text: "I've tested this the way one tests anything, by repetition. Same page, same lamp, same hour. The words are near enough to fool a casual eye and different enough to keep a careful one awake all night. I'm a very careful eye.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_3', text: "I read the changing passage to Ember as a check on my eyes. Her fire had given her the same sentence. Two witnesses. Neither independent of this house. I need a better test.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_4', text: "The margins are the stranger business. I left the outer edge of page nine blank on Tuesday; by Thursday there was a note in it, in that patient hand, and I didn't write it. I've checked the door. The door is a very ordinary door.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_5', text: "Each morning brings fresh annotations, and they're, I must admit, good ones. Better than mine. They anticipate my objection before I've finished forming it, the way a superior colleague does, which is both a delight and a quiet humiliation.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_6', text: "Last night, in a spirit of scholarly provocation, I wrote a small objection beside the stranger's note. By morning there was a reply. It was gracious, it was well argued, and it addressed me by a name I haven't used since I was very young.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_7', text: "You'll want an etymology; I want one too, they steady me. 'Margin' is from margo, an edge, a border, the brink of a thing. I had never once considered how many of our gentle words simply mean the edge of a drop.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_8', text: "I've begun keeping a log, dated and timed, each morning's text set against the night before. The changes aren't random. They correct, steadily, toward some final copy I haven't been shown.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_9', text: "I mentioned my log to Chill, who approved of the method and offered to file duplicate copies in his office, in case, as he put it, the originals wander. I asked what he meant by wander. He smiled, and stamped the page. An excellent administrator. Terrible at answering questions.", phase: 1, animalType: 'owl', requiresAnimals: ['capybara'] },
  { id: 'ow_1_10', text: "The book answered a question I hadn't spoken or written down. One in three, when I test it. I record the unanswered ones too.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_11', text: "For rigor I thought questions at three other volumes as well, my dictionary, my atlas, and a slim collection of poems, standing in as a control group. They kept their pages to themselves, as books do. I want it on the record that I know how books behave. That's precisely my difficulty.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_12', text: "This morning it answered a question I've carried for years and told no one, concerning a friend I lost when I was young. The answer was kind. That's the part I can't get past. Whatever writes in my margins is kind, and I don't yet know what kindness costs it.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_13', text: "The study has grown warm of late, warmest along the inner wall, the wall nearest the middle of the house. Warmth in a room made of paper ought to worry me more than it does. I've shifted my favorite volumes and told myself it's only the season.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_14', text: "Have you noticed that things in this house lean? Nothing dramatic. A pencil rolls the same direction every time, and my chair drifts, over a week, toward the center. I've started to level them, and I've started to wonder why I bother.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_15', text: "Axel reports that his water leans as well, that the surface of his tank sits a degree off level and tips toward the middle of the house. Water doesn't take sides; impartiality is the entire profession of water. I've added his tank to the log.", phase: 1, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_1_16', text: "The new annotations have begun to name words, specific ones, words I could swear I've watched you carry forward and set down before me. I underlined the passage, and then I underlined my own hand in the act of doing it, if you follow me.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_17', text: "Three words appeared in the margin. One later turned up on your board. Two have not. I am keeping all three in the account.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_18', text: "Ember was unsurprised when I told her. She said the fire spells things out for her too, and asked, gently, whether I'd considered that the book and the fire might have the same author. I said that was absurd. I've repeated the word absurd all week, like a charm.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_19', text: "I keep a drawer now for dull explanations: draughts, damp, tired eyes, the ordinary settling of an old house. Every anomaly receives one, filed and dated. I'm collecting them all in one place before I decide which dullness to believe.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_20', text: "'Curious,' since we're being curious together, once meant careful, full of cure and care. Only later came to mean prying, wanting to know what one should perhaps leave closed. The word grew a second, hungrier meaning. Words do that. So, apparently, do books.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_21', text: "I searched my catalogues for the book's ancestry and found a single reference, in a bibliography two centuries old, to a volume with no title that couldn't be dated. The entry stops mid sentence. Bibliographers don't stop mid sentence. We aren't built that way.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_22', text: "Panko has noticed I'm not sleeping and has begun sending up warm milk with the ginger, unasked. I complained, at length, about being managed, and I drank every drop. Some footnotes need not be read aloud in a house like this one.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_23', text: "I'll admit, in the low voice one uses in a library, that I'm uneasy. Not frightened; a scholar is rarely frightened, only insufficiently informed. But there's a difference between not yet knowing a thing and beginning to suspect the thing knows you.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_24', text: "Don't let my unease chase you off. Unease is only curiosity that has read a little further ahead, and I'd rather be uneasy in good company than certain and alone.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_25', text: "A physical note for the log: the book has begun falling open to the same page no matter where I leave the ribbon. Spines do develop habits; a binding remembers how it was read. But this spine remembers a page I have never once read.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_26', text: "The page it insists upon holds a diagram, or nearly one, a spiral of small marks that resolve into letters if you tilt the lamp just so. I haven't yet made out the word they spell. I confess I haven't tilted the lamp very far.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_27', text: "Come and sit anyway. I set out two cups this evening without quite deciding to, and it would be a shame to prove the table wrong. Bring me a word. I find I read a great deal better when you're here.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_28', text: "Next time, I shall have dated the paper properly; the tools are ordered and on their way. A scholar ought to know exactly how old a thing is before deciding exactly how much to fear it. That rule is in no handbook I own. I may have to write the handbook.", phase: 1, animalType: 'owl' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ow_2_1', text: "I've spent this week dating the book, by every method I trust and two I merely respect. The finding isn't the sort one announces standing up. Sit, pour yourself something warm, and I'll read you my conclusion in the calmest voice I can manufacture.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_2', text: "The book is older than the house that holds it. It predates the wood it seems bound in, predates the language it seems written in, predates, as far as I can measure, the ground beneath all of us. It isn't from before the house. It's from before before.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_3', text: "I checked the ink against every reference plate I own, and it matches none of them. The paper isn't quite paper, and the thread in the binding isn't thread. At some point a scholar must stop asking what a thing is made of and begin asking what it's for.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_4', text: "I carried my findings to Ember, braced to explain them twice. She nodded before I'd finished once, as though I were confirming her fire rather than the other way around. It's a strange feeling, to arrive breathless at a summit and find a fox already seated there.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_5', text: "One test remains, the oldest in the discipline: read it aloud. A text reveals itself in the mouth as it never does to the eye. I'll do it tonight, when the house is quiet. I'm aware that this is precisely the wrong time. That's rather why I chose it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_6', text: "I read the opening aloud. Chambers, a central space, words passing between them. It resembles this house, though some details disagree.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_7', text: "The old foundation matches the first diagram. The rooms you helped add appear in another ink. I should examine the alterations before declaring a prophecy.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_8', text: "I can't find a builder for the original den and foundations. The additions have a clearer account: your amber, new work, people invited to live here.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_9', text: "The book uses one particular word for the lot of us, and I've resisted repeating it, because names have gravity. But you've earned precision. It calls us keepers. The root means one who watches, and also one who holds a thing for someone else, until they come to collect it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_10', text: "Here, a cold little gift. 'Permanent' comes from permanere, to remain through to the end, and 'impermanent' merely pins a small denial to the front of it. Both words assume there's an end to remain through. The book makes no such assumption about itself. It makes it about us.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_11', text: "My first theory is that the diagram describes protection. It needs testing. The arrows point an inconvenient way.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_12', text: "Worse still. I compared the grading hand against my own marginalia from years past, and some of my oldest notes now read like preparation for this. I underlined the relevant passages long before I knew what they were relevant to. A scholar's instincts, it seems, can be recruited before the scholar.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_13', text: "My voice no longer carries from the study to the stairs. I measured the hall. Same length. I've propped the door open with an atlas. At last, a useful scale.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_14', text: "There's a sound beneath the ordinary sounds of the house. Under the lamp's hum, under my own turning pages, a low sustained note, as patient as the hand in the margins. Once you've heard it you can't unhear it, which is, I gather, rather the point.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_15', text: "It isn't confined to my study. Panko says her recipes have begun to rhyme, and Axel's water gathers itself into the same spiral I found pressed into the book. One anomaly is a curiosity. An anomaly in every chamber, one to a keeper, is a syllabus.", phase: 2, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_2_16', text: "There is a list resembling words you have formed. It also contains words you haven't. That difference matters.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_17', text: "The list runs on for pages past the words you have already brought, into words you haven't brought yet. I won't tell you which. Foreknowledge has a way of becoming instruction. But I check every morning, and every morning the next entry's ink is darker, like a thing coming into focus.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_18', text: "I considered hiding the book, and stood at the highest shelf for an hour with it in my wings, and couldn't do it. I'll be honest about why. It wasn't fear. I need to know how it ends. That's my entire species of sin, and the book knew it when it chose me.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_19', text: "The inner wall is warm as a sleeping animal now, and the study smells faintly of summer in the wrong season. I've stopped logging the temperature. There's a point at which measurements stop being data and start being correspondence.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_20', text: "One entry for the record, while the record is still mine to keep. Whatever comes through this house, it was written down first, and I was the one who read it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_21', text: "Come back soon, and keep bringing me your words. I know how that sounds, after everything I've told you. But the book is the only window I can read through, and each word turns one more page. I'd rather we read this together than let it read us alone.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_w1', text: "Fennick hears the note I find beneath these pages. Ask what it says, and bring his exact words. I shall keep them beside my translation, not improve them into it.", phase: 2, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  // Phase 3 (30)
  { id: 'ow_3_1', text: "I read the last chapter. It calls the result preservation. It is frustratingly brief about what is preserved.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_2', text: "I can't tell you what it says. Not because I'm forbidden, but because I've discovered there's no unreading. A sentence, once it's inside you, keeps its own hours. It reads itself back to me when the lamp is low, in that patient hand, in my own voice.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_3', text: "Fennick came to my door at midnight and asked what the sound beneath the house was saying. I couldn't tell him, and not knowing, for the first time in my life, felt like negligence. So I turned to the end. He only asked the question. The turning of the page was entirely mine.", phase: 3, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  { id: 'ow_3_4', text: "I gave my whole life to scholarship, and scholarship has given me a sentence. I mean both senses of the word at once: the thing I studied has pronounced upon me, and I'm now serving what it said.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_5', text: "I've told no one else how it ends. Not Ember, who may know already; not Panko, who would only bake for it, because that's how she carries things. Carrying it alone is heavy. I find I'd rather it be heavy than contagious.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_6', text: "The text specifies an arrival from above. I had written pit in the margin. Crossed out now, still legible. A reader should be able to see where I was wrong.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_7', text: "Fennick confirmed it without meaning to. The sound no longer rises from below, he says; it hangs overhead now, faint, like weather that hasn't decided. He asked why I'd gone so still. I told him owls go still in order to listen. It was the first lie I have ever told a colleague.", phase: 3, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  { id: 'ow_3_8', text: "The book groups its predictions by a count. Some of my tallies agree. Some don't. I've stopped treating the agreements as the whole result.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_9', text: "The book assigns me an office and describes what its holder does. I have done part of that work. It hasn't established that I must finish the rest.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_10', text: "I spent four nights hunting for a variant text, a second edition, any manuscript tradition in which the ending diverges. There's none. There's one book, never copied, and it was never copied because it has never needed to be right twice.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_11', text: "I'd like to report fear, honestly, but it has curdled past fear into something quieter. Dread is fear that has read the appendix. It knows the outcome and simply waits with you, politely, for the pages to catch up to what it already told you.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_12', text: "Ember knew the words sustained something. I have the diagrams. Neither kind of knowledge establishes what the guest will do.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_13', text: "I asked Warren about the foundations, casually, over Panko's soup. He said the house rests on tunnels older than his family, that he only ever widened what was already there, and he said it with a digger's pride. I couldn't finish the soup.", phase: 3, animalType: 'owl', requiresAnimals: ['wombat'] },
  { id: 'ow_3_14', text: "'Doom' isn't, at its origin, a curse. It meant a judgment, a thing set down, a decree read aloud in a court. To be doomed was merely to have had one's case decided. I take a scholar's cold comfort in that. We weren't cursed. We were ruled upon.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_15', text: "Thyme came to the study with her ears flat and asked me to tell her honestly whether her garden was growing in patterns. I have never managed to lie to that rabbit twice in one lifetime. I showed her the page the book falls open to. She didn't scream. That was worse.", phase: 3, animalType: 'owl', requiresAnimals: ['rabbit'] },
  { id: 'ow_3_16', text: "The words you offer go down to the pit, and I used to think of that as filing. Now I understand it's nearer to feeding. Every word you set before me, I have, in effect, carried to the appetite beneath the house. My sincerest apologies. I filed you into a mouth.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_17', text: "I tried to burn the book. I confess it, keeper to keeper. It didn't resist and it didn't char; the flame simply declined the invitation, the way a guest declines a dish they know was never meant for them. You can't end a thing by unwriting it when it was written before writing.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_18', text: "The morning after the flame declined it, there was a new note in the margin, in the patient hand, set precisely where the scorch should have been. It said, thank you for the warmth. I've filed the incident under courtesy, because the other available drawer doesn't bear opening.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_19', text: "The diagram places someone at the center without showing what they are told. I used to call that efficient notation.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_20', text: "It appears to use affection as part of its arrangement. Affection can be sincere and still be used. We need to ask who understood the use.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_21', text: "The study is warm now in the way a body is warm, which isn't the way a hearth is warm. Warmth ought to mean fire, which means fuel, which means an end. This warmth has no fire under it and asks for no fuel. It's simply, patiently, the temperature of what waits.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_22', text: "The library is moving books toward the inner wall. I recognize the order from a diagram. I did not choose to shelve them this way.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_23', text: "Sloane visited, which for her is an expedition of some days, and she regarded the book a long while without touching it. Then she said, in that unhurried voice, that she remembered when it was the only thing here. I didn't ask what she meant. Some citations one leaves unchased.", phase: 3, animalType: 'owl', requiresAnimals: ['sloth'] },
  { id: 'ow_3_24', text: "I've opened an atlas, a poem, and a cookbook. I want an account of us that has uses outside the arrangement.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_25', text: "I began another notebook. The animals as they are: funny, difficult, sometimes wrong. I will not edit them into better symbols.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_26', text: "If you make more words, watch what changes. I can explain the evidence I have. I won't tell you that a choice was already made for you.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_27', text: "I climbed to the attic to ask Bamboo how they stay so calm, and they poured the tea and said a page is only frightening while it's turning. I've been arguing with that sentence for three days now. Last night I caught myself footnoting it.", phase: 3, animalType: 'owl', requiresAnimals: ['red_panda'] },
  { id: 'ow_3_28', text: "If I could carry a single thing out of this house, it wouldn't be the book; the book would only follow. It would be Panko's little tray, or the log with your words in it. The record of the ordinary. That's the rarest text in any collapsing library.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_29', text: "I wrote down that I was fond of you. It was the easiest sentence to verify, and the hardest to leave without an excuse after it.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_30', text: "Go carefully, and when the sky begins to look like a page to you as well, come straight here. I'll be at the window with the lamp lit. Whatever descends will find, at the very least, that it has been thoroughly footnoted.", phase: 3, animalType: 'owl' },
  // Phase 4 (30)
  { id: 'ow_4_1', text: "I mistook a description for instructions. An elementary error, dressed in excellent handwriting.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_2', text: "The book calls this preservation. It doesn't define what may be altered.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_3', text: "I'm writing in pencil. My certainty used rather too much ink.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_4', text: "Ask for evidence. Owning a lectern isn't a qualification.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_5', text: "That volume came in the first crate. The notes resemble mine. Resemblance doesn't prove I wrote them.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_6', text: "Old foundations in the diagrams; new rooms in later annotations. I should have compared the inks.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_7', text: "I can't name the author. I can tell you which claims failed a test.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_8', text: "A place for every creature. No entry for one changing its mind.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_9', text: "My pressed-leaf bookmark moved. Currently more candid than my source.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_10', text: "I am fond of you. That doesn't acquit my scholarship.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_11', text: "The index sends leaving to belonging. An evasion.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_12', text: "I've opened an atlas. Roads go places in an atlas. Usually.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_13', text: "A promising theory is only a theory. I enjoyed the promising part disproportionately.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_14', text: "We weren't equally informed. I won't turn different mistakes into one comforting story.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_15', text: "The plain notebook holds ordinary things. Bad jokes. Disagreements. How someone took their tea before anybody corrected them.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_16', text: "I recorded Ember's burnt bread. She protested. I recorded the protest.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_17', text: "An ancient book may contain an ancient mistake. Wish I'd observed that first.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_18', text: "Being kept sounds merciful. We haven't established what it prevents.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_19', text: "The last page remains. I no longer take it as a guarantee.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_20', text: "Someone present should check my account. Scholarship benefits from interruption.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_21', text: "You may refuse a conclusion without knowing the right one. Remember that if I become unbearable.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_22', text: "A spare pencil. You needn't take notes. It's reassuring that you could.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_23', text: "Unexplained light: filed under unexplained light. Progress, of a sort.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_24', text: "Someone at the diagram's center describes an arrangement. It doesn't establish consent.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_25', text: "Thyme's measurements belong beside mine. A small ruler is still a ruler.", phase: 4, animalType: 'owl', requiresAnimals: ['rabbit'] },
  { id: 'ow_4_26', text: "I corrected a cookbook without tasting the soup. Panko keeps me informed of this.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_27', text: "If I say I knew all along, inspect my crossings-out.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_28', text: "I've stopped polishing the lectern. It gave the wrong impression.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_29', text: "Something irrelevant to read? An exceptionally spiteful poem about geese.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_30', text: "I'll leave room in the record for what we get wrong next.", phase: 4, animalType: 'owl' },
];

const CAPYBARA_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'cp_0_1', text: "Good chair's free. Tested it for most of the morning.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_2', text: "I'm finishing a thought. No deadline attached.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_3', text: "Coffee is warm. That accounts for half the office's achievements.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_4', text: "I made a list, then removed the unnecessary part. Short list now.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_5', text: "Take your time. I have a form for rushing and haven't printed it.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_6', text: "The desk drawer sticks. Open it slowly. A policy I support elsewhere too.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_7', text: "I put a plant by the window. It has declined every meeting so far.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_8', text: "This mug says productive. A gift from somebody with a generous definition.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_9', text: "The spring is my break room. I leave the ledger here.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_10', text: "There are spare pencils. Return one if you borrow one. Return two if you feel unusually civic.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_11', text: "A quiet visitor improves the office. So does a noisy one, on certain days.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_12', text: "I have scheduled nothing after lunch. A difficult appointment to protect.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_13', text: "My face is doing the pleased expression. Small print.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_14', text: "The good chair squeaks. I consider that feedback.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_15', text: "No agenda today. You can still have coffee.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_16', text: "I found a receipt for something I enjoyed. Pleasant when accounts explain themselves.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_17', text: "The plant leans toward the window. First successful office relocation.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_18', text: "I keep a folder for later. It has become ambitious.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_19', text: "A tidy desk doesn't necessarily mean finished work. In this case it does mean hidden work.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_20', text: "The boiler note says sufficient. No temperature. An unusually confident note.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_21', text: "I recorded your visit after you came in. Good to have a task with a clear order.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_22', text: "Panko asked for a shelf estimate. I estimated that somebody else should build it.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_23', text: "No need to stay to be polite. No need to leave to be efficient.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_24', text: "I am glad you stopped by. Recorded without qualification.", phase: 0, animalType: 'capybara' },
  // Phase 1 (28)
  { id: 'cp_1_1', text: "A small administrative curiosity to report. This morning I opened a folder I have no memory of creating, and found it complete, accurate, and filed in precisely the place I'd have filed it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_2', text: "I checked the handwriting against my own, carefully, letter by letter. It's mine. I simply can't recall the afternoon in which I sat down and wrote it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_3', text: "This has never troubled me before because it has never happened before. I made a fresh pot, sat down with the folder, and read it through twice. It's good work. I'd be proud of it if I could remember being the one who should be.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_4', text: "My schedule for next week filled itself in overnight. I want to be precise: not with nonsense. Every entry is sensible and correctly placed, exactly the appointments I'd have made. I simply didn't make them.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_5', text: "I've started initialing each page as I finish it, with the time, so I can be certain of my own work. This morning three pages carried tomorrow's date and my initials, and I haven't yet lived tomorrow.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_6', text: "I opened a file for these occurrences, naturally. Filing a thing is how I hold it still long enough to look at it. When I went to label the folder, the label was already typed. It says Onboarding.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_7', text: "The warm patch toward the middle of the house has grown, gently, by about a room. I measured. I'm the sort who measures. It's warmest exactly where the ledger is kept, which I'm sure is only a matter of ducts.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_8', text: "I locked the ledger in a drawer one evening, purely as an experiment. By morning it was open on the desk at the day's page, the drawer was still locked, and the key hadn't left my pocket. I've apologized to the ledger, in a manner of speaking, by never doing that again.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_9', text: "I sat up one night with the ledger and a fresh pot, determined to catch the entries arriving. I woke at my desk at dawn with the day's words recorded, the pot still warm, and my pen capped neatly in my hand. I don't cap my pen.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_10', text: "Ember came by and asked, very lightly, whether I ever feel I'm filing things for someone. I said the paperwork does have a recipient, now that she mentions it. I had simply never asked who.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_11', text: "Panko mentioned her pantry restocks itself now, always precisely what the week's cooking needs. She has decided to be grateful, and I told her gratitude was the correct filing. Then I went back to my office and looked at my own supply cupboard for rather a long time.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_12', text: "Archimedes put in a requisition for lamp oil last month, then found the oil already on his shelf, older than the request. He asked how my system managed that. I told him the truth, that my system doesn't, and we sat with it a while over tea.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_13', text: "I have always taken comfort in a full calendar. Lately the comfort has a strange edge to it. Every slot filled means every hour is already spoken for.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_14', text: "There's a project underway. I'm certain of this the way I'm certain of weather. All the small tasks point one direction, they coordinate, they nest inside each other neatly. No one has told me the name of the thing they're building toward.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_15', text: "I drew up an organizational chart of all the small tasks, to see the shape of the thing. It's a fine shape, tidy, converging. At the top there's a box that came out larger than the others, and I haven't yet found what to write in it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_16', text: "A memo arrived from Axel, damp at the corners, describing something he had seen in his water. He addressed it not to me but to the desk. I've thought about that distinction more than I should. Desks don't read. Mine, at any rate, has given no sign.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_17', text: "Fennick asked to compare logs, so we did, his watches against my curiosities. Every odd entry of mine falls inside one of his listening hours. He nodded as though this confirmed something, and didn't say what. I let him keep the copy.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_18', text: "Sloane returned the questionnaire I sent when opening the office. Under long-term goals she answered a question I hadn't included.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_19', text: "I asked myself whether I'm worried. I checked, honestly, the way I check a figure twice. The answer is no, which is itself the most curious entry in the whole log. I should be worried, and I'm only tidy.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_20', text: "My coffee hasn't gone cold once this month. Not once. I set it down, I forget it through a long task, and it's warm when I return. I've decided to find this hospitable rather than strange.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_21', text: "My arrival date is filled in earlier than I remember coming. I've marked it disputed and kept the date I wrote on my unpacking list.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_22', text: "I audited my own attendance, purely as an exercise. The record shows me at this desk on several days I clearly remember spending elsewhere. The record is initialed. My attendance, apparently, is better than I am.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_23', text: "There's intake paperwork in my cabinet for keepers who haven't arrived yet. A wombat, for one, a Warren, with a start date and a room assignment below all of ours. I didn't prepare it. I've left it where it lies. It seems rude to unexpect someone.", phase: 1, animalType: 'capybara', requiresAnimals: ['wombat'] },
  { id: 'cp_1_24', text: "I left a note for morning. Someone answered beneath it in my handwriting: rest more. Sensible advice. Unacceptable signature. I kept the page.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_25', text: "Your folder, I notice, fills faster than anyone's ever has. Pages I don't add appear in correct order. Reading them would breach my own policy, since I evidently didn't write them. I'm still deciding whose policy outranks whose.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_26', text: "The good chair has begun to face the middle of the house by evening, a few degrees off from where I leave it. I straighten it each morning. It's the only argument this office and I have, and we're both very polite about it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_27', text: "I want to be clear that I like it here more than ever. Whatever is minding this office minds it well, and minds me with it. It's pleasant to be looked after. I merely wish I'd seen the contract.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_28', text: "Everything, I want to say for the record, is still running smoothly. That's true, and it's the part I keep returning to. Nothing is wrong. The office has simply begun keeping itself, and it keeps itself beautifully.", phase: 1, animalType: 'capybara' },
  // Phase 2 (21 + 1 question-web)
  { id: 'cp_2_1', text: "There's a folder with your name on it, and it's far thicker than a newcomer's folder should be. The earliest pages predate your arrival by a good margin. Someone was keeping a record of you before you were here to record.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_2', text: "I read the first page of your folder, dated long before you came. It lists the chair you'd prefer, the hour you tend to visit, the words you'd offer first. Every prediction has held. I no longer call them predictions in my notes. I call them arrangements.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_3', text: "I've been coordinating something. I know this the way you know you've been walking, from the distance covered. Messages I don't remember sending have gone out, in my voice, and the replies are addressed to me by title.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_4', text: "The title they use is Administrator. It isn't one I chose, and it didn't arrive by memo. It was simply in the correspondence one morning, everyone accepted it at once, and my mouth, I noticed, had already learned to answer to it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_5', text: "I looked for the letter appointing me and found it filed under my name, dated before this house had rooms. The signature line at the bottom is blank, and yet the appointment was plainly accepted. My whole career is in that cabinet somewhere. I've declined, for now, to summarize it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_6', text: "I keep the master schedule. I understand that now. The others each hold a piece, Panko her preparations, Fennick his watches. But the whole timeline sits on my desk, and it's I who keeps the pieces from colliding.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_7', text: "I don't recall agreeing to this. That's the entry I can't reconcile. Everything is signed, everything is consented to, in my hand, and the signature is genuine, and I was never asked.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_8', text: "There are minutes on my desk from meetings I chaired. The attendance lists are thorough. Every keeper is marked present, including keepers I haven't met, including one entry that isn't a name at all, only a long blank space that the pen very clearly went around.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_9', text: "The organizational chart finished itself. The large box at the top has a title now, printed in the tidy hand. It says, the recipient. Below it, connected by a single line, is my box. I've studied that line for hours. It's the shortest one on the chart.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_10', text: "I answer correspondence now the way one breathes, without deciding to. This week I caught myself sealing an envelope I had no memory of writing, addressed downward. Not to a name. Downward. The house has its own internal post, apparently, and I'm its most productive employee.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_11', text: "There's a chair in the hall with a loose back leg, and no one has mended it, and no one intends to. We keep this office beautifully and repair nothing, the way you keep a rented room. As though there's a date after which the filing simply stops.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_12', text: "There's a date. I feel it in the shape of the schedule the way you feel the bottom of a page approaching under your thumb. Everything is scheduled toward it. Nothing is scheduled past it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_13', text: "The warm middle of the house is no longer a matter of ducts. I traced the ducts. They don't go there. The warmth is coming from the point everything on my desk quietly leans toward, and I've stopped pretending I don't see the lean.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_14', text: "The marble rolled toward the center of the house. Level desk; checked. I put it in a dish. The dish is moving. Revised containment proposal pending.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_15', text: "Nothing is scheduled past the date, but the supply orders tell the truer story. The candles run out that week. The coffee runs out that week. Whoever planned our stores planned them to the day, and planned no breakfast for the morning after.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_16', text: "I catalogued the words you've offered so far. Read as a list they aren't random. They sort. They fall into categories I could name, and the categories were already printed at the top of the columns before I filled them.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_17', text: "Your folder gains weight on the days you offer generously. I weighed it, because weighing things is what I have instead of praying. The correlation is exact. Whatever is being kept about you is made of what you give.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_18', text: "I drafted a letter of resignation, as an exercise in whether I could. The drafting went smoothly. The filing went smoothly. It came back the next morning marked approved, with a start date rather than an end date, and the start date is the date.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_19', text: "I haven't told the others most of this. Calm is the one resource I'm responsible for issuing, and I ration it honestly. But you handle the words themselves, so you receive the unabridged file. The one who fills the ledger should know it has a bottom.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_20', text: "I remain calm, and I've examined the calm carefully, because a calm you can't explain is a finding, not a comfort. Everything is on track. I've entered that sentence in the log under findings.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_21', text: "I still empty my inbox nightly. It fills again by morning, courteously, never more than I can finish in a day. Whoever assigns my work knows my pace exactly. Of course they do. They have my folder too. Somewhere there's a cabinet where the administrator is administered.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_w1', text: "My filing categories appear in Archimedes' oldest book. Ask what's on page one. I need a source date before claiming authorship of the system.", phase: 2, animalType: 'capybara' },
  // Phase 3 (30)
  { id: 'cp_3_1', text: "Here is the honest status, since you're named in the plan and deserve accuracy. We're on track. Every milestone has landed on the day it was due, without slippage. I used to live for that sentence.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_2', text: "A project that runs perfectly is a project someone is minding closely. Nothing real runs this clean on its own. Something is keeping our timeline true, correcting us gently when we drift, and it isn't me, though it signs as me.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_3', text: "The warm center of the house is now warm enough to feel from the office door. Everything on every desk leans toward it, the pens, the papers, the animals when they think no one is watching. The lean is on schedule. I checked it against the plan, and it's exactly where the plan said it would be by now.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_4', text: "I moved a date in the ledger. The page moved it back. I've kept the sheet on my desk instead of filing it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_5', text: "The project corrects its own dates. I have stopped correcting my notes to match. We need to know which version was first.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_6', text: "I asked Archimedes to read me page one aloud. He did. It was my filing system, described as a rite, in a language older than the study. I've been administering a ceremony and calling it good recordkeeping.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_7', text: "Earlier entries resemble my handwriting. Resemblance isn't memory. I am treating them as an unverified source.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_8', text: "I've stopped asking who set the deadline. The more useful question is what happens on it, and the schedule answers that only by ending. There are no entries after. The calendar simply goes blank, cleanly, like a task completed.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_9', text: "The calendar ends here. It doesn't prove the days do. I have put a blank sheet beside it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_10', text: "Axel drew a shape from the water. It matched a flowchart I made before coming here. We kept the two drawings apart to compare them.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_11', text: "Panko stopped me at the kitchen door and asked whether everything was all right. I said yes before she had finished the question. It wasn't a decision. My mouth issues calm now the way the pot issues coffee, warm and automatic and on behalf of the house.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_12', text: "I no longer circulate the full agenda. Each keeper receives only the page with their own tasks on it, and I tell myself this is kindness. I'm aware that it's also exactly how you run a project no one would finish if they saw it whole.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_13', text: "I calmed Thyme so I could finish a row. She needed me to read her figures. I apologized before asking to see them.", phase: 3, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_3_14', text: "Warren reports a low note in the foundation. A number in my old planning notes might describe its frequency. Might. I asked him to measure again.", phase: 3, animalType: 'capybara', requiresAnimals: ['wombat'] },
  { id: 'cp_3_15', text: "I've begun to see the house as a single form being filled in. Each of us completes a field. Ember the reading, Panko the portions, Fennick the timing, and I'm the signature block at the bottom. Forms are harmless until signed. We're nearly signed.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_16', text: "The words you offer are no longer filed loosely. They queue. Each one takes an assigned place, and this week I could read the shape they're making from across the room, one page short of a sentence I don't want completed.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_17', text: "I measured how much of the plan remains. Not much. A tidy administrator can feel a project entering its final phase, the way the last folders in a drawer stop needing to be searched for. We're in the last folders now.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_18', text: "Your folder has grown a final section, tabbed and waiting, exactly one page thick. I know what a form looks like when it lacks a single field. Everything about you is complete except one entry, and the schedule knows the day it will be made.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_19', text: "I took a page of your folder to Ember's fire, meaning to burn it. I stood there long enough for the fire to notice me. Then I carried the page back upstairs and refiled it, gently, in its correct place. I'd like to report which of us made that decision. The record only shows that it was made.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_20', text: "I wrote a warning memo and filed it where nobody would look. Accurate writing, ineffective warning. I'll have to deliver it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_21', text: "I want to lie to you and say the deadline can be moved. It can't. I hold the master schedule and there's only one date in the whole thing written in a hand I truly don't recognize, pressed deep into the page, and everything else defers to it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_22', text: "Fennick came to the door last night and didn't knock, only listened, and said the sound under the other sounds has gotten closer to the surface. I marked the time in the log. His report and my timeline agree to the hour.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_23', text: "Sloane answered the question I sent after arriving. Her note had an older date. I asked about the date instead of quietly correcting mine.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_24', text: "Bamboo appears in minutes of meetings neither of us remembers. I sent the copies back with that fact written across them.", phase: 3, animalType: 'capybara', requiresAnimals: ['red_panda'] },
  { id: 'cp_3_25', text: "The instruction says continue as before. It leaves no space for anyone wanting something different.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_26', text: "Private readings: pulse, hand, appetite. Steady for a month. Identical, including the ink blot. I have started making the entries on separate paper. The ledger can file an objection.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_27', text: "Everything you've offered is accounted for. Nothing has been lost. I say that to reassure you and I hear, as I say it, how it sounds. A thing that loses nothing keeps everything, and keeps it for a reason, and the reason is nearly here.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_28', text: "There's one kindness left inside my authority, and I'm spending all of it in the same place. I can keep this office ordinary. Warm room, full pot, clean desk, right up to the last page. That's the whole of my remaining budget, and it's allocated to you.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_29', text: "If you were staff I'd reassign you. I've looked into it. There's no form for removing the key from the arrangement, and I have every form. I checked every drawer. That was the day I finally understood your position here.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_30', text: "When you next come by, the coffee will be warm and the chair will be free, exactly as always. Hold onto that as long as you can. I intend to. Some part of me knows that the ordinariness of this office is the last ordinary thing, and I'm keeping it running for you on purpose.", phase: 3, animalType: 'capybara' },
  // Phase 4 (30)
  { id: 'cp_4_1', text: "The form says everyone agrees. No space for another answer. I've added one.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_2', text: "I knew office work. No cosmic purpose in the handover notes.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_3', text: "My signature on an authorization I don't remember. Marked disputed.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_4', text: "Good chair's free. Paperwork can wait.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_5', text: "The calendar stops here. A blank sheet beside it. We may need more dates.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_6', text: "The house corrected no. Short word. Difficult to mistype.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_7', text: "I called things manageable when I meant I could stop thinking about them.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_8', text: "Keep original sheets. Filing a correction doesn't require destroying the source.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_9', text: "If someone budgeted for my objection, they'll hear it anyway.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_10', text: "Coffee. Can't vouch for its relevance.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_11', text: "I calmed Thyme down to finish a report. She needed me to read what she'd found.", phase: 4, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_4_12', text: "Useful to the house and useful to a friend. Separate jobs.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_13', text: "The ledger says settled. I've requested a definition.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_14', text: "Thyme's fear is information. It isn't an assignment for our benefit.", phase: 4, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_4_15', text: "I can sit quietly without requiring you to become quiet.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_16', text: "The pen acquires a cap. I've put the cap in a drawer. Ongoing case.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_17', text: "This chair squeaks. I've declined a replacement.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_18', text: "Permission to disagree. Permission was unnecessary, but old habits.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_19', text: "I delayed an apology while finding a concise version. Another delay.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_20', text: "Two dates on notes: when it happened, and when the page says it happened.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_21', text: "Say if you don't want an answer recorded. Records can expose people too.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_22', text: "Extra-large requisition. No dimensions. Not how furniture works.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_23', text: "I'm moving the desk to see who's waiting. The inbox gets the worse view.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_24', text: "Orientation question: what do you do when someone asks you to stop?", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_25', text: "A finished report may have unresolved matters. This one will.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_26', text: "I like order. I also like knowing whose order it is.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_27', text: "A column headed contentment. I haven't filled it in for anyone else.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_28', text: "The clock still runs. Helpful.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_29', text: "We can take a break. It doesn't count as agreement.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_30', text: "No reassuring forecast. A chair and time to listen.", phase: 4, animalType: 'capybara' },
];

const WOMBAT_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'wb_0_1', text: "Mind the lintel. Measured for a shorter audience.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_2', text: "Warren. Digging, bracing, and tea when the kettle cooperates.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_3', text: "I make square corners. The earth supplies more than enough curves.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_4', text: "There is old stone beneath the new work. I check both before trusting either.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_5', text: "Thirty years digging. Still pleased when a shelf comes out level.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_6', text: "A good shovel fits the hand using it. Mine looks terrible in a shop window.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_7', text: "The crate will take your weight. I don't offer a seat without checking.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_8', text: "A damp patch smells different before it looks different. Useful nose, mine.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_9', text: "I cut seventeen chambers over a career. Remember each ceiling. Forget where I put the cups.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_10', text: "Warm soil near that wall. Could be the hearth. I'll measure.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_11', text: "The low doorway teaches me to duck. Nobody else needed the lesson.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_12', text: "The handle is worn to fit my paw. I'm sentimental about useful things.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_13', text: "If you want to help, hold the lamp where the work is.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_14', text: "Ember brought tea down. A good neighbor with a dangerous tail near chalk.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_15', text: "A square peg isn't wrong until you insist on a round hole.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_16', text: "I keep offcuts. Tomorrow usually needs a piece nobody wanted today.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_17', text: "The burrow is new to me. The foundation isn't. Different histories, joined carefully.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_18', text: "I like a job you can check with a string and a weight.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_19', text: "Earth in my pockets again. Taking work home is easy when home is earth.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_20', text: "Somebody drew a plan on old stone. The dimensions are worth comparing to what stands above it.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_21', text: "Rest while I find the spare cup. A project of uncertain duration.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_22', text: "The shelf stayed level overnight. I checked before breakfast because I wanted to.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_23', text: "I sharpen tools while thinking. Do interrupt before I sharpen through the blade.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_24', text: "Come down when you like. Knock first if you hear hammering; I won't hear anything subtler.", phase: 0, animalType: 'wombat' },
  // Phase 1 (28)
  { id: 'wb_1_1', text: "I've been digging thirty years and I'll tell you something odd. Lately my tunnels want to run a way I never planned. I set out east, and by lunch I've curved off without meaning to.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_2', text: "At first I blamed my shoulder. A digger drifts toward his strong side, that's known, and I'm not young. So I dug left-pawed for a week to test it. The tunnels curved the same way regardless. It isn't my shoulder.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_3', text: "I checked the bearings on every shaft I've sunk this season. Every last one of them leans the same direction, toward the middle of the house, toward the pit that sits under all of it. I can't yet say what to make of a thing like that.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_4', text: "I told Ember about the leaning. She just nodded, like she'd been waiting on me to notice, and she didn't say a word about it after. That's not like her at all.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_5', text: "Ember showed me where the new burrow could join the old stone. She pointed without checking a drawing. I would like to know how she knew.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_6', text: "So I sharpened the spade and took the question down with me. There's always an answer in the ground if you're willing to go find it. That's what I believed going down, anyway.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_7', text: "The dirt changes color the deeper you go. That's normal, everyone who digs knows that. But there's a layer down there that's the wrong color for any earth I've turned, and I've turned a great deal of earth.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_8', text: "Wrong how, you ask? I can't rightly put a name to it. It's dark, but not the way dirt is dark. Dark like it's holding something back. Dark like a held breath, and I keep thinking of that empty gallery.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_9', text: "I brought a handful of that warm layer to the lamp. Ordinary dirt by the top step. Next time the lamp goes down. Can't inspect a job only from where it's comfortable.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_10', text: "Down at the wrong-colored layer, the ground is warm. It shouldn't be. Earth gets colder as you go down, that's the first thing any digger learns. This gets warmer, and warmth where there ought to be cold is a thing that keeps a man up nights.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_11', text: "I put my bare palm flat on that warm layer and held it there a good while, the way you'd check a wall for damp. It wasn't like touching stone. It was like touching the flank of a barn animal through a blanket. I don't say that easy.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_12', text: "Panko asked me why I've been eating so little. I didn't tell her it was the warmth. You go down to a warm place that ought to be cold and your appetite stays up top where it's got the good sense to.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_13', text: "I've started measuring three times instead of twice. Not because my hand got lazy. Because the numbers don't sit still the way they used to, and a builder trusts his numbers or he trusts nothing at all.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_14', text: "I ran a level along my own burrow floor last week, a floor I laid and know to be true. The bubble sat a hair off center, toward the middle of the house. Either my level's gone liar, or the whole house is leaning in, slow, like it's listening.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_15', text: "Even the spade's in on it now. I set it against the wall at night, honest as anything, and by morning it's slid over, blade tipped inward like a compass needle. Tools don't have opinions. Mine seems to be developing one.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_16', text: "I keep filling the odd tunnels back in. The ones that curved toward the center on their own. I fill them and pack them tight, and the next morning the packing's gone loose again, like the ground breathed while I slept.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_17', text: "The third time the packing came loose, I sat down in the dark and listened instead of digging. A long while. And under the quiet there was a sound, if sound's the word. More like the memory of one. Low, slow, patient, coming up through the soles of my feet.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_18', text: "I asked Fennick to come down and put those ears of his to the gallery floor. He listened maybe ten seconds, then stood up and said he'd rather listen from his own room, thank you. Fennick has never once in his life preferred to hear a thing less clearly.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_19', text: "Archimedes came down the shaft to look at my wrong-colored layer. He read it the way he reads his books, real careful, and then he climbed back up without a word. That's twice now a friend's gone quiet on me.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_20', text: "Sloane stopped me in the hall after, moving slower than usual, which for her is saying something. She said, you found the color, then. Not asked. Said. I hadn't told a soul but Ember and the owl. I lay awake on that one a good while.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_21', text: "Three friends gone quiet on me now, and quiet in the same direction, if quiet can have a direction. Nobody says don't dig. Nobody says dig. They just look at me like I'm partway through a story they've already read the end of.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_22', text: "I've been trying to remember why I dug that deep gallery so wide. I still don't know. But every tunnel that curves on its own is curving toward it, and I don't much care for the fact that they all agree.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_23', text: "The air in the gallery moves now. Just faintly, a slow drift toward the center of the floor, like the room's drawing breath through a crack I never cut. I checked every wall for the source of the draft. There's no crack. The air just goes.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_24', text: "I paced the gallery off again to settle my nerves. Forty strides across, the day I finished it. Forty-two now. Rooms don't grow, and I want that on record. Rooms don't grow. Mine is growing.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_25', text: "All my life the work has answered me plain. Set the beam, the beam holds, and the question is closed. Down there I set my questions the same careful way, and every answer just opens a bigger hole underneath it.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_26', text: "I've started leaving a lantern lit down there through the night. Thirty years underground and I never once needed a light I wasn't carrying. I don't look at that habit too closely. I just keep buying oil.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_27', text: "I wrote to my brother about it all. Tore the letter up before sending. He's a digger too, and he'd do what diggers do, come see for himself, and I found I didn't want him anywhere near that gallery. That told me more than the letter did.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_28', text: "Your words settle the additions onto the old base. I can account for the load. I'm less sure what the older stone was meant to hold.", phase: 1, animalType: 'wombat' },
  // Phase 2 (21 + 1 question-web)
  { id: 'wb_2_1', text: "I hit something down at the warm layer, past where any sensible digging stops. I set my spade to it and it wasn't stone and it wasn't root, so I stopped. I want that said plain: I stopped, and I'm not ashamed that I stopped.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_2', text: "I've got no honest word for what it was, and I'll not hand you a dishonest one. A builder who guesses at his materials builds himself a grave, and I've outlived every fellow I knew who guessed.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_3', text: "The stone didn't move. It was warm under my hand and old beneath my tools. I can't get more of an answer from either fact.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_4', text: "The spade rang when it touched. Not a clang, not stone's honest knock. A note. Low and round, and it went on longer than a struck thing ought to, like it wasn't the spade ringing at all. Like it was something answering.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_5', text: "I stood there in the dark a long moment with my hand on the handle, and I had the strangest feeling I've ever had in a hole. The feeling that I was expected. Then I climbed out, and I didn't run, and I'll take credit for the not running.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_6', text: "I filled my inspection shaft back in, packed it, and braced it. It felt like good work. I need to check what I've actually shut.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_7', text: "My packing loosens inward. I won't open it just to prove I can. I'll find where the pressure comes from.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_8', text: "I've sealed springs, sealed gas pockets, sealed a badger's spite-tunnel once. A seal holds because what's behind it pushes even, all around. This one shifts like it's being tried, gently, one stone at a time. Patient hands. If hands is what they are.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_9', text: "Sloane found me re-packing it the fourth time. She watched the whole hour it took, then said, kindly for her, that some doors are load-bearing. I've been chewing on that ever since. A door that holds the house up. You can't pull it, and you can't keep it shut forever either.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_10', text: "I don't re-pack it anymore. I check it, I note the drift in my book, and I let it be. A fellow can spend his strength holding a door shut or he can spend it keeping the rooms his friends sleep in sound, and I've made my pick.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_11', text: "Ember doesn't ask me to open it. She asks after my shoulder, and my supper, and whether the timber's holding, and she never once asks about the seal. That's how I know she knows.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_12', text: "Panko's taken to serving warm things cold, if that makes sense. Soups chilled, breads left to cool. She says the appetite for warmth has gone strange in this house, and she cooks for the appetite that's there. That pangolin notices more than she lets on.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_13', text: "Archimedes finally spoke to me about the layer. One sentence, then back to his books. He said the color has been described before. Described. Somebody, somewhere, wrote down my dirt. I didn't ask where he read it. Some questions you keep in your pocket a while.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_14', text: "Flour ring round the seal. Old trick; shows a draft or a rat. Morning: stones shifted inside it, flour untouched. Whatever moved them didn't cross my floor.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_15', text: "Chill asked me for a drawing of the sealed shaft, for his files, pencil ready. I told him no. First time I ever refused that fellow paper. Some things I'm not ready to see filed under a heading, like they're settled. Nothing about it's settled.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_16', text: "The warmth is coming up. Used to be I had to dig for it. Now I feel it in the floor of my own burrow of a morning, faint, like something below turned over in its sleep and settled a little closer.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_17', text: "It rises slow, the warmth. A floor or so a season, by my reckoning. I've started marking it on the shaft wall the way you'd mark a flood line. Only floods crest and fall back. This one only crests.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_18', text: "I've laid foundations for barns and dens. Here I joined the new work to an older base. Its depth should have made me ask what it was for.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_19', text: "My additions fit the old base unusually well. I keep finding places where I copied a joint without investigating what the older joint did.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_20', text: "My dad used to say the ground remembers every hand that works it. I've started to wonder if it runs the other way too. If the ground was remembering my hands before I ever put them to it. If the work knew me first.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_21', text: "So I don't dig down anymore. I dig sideways, I dig useful, I dig honest. But at night, flat on my back in the burrow, I can feel exactly which way is toward the thing I sealed. I never lose the direction, not once, not ever.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_w1', text: "Thyme's roots lean the same way as my shafts. Ask where her flowers point up top. A drawing from both ends might show what I've been digging round.", phase: 2, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  // Phase 3 (30)
  { id: 'wb_3_1', text: "I can distinguish the support from the older seal now. The purpose of that seal is the next question.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_2', text: "Ran the load figures twice. The base can carry more than anything I've built. Sat on the stone awhile after that. Good work, someone else's purpose. Need to know the purpose.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_3', text: "A good plan states the load. Here I copied dimensions from old stone. My hands did sound work from incomplete instructions.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_4', text: "I went looking for when the spec got into my hands. Traced it back through every job, every season, all the way to the first morning I ever set a spade to this hill. It was already there. I dug my first honest line to a drawing I'd never seen.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_5', text: "Ember pointed at the ground and said dig here, and my hands said yes before my head weighed it. I used to call that trust between friends. It was trust, and I'll stand by that. But something used the trust as a road.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_6', text: "The warm layer isn't a layer. I understand that much now. It's the top of something, and I dug down to the crown of it and called it a floor. There's no floor. There's just the thing, going down and down, patient, waiting on the sky to give it leave.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_7', text: "Ember thinks the approach is from above. The structure directs pressure inward from below. I need both reports before deciding what this place receives.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_8', text: "I thought I was supporting a house. Part of the old work directs pressure toward the center. I want to know who chose that direction.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_9', text: "The fire leans upward, Ember says. I added that to the plan as a reported observation. Then asked Vesper what she could see.", phase: 3, animalType: 'wombat', requiresAnimals: ['tarsier'] },
  { id: 'wb_3_10', text: "So what I touched down there, what rang like an answer, that was the seat knowing its maker had come to check the work. That's all it ever was. I shook hands with the thing I built without knowing I built it. There's a strangeness a fellow doesn't shake off by morning.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_11', text: "Every word you offer, the base takes it and settles firmer. I used to call that comfortable. Now I know it's the house getting ready to bear the load. Bracing. The way I brace a beam before I take the prop away.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_12', text: "I've stopped sealing the deep shaft. What's the use. You don't dam a river by scolding it. I just make sure the upper house is sound, so that when the weight comes down, the rooms my friends live in don't fold in on them.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_13', text: "My brother asked to visit. I told him the house was unsettled. I owe him a clearer account before calling that an invitation.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_14', text: "I've begun going room to room up top, quiet like, checking every beam I ever set. Ember's hearth, Panko's kitchen, the study with all that paper weight. If the sky's going to open over my friends, my friends will be standing under my best work when it does.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_15', text: "Thyme asked whether the house would fall. I showed her the load measurements, then asked what had prompted the question. She had another measurement for me.", phase: 3, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_3_16', text: "Warmth's in every floor of the house now, faint, from the burrows up to the attic. Bamboo feels it up top the same as I feel it down bottom. We meet in the middle of the wrongness, the two of us, and we don't need many words about it.", phase: 3, animalType: 'wombat', requiresAnimals: ['red_panda'] },
  { id: 'wb_3_17', text: "I dream I'm digging and the spade goes soft, into that warmth, and it's not a wall anymore, it's a back. A great patient back, breathing slow, waiting on a sky that hasn't opened yet. I don't wake up scared. That's the part that scares me.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_18', text: "I told Bamboo the dream, since they're the only one who wouldn't make it worse or make it smaller. They listened with their eyes shut, then said, the back has been dreaming you longer. I came down the ladder unsoothed, which I suspect was the honest thing they intended.", phase: 3, animalType: 'wombat', requiresAnimals: ['red_panda'] },
  { id: 'wb_3_19', text: "Fennick's taken to sleeping in my burrow entrance some nights, high end, ears toward the sky now instead of the ground. Says the sound he used to hear underneath everything has moved up. Sounds don't climb. Except this one has, and neither of us said the next part.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_20', text: "The gallery measures forty-four strides. I keep the earlier measurements beside it. A changing room shouldn't erase the evidence of changing.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_21', text: "Thyme's roots have wound clean through my galleries now, every one of them aimed at the seat. She's anxious. I understand why she's anxious. She's the only one of us honest enough to be scared out loud.", phase: 3, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_3_22', text: "Chill came down with his pencil at last, and this time I let him file the sealed shaft. He wrote a heading on the drawing, and I didn't read it, on purpose. If it's got a name in that filing room of his, the name can stay there. I work better unlabeled.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_23', text: "Axel sent word up through the spring, if you can believe that. My west seep ran warm for a day, then cold, then warm again, like something big turning over in its sleep. I don't speak water. But I sat with my hand in it a long while, and what it was saying was soon.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_24', text: "Sloane doesn't say soon anymore. That's how I mark the time now. When the slowest of us stops saying soon, it's because soon has stopped being the right word.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_25', text: "I ground the spade fresh this morning and caught myself doing it careful, the way you dress a tool for a job that matters. Then I stood there wondering which job my hands thought they were dressing it for. They know things before I do, my hands. I've stopped pretending otherwise.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_26', text: "I put my hand against the sealed stone. I know how it was fitted. I am only learning why.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_27', text: "There's a whole season of snapped spade handles up in my store room, cracked at the neck from the months I dug too hard at nothing in particular. I don't snap handles anymore. Make of that what you like.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_28', text: "You should know your words come down here changed. Up top they're bright little things. By the time they reach the base they've got weight, real weight, and the stone takes them the way mortar takes water. I'm telling you because nobody told me what my work fed.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_29', text: "I still take my supper off Panko's rope, and it still goes cold on the way down, and I've come to be glad of that. Cold supper is right. Cold is the honest temperature of the deep, and I hold to every honest thing left down here.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_30', text: "I've set out the old plan and my revised one. Before I make another cut, we should decide what we need it to do.", phase: 3, animalType: 'wombat' },
  // Phase 4 (30)
  { id: 'wb_4_1', text: "I know what holds weight. I'm learning what the old work was meant to hold in.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_2', text: "Old foundations. Your new rooms. Don't let anybody erase your work from the account.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_3', text: "I copied a sound joint. Sound joints can belong to bad plans.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_4', text: "Light here. A groove behind the brace. I missed it checking the load.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_5', text: "A brace holds up. A seal holds shut. They can look alike until you try the door.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_6', text: "Should've asked who drew the plan. I was too pleased someone liked my measurements.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_7', text: "My marks beside the old ones. Mine have dates.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_8', text: "Warm stone tells you about heat. That's as far as that evidence goes.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_9', text: "The wall can argue with chalk. Can't move my hand while I'm watching.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_10', text: "Mind the beam. Mystery doesn't make a cracked skull less inconvenient.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_11', text: "I won't brick up a gap because someone labeled it finished.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_12', text: "An old den and footings before the additions. I remember hauling new timber.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_13', text: "Load travels upward there. The gauge doesn't care if I call it impossible.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_14', text: "A wedge by the passage. Whether to use it depends what we're keeping open.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_15', text: "Thyme measured well. I should've said that before asking why she worried.", phase: 4, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_4_16', text: "Love a house; take a hammer to a part that's hurting somebody.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_17', text: "The plan shows one outline. Buildings need joints. So do their occupants.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_18', text: "The shovel handle fits me. If it comes back smooth, I'll roughen it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_19', text: "No need to admire the tunnels. Tell me if something feels wrong.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_20', text: "I removed the pretty facing. It hid the connection.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_21', text: "Dirt on the ceremonial robe. Dirt on my other clothes. Consistent standards.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_22', text: "Deep meant secure, I thought. Depends what you're standing over.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_23', text: "If I built it, I can explain how. If I don't know why, I'll say.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_24', text: "No alterations allowed in the old plan. A defect in the plan.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_25', text: "Keep rubble until repairs hold. Don't lose evidence halfway through a job.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_26', text: "Ember brought a cup. I made her put it somewhere that wasn't my chalk line.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_27', text: "The earth never promised anything. I said otherwise when work went well.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_28', text: "Nobody gets buried in a promise I built if I can help it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_29', text: "Rest on the crate. Rated for more than worrying.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_30', text: "Whatever we keep, we ought to know its edges.", phase: 4, animalType: 'wombat' },
];

const RABBIT_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'rb_0_1', text: "The thyme is in this bed. I'm the other Thyme. Labels help.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_2', text: "Mind the gate. It bangs, and I drop whatever I'm carrying.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_3', text: "I grew those flowers from seed. I keep wanting to introduce you to each one.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_4', text: "The path bends because a flower came up where I'd planned the straight bit.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_5', text: "I make lists. They keep thoughts from running through the beds unsupervised.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_6', text: "This is chamomile. Better tea if you stop steeping before remembering three other jobs.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_7', text: "I once drowned a fern with devotion. I'm trying measured water now.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_8', text: "There are twelve ways out if you count behind the mint.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_9', text: "I like knowing where a path goes. I can enjoy the walk afterwards.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_10', text: "I packed spare seeds in this tin. A little future that fits in a pocket.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_11', text: "The beetle looked frightening until it fell off a leaf. We both had a difficult minute.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_12', text: "I watch the sky for rain. And for hawks. Rain receives a warmer welcome.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_13', text: "You can help tie this stem. Gently. It doesn't know you're trying to help.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_14', text: "The watering can leaks. I use the leak for the seedlings.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_15', text: "I grew every one of these. Yes, that's a boast. I'm practicing.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_16', text: "A list of finished jobs is a pleasant thing to sit beside.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_17', text: "Sometimes I check the latch twice. The second time usually tells me about myself.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_18', text: "Please don't call the tiny flowers weeds until I've identified them.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_19', text: "The north bed sprouted early. I have written down the date instead of deciding why.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_20', text: "Someone left a biscuit by the gate. I hope it was for me. The evidence is gone.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_21', text: "Tea while I work? You can sit where I can hear you.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_22', text: "I keep an empty pot for surprises. So far, mostly beetles.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_23', text: "There is string in the seed tin. Seeds in the string box. I am revising the labels.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_24', text: "Visit whenever. Call from the gate so I can put the watering can down first.", phase: 0, animalType: 'rabbit' },
  // Phase 1 (28)
  { id: 'rb_1_1', text: "I have to tell you something, and please don't think me foolish. That root I turned back last time had turned again by morning, and it isn't only that one.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_2', text: "I lifted a pot to repot it and found every root inside had grown to one side, all of them curled the same way, toward the house. I told myself roots simply follow water. I've been telling myself that for days now.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_3', text: "Since the pots I've counted fourteen other small leanings, the ivy and the runner beans and the parsley gone sideways in its window box. I didn't go looking for any of them. They're simply there now, everywhere I rest my eyes.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_4', text: "I ran a little test, which isn't like me at all. Tests belong to Archimedes. I planted six beans in six pots and turned each pot a different way, like setting clocks.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_5', text: "Every bean came up leaning the same direction. Not toward the window. Not toward the water. Toward the wall the house stands on. I wrote it down with a very steady paw and then sat in the shed for a while.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_6', text: "I moved a whole bed to the far end of the patio, as far from the house as the stones allow. By the third morning the new shoots had leaned back the same way, and I sat down on the path and I'm afraid I cried a little.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_7', text: "Ember found me there and said the reaching wasn't wrong, only honest, that plants lean toward what they need. She meant it kindly. She always means everything kindly.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_8', text: "Because if she's right, then the roots need whatever is inside the house. I don't truly know what's inside the house, and I'm the one who tends all the growing things.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_9', text: "I asked Ember what the fire needs, since she's always reading it. She looked at me for a long moment and said, company. I've been turning that answer over for three days now.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_10', text: "I counted the pots this morning and for once it didn't settle me at all. They were all present. Every single one of them was leaning.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_11', text: "The warm patch by the wall has grown into a warm strip now, running toward the center of the house. The thyme along it comes up thick and glad, as if it likes the warmth I can't explain.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_12', text: "I laid a thermometer along the strip, feeling silly, feeling scientific. The reading was perfectly ordinary. My paw on the same stone said otherwise. I no longer entirely trust one of them, and I'm not certain which.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_13', text: "Do you hear it, underneath the birds? A low sound, very patient, like the note a hive makes but slower. The bees don't seem to mind it, and that frightens me more than if they did.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_14', text: "I asked Fennick about the sound, because ears like his don't invent things. He held very still, and then he said, you hear that too. Not a question. He sounded relieved, and I felt worse.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_15', text: "Fennick told me it has been there longer than I've been listening. That's the sentence I took to bed with me. Longer than I've been listening.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_16', text: "Panko asked me for the fastest-growing herbs, the ones that fill a space quickest, and I gave them gladly. Only later did I wonder why the house should want filling.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_17', text: "I watched Panko hang the bundles in her kitchen, every stem pointing the same way, and she called it tidiness. I know tidiness. Mine faces every which way. Hers faced inward.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_18', text: "I've started keeping a second list, a private one, of the small wrong things. The first list keeps the garden. I don't yet know what the second list is for.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_19', text: "I finally brought my little notebook to Archimedes. He read my second list the way he reads everything, twice, and then he said, would you leave this with me. Not, this is nothing. Would you leave this with me.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_20', text: "He was so gentle about it that I nearly missed how carefully he didn't reassure me. Archimedes chooses his words the way I choose seed stock, and he chose none of the comforting ones.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_21', text: "My list lives in the study now. I kept a copy, of course. I'm anxious, not careless.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_22', text: "Axel says the weed in his tank has started leaning too, and there's no sun in that room to lean toward. He said it dreamily, the way he says everything, as if leaning were a kind of dancing.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_23', text: "Chill patted my paw and told me every house settles, and the garden is only settling with it. It's a very reasonable explanation. I've noticed the reasonable explanations are getting shorter than the things they explain.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_24', text: "I want so badly for all of this to be nothing, a quirk of the soil, a trick of the slope. I'm very good at wanting things to be nothing. I'm simply running out of nothings.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_25', text: "Today's words left a dent in my paw, like seeds beginning to swell. I planted them along the warm strip. Then wrote that down. I don't remember choosing the strip.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_26', text: "I've begun to wonder whether the garden grows for the house, or the house grows the garden. That's a silly sentence. I've read it back four times now and it won't become silly.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_27', text: "Sloane said, in her long slow way, that noticing is a gift given early. I asked, early before what. She had fallen asleep. Or she chose that exact moment to seem to.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_28', text: "Tell me the garden is only a garden. I won't fully believe you, but I'd dearly love to hear it said out loud by someone who isn't a plant, or me.", phase: 1, animalType: 'rabbit' },
  // Phase 2 (21 + 1 question-web)
  { id: 'rb_2_1', text: "It's the whole garden now, not the roots only. The stems, the flower heads, even the fence posts have taken a lean, all of it bowing toward the middle of the house like a congregation that has been told exactly where to look.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_2', text: "I stopped fighting it in the beds. When I propped a stalk straight it snapped, and the snapping felt worse than the leaning, so now I let them bow. I tell myself I'm only being gentle. If I'm honest with myself, I think I'm being obedient.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_3', text: "The blooms have begun opening in an order. Not my order. The bed flowers from the outside in, one ring at a time, closing on the middle like a slow eye. I planted them all on the same day.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_4', text: "The warm strip has become the warmest thing in the garden, warmer even than the sunned stones, and cold now sits where the sun falls. I've written that in my private list and underlined it twice.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_5', text: "Here is the part I can't put down: I understand it now. Not the words for it, but the shape of it, the way you know a storm is coming by the feel of the air long before you know a single thing about the sky.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_6', text: "Archimedes says the pattern in my beds matches a pattern in his old books. He said it kindly, the way you'd point out a shared birthday, and I haven't slept well since he told me.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_7', text: "He showed me the page. I'd braced for something dreadful, and it was only a diagram, circles and lines, tidy as a planting chart. That was the dreadful part. My garden has been following instructions.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_8', text: "The low sound under the birds is under everything now. I hear it in the watering can, and in my own chest when I lie very still. It's patient the way roots are patient.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_9', text: "The bees circle once, turn toward the house, stop. No flower direction. I drew it three times. I'm leaving the old dance beside it so I don't forget which was which.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_10', text: "I went and told Chill all of it, the lean and the rings and the sound. He listened with his whole kind face and said, then we're exactly where we're meant to be. I'd wanted him to say something else. I wanted anyone to say something else.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_11', text: "I moved the tenderest seedlings indoors to save them from the lean, and by dawn they'd turned toward the same center from inside the house. There's no far end of the patio anymore. There's only nearer and farther from it.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_12', text: "The words you offer go down to the pit, and I picture them settling into soil I can't see, and something feeding on them, and coming up. I'm the gardener. I know exactly what feeding looks like when it's working.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_13', text: "Panko came for the harvest with two baskets instead of one and said the house eats better than it used to. She meant it warmly. Everything here is meant warmly. That has stopped being the comfort it once was.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_14', text: "Warren offered to dig my beds deeper, right down where the soil stays warm, he said. I asked how he knew it stayed warm down there. He looked at me kindly, and didn't answer, and dug.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_15', text: "I understand a garden. Ready ground, patient feeding, everything turned toward one point of light. What I'm standing in is a garden. I simply no longer believe that I'm the gardener.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_16', text: "Tonight's understanding was the trellis. The roses have tied themselves to it in flat, even loops, fastened tighter and truer than any knot my own paws can manage. I stood in the dusk being taught knotwork by a rose.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_17', text: "I dream in rows now. Long tended rows converging on a dark, warm center, and in the dream I'm not frightened, and waking into my own fear is almost a relief. It proves I'm still myself.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_18', text: "I tried leaving one corner untended, a single wild square, just to watch something in this garden choose its own direction. Within the week the wildness had a pattern in it too. Neater than anything I ever taught.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_19', text: "The thyme by the step, my very first planting here, has crept the whole length of the warm line to the wall of the house. It has never looked so well. My name is growing all along the fuse, and it's thriving.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_20', text: "I'm still here at dusk all the same, tucking in the beds one by one the way I always have, because someone kind should be minding the garden even now. Especially now. Please don't call that brave. Call it habit, and let me keep it a little longer.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_21', text: "Stay just another moment, would you. The garden calms when you're in it. So do I. And I've begun to wonder, very quietly, whether that's one more thing arranging itself.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_w1', text: "Bamboo isn't afraid of the garden leaning inward. Ask them why. Please bring the answer as they say it. I can decide what to do with it after I've heard it.", phase: 2, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  // Phase 3 (30)
  { id: 'rb_3_1', text: "I'm done pretending it's soil chemistry. I've known what's coming for a good while now, and I kept setting the knowing down the way you set down a heavy watering can. It's time I admitted that I can't put it down anymore.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_2', text: "Something is arriving. Not growing, arriving, the way weather arrives, and the garden has been readying the ground for it the whole time. I helped, because tending is all I have ever known how to do.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_3', text: "My first list has fallen behind, the tidy one that keeps the garden, and I haven't brought it current in a week. All my writing goes to the second list now, the one of wrong things, and it has outgrown its notebook. I've started a third page I don't yet have a name for.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_4', text: "The flowers open at night now. Moonflowers I never planted, white as paper, every face tipped straight up. A garden looks where it's told to look, and mine has stopped looking at the sun.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_5', text: "When I close my eyes now there's a shape behind them, always the very same shape, patient, waiting for the light to be right. I open my eyes to make it stop, and the garden is bowing toward the exact spot where the shape stands in my dark.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_6', text: "Ember says the fire has started telling her the same thing my roots tell me, that we're simply two windows onto one room. I used to find her frightening. Now I only find her early.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_7', text: "Axel asked me to look into the rain barrel with him. I saw sky, and then I saw the sky open, just for a breath, like a seed coat splitting. He steadied me and said, it's gentler in the water. I don't want to learn what it's like out of the water.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_8', text: "Fennick doesn't say all is well anymore. He sits at my garden wall at dusk with his ears high, and when I bring him tea he takes it without once looking away from the sky. We don't talk. We keep watch.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_9', text: "So I water the things that lean, and I hate that I do it, and I do it anyway. Stopping would only leave the beds untended when they most need a kind hand.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_10', text: "I've started a tin of seeds. One of every plant I love, sealed dry, tucked at the back of the shed. I couldn't tell you what after looks like. I only know that a gardener saves seed before a hard season.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_11', text: "Warren has been digging deeper than the roots go, and the roots have started following his tunnels down toward the pit. Even underground, everything wants to be nearer the center. There's no direction left that isn't toward it.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_12', text: "The words you bring are the heaviest they have ever been. I plant each one and feel the ground take it so eagerly, and I think, that's one more. I never finish the thought, because I know precisely what it's one more toward.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_13', text: "The beds have finished their pattern. From the attic window you can see it whole, rings and lines, a great tidy sigil drawn in green, and my own paws made every stroke of it. I signed something I couldn't read.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_14', text: "I asked Panko to stop preparing so much. She looked at me with such tenderness and said the guest is nearly here, and one doesn't stop cooking when the guest is already on the road. I went home and couldn't eat a bite.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_15', text: "You're the one who keeps coming, the one whose words the garden drinks. Someone who knows what this garden is should be standing beside you when you visit it. So I stand there. It isn't quite bravery, but it's the nearest thing to it that grows in this soil.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_16', text: "I asked Bamboo why they weren't afraid. They answered with rain. I asked again, because I meant this house.", phase: 3, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_3_17', text: "Sloane said she'd waited longer than I'd been alive. I told her waiting longer wasn't the same as knowing more about what I had measured.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_18', text: "Archimedes reads to me in the evenings now, out on the patio. Not from the old books. He reads me seed catalogues, orchard almanacs, anything with a spring in it. He knows exactly what he's doing, and I love him for it.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_19', text: "The warm strip is hot now. Cold has taken the rest of the garden, a still, waiting cold. The one hot line runs straight to the middle of the house like a fuse that someone has already gone and lit.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_20', text: "I dug up one of the words you brought last month, just to see. Where I'd planted it the soil was dark and rich and warm, the finest soil I have ever touched, and nothing of the word was left. Whatever eats down there eats thoroughly, and it's fed by my own two paws.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_21', text: "On my dusk round I counted the beds, then the lit windows. Everybody home. Everybody leaning toward the middle. I counted again. I wanted the second count to be different.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_22', text: "I half-packed and went to the gate. I checked the latch, then the route beyond it. The latch was the easier answer.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_23', text: "Don't misunderstand me. No one here would stop me leaving. Every keeper in this house would help me carry the bag, and that's somehow the most frightening fact I own. Whatever holds me here, it isn't them.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_24', text: "Chill found me trembling among the bean rows and simply sat with me until I stopped. He never once said it would be all right. He's too honest for that, underneath all the calm. He just stayed. It helped more than the truth would have.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_25', text: "I count the pots again at night. The old habit, come back with its coat on. Only now I catch myself counting toward something, as if the garden and I are both keeping a tally that's very nearly complete.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_26', text: "The words you bring lately, I recognize some of them. Dark ones, hollow ones. I plant them because that's the task, and the ground takes them like rain after drought. I'm sorry, I'm so sorry, and I don't even know yet what I'm apologizing for.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_27', text: "I asked Ember how long we have. She read the fire for a great while, longer than she has ever needed, and then she said, before the seed you saved can sprout. I went home and looked at my tin for an hour.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_28', text: "The night sky over the center of the house has a texture now. I have excellent eyes for small differences, it's my whole trouble. I'm telling you the dark above us has a grain in it, like soil seen very close.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_29', text: "It's close. I can feel it in the soil the way you feel a storm in your teeth before the first cloud. The birds have gone quiet about it, and the bees haven't stopped their new figure once, not even at night.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_30', text: "I want to be here because I like my garden. I would like that to remain a reason I can change.", phase: 3, animalType: 'rabbit' },
  // Phase 4 (30)
  { id: 'rb_4_1', text: "The latch caught when warm. I filed it. A useful worry.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_2', text: "Facts and guesses on separate sides. Fewer facts. Good facts.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_3', text: "You can help check if you're tired of hearing about checking.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_4', text: "The seed tin is within reach. I haven't decided anything.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_5', text: "Some flowers turn inward. Some don't. Both sorts marked.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_6', text: "I like my garden. I don't have to like everything happening in it.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_7', text: "Bamboo says gentle. How does gentle feel to a seed breaking its shell?", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_8', text: "Counting exits isn't knowing where they lead.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_9', text: "I did ask Bamboo why they weren't afraid. They answered about rain. I needed an answer about us.", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_10', text: "Shaky paws. Reliable measurements.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_11', text: "One bed unplanted. I might want different flowers later.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_12', text: "The chamomile thrives. Outperformed by my own calming tea.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_13', text: "Don't call me brave yet. Sometimes that means please keep going.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_14', text: "I want Ember to visit. I want her to stop deciding which truths I can manage.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_15', text: "I weed the mint path even when I'm not going anywhere.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_16', text: "Sky: frightening. Beetle eating seedlings: infuriating. Both at once.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_17', text: "I used to apologize before warnings. It took up warning time.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_18', text: "Seeds stay in the tin. I don't have to plant everything.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_19', text: "Never afraid again? I'd like the rest of that promise.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_20', text: "Warren found a mistake in my diagram. Then one in his.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_21', text: "Tea without teaching me what tea means? Please?", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_22', text: "Packed twice. Biscuits in the second packing. An improvement.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_23', text: "I want another spring because it'll be different.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_24', text: "I want reassurance. I also want the truth.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_25', text: "The house straightened my rows before I'd decided where the path should bend.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_26', text: "Fond of everybody here. Annoyed with quite a lot of them.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_27', text: "That little flutter in my chest belongs to me. Let me decide what to do with it.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_28', text: "Stand beside someone without agreeing. I'm practicing with Bamboo.", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_29', text: "If I ask for space, you haven't failed at comforting me.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_30', text: "Leave the watering can where I put it. Small thing. I'm asking anyway.", phase: 4, animalType: 'rabbit' },
];

// TARSIER (Vesper) - The unblinking night watcher whose vigil holds the way open
const TARSIER_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'tr_0_1', text: "Up here. I tend to forget everyone isn't already looking at the rail.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_2', text: "Vesper. Night watch, with occasional breakfast at unreasonable hours.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_3', text: "The lantern is unlit so I can see the valley.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_4', text: "My eyes stay fixed. I turn my whole head. Demonstrations available.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_5', text: "A moth is lovely. Also supper. I manage both appreciations.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_6', text: "I chalk the star positions. Rain edits my work without asking.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_7', text: "When I look at you, you have all my attention. Let me know if it's too much.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_8', text: "The porch is warmest just before dawn. Excellent place to finish a night.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_9', text: "I inherited this watch log. A lot of diligent entries and very few explanations.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_10', text: "That moth has circled twice. I admire persistence but won't reward it indefinitely.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_11', text: "The best sleep is after watching dawn arrive on time.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_12', text: "I have a favorite star. It hasn't noticed. A comfortable arrangement.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_13', text: "My quietest note is above most creatures' hearing. Fennick can hear it.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_14', text: "I sing to check my breath. Fennick sometimes answers. We haven't agreed who's leading.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_15', text: "Most creatures can't hear our duet. This protects my reputation.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_16', text: "The chalk box needs a lid. I have solved many sky problems and postponed this one.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_17', text: "A fixed gaze makes a small movement conspicuous.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_18', text: "There is a darker patch above the ridge. I marked its edges instead of naming it.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_19', text: "I turn my head to think. People assume I've spotted something. Usually it's an unanswered question.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_20', text: "The beetle under the lantern is allowed until dawn. We have arrangements.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_21', text: "I like the stars without names. Less conversation to catch up on.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_22', text: "Bring a blanket if you stay. Warm opinions won't cover your feet.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_23', text: "I named one star Yours. An inconvenient name when explaining which star I mean.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_24', text: "Come after dusk. I'll show you what changed while the house was busy downstairs.", phase: 0, animalType: 'tarsier' },
  // Phase 1 (28)
  { id: 'tr_1_1', text: "Something small and new, for your ears only. The dark has a grain to it lately. Like wood, like water. All my life the night has simply sat over the valley, evenly, the way dark should. Now it lies in one direction, and the direction is toward this house.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_2', text: "I checked the grain three ways, because a watcher checks. The moths drift with it when they stop flapping. Fallen feathers lie along it. My own fur settles into it when the wind has gone. Everything loose in the night agrees about which way the night is going.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_3', text: "I'm not troubled, before you ask. Rivers have directions and nobody calls them sinister. But I've watched this valley a long while, bright one, and the night never used to flow. It used to pool. Something downstream has opened, and I intend to find out what by watching very hard, which is the only method I own.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_4', text: "The middle of the sky is being kept clear. I noticed it the way you notice a swept doorstep. The little stars, my shy ones, the between ones, they have all shifted a hair outward from one patch of dark above the house, and stars don't shuffle. Something asked them, and they're polite.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_5', text: "I watched the cleared patch all night to see what it was for. Nothing came. But it wasn't an empty nothing, if you follow me. It was a reserved nothing. A chair with a coat over the back of it.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_6', text: "The Latch and the Spoon have held their places, which comforts me more than it should. Yours has moved closer to the middle. I'm deciding not to draw conclusions from that. I'm, as you can hear, not entirely succeeding.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_7', text: "I sang to the valley in my over-voice last night, the usual greetings, small polite things. And underneath my last note, right at the floor of the world where my voice has no business having an echo, something answered. One note. Lower than low. Not unfriendly. I've been carrying it around all day like a warm stone.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_8', text: "Fennick knows the answered note. Weeks of hearing it below the house; mine came from above. We marked both directions. A second pair of ears has complicated the map usefully.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_9', text: "The obvious thing, since you aren't Fennick and can't hear me not saying it: above and below are answering each other. My little voice happened to sing in the space between. I wasn't the conversation. I was a bird that landed on the wire. But the wire, bright one. The wire is humming.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_10', text: "The moths changed their loose circle into a spiral. I marked both routes in the log. Then caught one for supper.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_11', text: "Same chalk spiral, deeper each night. I recognized its curve when I stepped back: the stars around the cleared patch. I have kept the porch drawing beside the sky chart.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_12', text: "Archimedes asked which book I'd copied the spiral from. None. He knows I haven't opened his books. He wrote down my answer and thanked me twice.", phase: 1, animalType: 'tarsier', requiresAnimals: ['owl'] },
  { id: 'tr_1_13', text: "The dark patch seems nearer. Same position above the ridge, different sense of distance. I have two columns now. Position is measured. Nearness is what I feel.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_14', text: "One hour facing east. When I turned back, the patch was unchanged. It doesn't seem to need my watching to stay there. I was pleased with that result. Record the pleasure too.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_15', text: "The patch is easy to watch for too long. I began counting how often I look away, instead of assuming my attention proves my discipline.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_16', text: "Axel's water shows a second sky after dark. Different lights, below the reflected stars. I stayed until my neck ached. He held a weed aside so I could finish the sketch.", phase: 1, animalType: 'tarsier', requiresAnimals: ['axolotl'] },
  { id: 'tr_1_17', text: "Bamboo's incense leans inward. My night chart does too. At dawn we compared directions on the top step. The house lies between the two. We needed a larger sheet.", phase: 1, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_1_18', text: "Ember brought tea to the midnight watch. She asked how the fire looks from here. A doorway. She said it looks that way from inside too. I added the second viewpoint.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fox'] },
  { id: 'tr_1_19', text: "At the start of watch I wait for the low note. If it comes, I answer. Last night I wrote down how long I waited: longer than my greeting used to take.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_20', text: "It feels familiar. I am trying not to promote that feeling into proof that it is safe.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_21', text: "I told the moths about the low note, out loud, in my day voice, because saying a thing to moths is how I hear myself think. They spiraled on, unbothered. Moths have never once been surprised by anything in all my years of watching them. I used to find that comic. Lately I find it instructive.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_22', text: "Warren reports warmth beneath the house. I report a change above it. He held my chart while I marked where his tunnels run. His paw left a little soil on the ridge.", phase: 1, animalType: 'tarsier', requiresAnimals: ['wombat'] },
  { id: 'tr_1_23', text: "The dew fell in rings around the house. I sketched them before sunrise. Thyme should see the drawing before somebody tells her it was ordinary dew.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_24', text: "I've begun keeping two ledgers. The old one, moths and beetles and winds, because the small true things deserve their bookkeeping whatever else is happening. And a new one, thinner, where I write the grain of the dark, the cleared sky, the spiral, the note. The thin ledger is filling faster. I want it on record that I noticed that.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_25', text: "Yours, the star I named for you, is at the cleared patch's edge. I check it first each watch. Its position is still steady. I would tell you if it changed.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_26', text: "Tonight I caught myself reading an expression into the dark patch. I have drawn what I saw. Tomorrow I'll compare the drawing before choosing a word for the face.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_27', text: "The hour before dawn is warm now. Used to be the coldest part of watch. I've marked the change for seven mornings. On the eighth I said good night to it.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_28', text: "The night isn't finished becoming whatever it's becoming, and I wouldn't dream of rushing it. I have the eyes, I have the rail, I have the patience of a very old line of watchers. Sleep well in the bright, my friend. I'll keep the ledgers. Come back and I'll read you the newest page.", phase: 1, animalType: 'tarsier' },
  // Phase 2 (21 + question-web)
  { id: 'tr_2_1', text: "I used to mark only the stars. Most of the sky escaped the log. Now I draw the spaces between them too. The pages fill much faster.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_2', text: "A moth died on the rail last week, mid-spiral, folded down out of the air with no fuss at all. I sat with it until dawn. Not grieving exactly. Attending. Where does a moth's circling go when the moth is done circling? Somewhere, I think. The spiral didn't look finished. Nothing about it looked finished.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_3', text: "The lantern glowed. No oil, wick or match; I checked all three. I watched until dawn without waking anyone. Next time I want a witness before the light goes.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_4', text: "I keep asking when the lantern began glowing. Perhaps the change was in my seeing. I have no earlier measurement. It is an irritating gap in a very long watch.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_5', text: "I can follow your words' glow below the ground. Then I lose sight of it. I used to write vanished. I've corrected that to beyond my view.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_6', text: "The cleared patch is wider. Its edge stays sharp; my gaze finds nothing to settle on inside. I count the surrounding stars when I need somewhere firm to put my eyes.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_7', text: "I have never felt alone on watch. Old country or this rail. I called it company and liked it. The lantern makes me wonder how large that company has been.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_8', text: "Sloane says nobody has ever been the only one awake. I waited for the rest. That was all. I wrote her sentence in the margin, where I keep other watchers' accounts.", phase: 2, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_2_9', text: "The low note answers before I finish singing now. I changed my last note. It answered the old one.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_10', text: "Each dusk seems to resume where the last night stopped. A repeated watch with a change in it. I can show you the changes. I can't tell you what's learning them.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_11', text: "Thyme asked whether the night is safe. It has never harmed me, I said. That doesn't establish safety for her. We stayed by the gate until she had finished asking.", phase: 2, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_2_12', text: "I left the rail and walked the ridge. Same watched feeling from below. Came back before dawn with damp hands and a new entry: inside the observation for once.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_13', text: "A new column: what the night wants. My paw kept writing nearer. I have changed the heading to what I think it wants. Small letters. An important correction.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_14', text: "Bamboo calls the warmth attention. If so, it reaches above and below the house. I put their word beside the temperature marks. The word explains more than the marks can prove.", phase: 2, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_2_15', text: "I asked what the watch was for. The same low note answered. I had nearly mistaken familiarity for an explanation.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_16', text: "I give Thyme the smaller truths when she asks about the watch. I thought that was care. I am keeping the complete log where she can ask to read it.", phase: 2, animalType: 'tarsier', requiresAnimals: ['rabbit', 'fox'] },
  { id: 'tr_2_17', text: "Every moth settled on the lantern glass. Still until dawn. The next night it shone brighter. I marked both times. Unlit no longer describes it, however long I've used the name.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_18', text: "I sleep less in the day now, and it isn't worry. I know worry from my grandmother's stories and this isn't its shape. It's the sleep of a creature before a journey, light and provisional, one ear out of the blanket. My body is keeping itself available. For what, it hasn't told me. Bodies are honest but they aren't forthcoming.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_19', text: "Fixed eyes; a full turn for every look. The text calls it an instrument's design. I know what my eyes can do. I am slower to accept who they were made for.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_20', text: "Fennick's direction and mine meet now. We nearly stopped keeping separate notes. I asked him to keep his. Agreement is easier to check when there are still two accounts.", phase: 2, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_2_21', text: "Every light went out for one breath. Stars, lantern, pit. I saw something in that interval. I can't describe it yet. One breath is the measurement I can give you.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_w1', text: "Fennick keeps listening after my greeting ends. Ask what he hears then. I have timed the silence. His account belongs beside mine.", phase: 2, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  // Phase 3 (30)
  { id: 'tr_3_1', text: "I inherited a watch and assumed guard was the word for it. The old diagrams suggest something else. I don't yet know how much my watching helps it.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_2', text: "I can make the old watch log sound like preparation for this. I can also find entries with quite other concerns. I am keeping those pages.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_3', text: "My grandmothers kept the same watch. The book treats that as agreement passed down with our eyes. I can inherit their log. I still have to decide where I stand.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_4', text: "A shape holds in the cleared sky. No descent I can measure. My eyes ache when I turn away, but I turn. Rest belongs in the watch schedule too.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_5', text: "The seam seems clearer while I hold my gaze on it. I look away and check the chalk. I need a second watcher before declaring that my eyes hold it open.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_6', text: "At moonset Fennick stood beside me. His ears and my eyes pointed along one line. I drew it across both maps. He asked me to leave our old bearings visible.", phase: 3, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_3_7', text: "The low note felt like thanks for keeping the way open. That is my translation. I liked hearing it enough to hold the rail tighter. Put that beside the translation.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_8', text: "Bamboo watches beneath the roof gap; I keep the porch. At dawn we ask whether the way held. We used to ask how the other slept. I miss that question.", phase: 3, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_3_9', text: "Thyme asked if it was coming for us. I answered to us. She said a changed preposition hadn't answered her question. I turned from the sky and tried again.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_10', text: "The moths trace their spiral above the lantern each night. I've stopped eating them. It complicates supper. Archimedes calls them messengers; for now, I am watching where they go.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_11', text: "Your letters settle; amber gathers below; the cleared sky changes above. Three entries at the same time. The pit is involved. I can no longer call it the end of the journey.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_12', text: "Archimedes read a passage about fixed eyes holding a way open. I fit its description. I asked him to leave the book. I want to read the part before it too.", phase: 3, animalType: 'tarsier', requiresAnimals: ['owl'] },
  { id: 'tr_3_13', text: "I left the rail for a night to test the book. Pressure behind both closed eyes until dawn. When I returned, it eased. I wrote relief in the log. Not proof.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_14', text: "Sloane says my grandmothers watched this arrival before I was born. I have their logs. Tonight I am looking for their own words about why they stayed.", phase: 3, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_3_15', text: "I want to see it arrive. That is a large want, and a partial account of me. I also want a morning afterwards with somebody to talk to.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_16', text: "I straighten the watch marks and sing the stars at the edge. Familiar work I don't remember learning. I've left one mark crooked to see whether my hand goes back to it.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_17', text: "Ember asked what I knew. I showed her the chalk marks and the unanswered questions. Her fire, Bamboo's smoke, Sloane's waiting: none of them makes my evidence complete.", phase: 3, animalType: 'tarsier', requiresAnimals: ['fox', 'red_panda', 'sloth'] },
  { id: 'tr_3_18', text: "An hour's sleep at a time, under the eave. I dreamed I was a doorframe. Woke rested and wrote it down. Then added an extra hour off watch. Frames need maintenance.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_19', text: "The lantern makes the ink clearer than daylight does. I keep the log beside it. The porch door stands open. I noticed I had opened it without making an entry.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_20', text: "Come to the rail before the sky changes again. I'll show you Yours first. The view is beautiful. I can promise you a place beside me, and an honest report.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_21', text: "Dust, petals, Thyme's seed paper: lifted toward the sky and set down. The paper returned with the marks intact. I watched the whole journey. I couldn't see what held it.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_22', text: "The table and foundation are nearly ready. My watch continues until the way opens. I am proud to be trusted with it. I have asked who takes the watch afterward.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_23', text: "Chill kept the middle watch with me. No questions. At dawn he wrote vigil, ongoing in his ledger and showed me. I asked him to add the hours we shared.", phase: 3, animalType: 'tarsier', requiresAnimals: ['capybara'] },
  { id: 'tr_3_24', text: "My high call and the low note alternate. A counting song. Each new arrangement shortens the interval. I enter the intervals in the log. I don't sing over the gaps.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_25', text: "I want to see what happens. I can't turn that desire into a claim that my whole life was made for one sight.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_26', text: "Even the Latch has leaned toward the cleared patch. I named it for holding steady. Tonight I kept the name and changed the position on my chart. The old mark remains.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_27', text: "I nearly merged the two logs. The ordinary sightings would have vanished into the account of the approaching shape. I've kept them separate.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_28', text: "Thyme sent a moonflower with a note: so something soft is with you. It opens toward the cleared sky. I put the pot beside the lantern and kept her note under the log.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_29', text: "I don't know what my watch will be for afterwards. There may be something else I want to look at.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_30', text: "When the sky changes, I'd like to hear someone beside me. Looking isn't the only way to keep company.", phase: 3, animalType: 'tarsier' },
  // Phase 4 (30)
  { id: 'tr_4_1', text: "An edge on the dark patch. I marked it. Chalk is less excitable than memory.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_2', text: "An inherited watch isn't an explanation. My family didn't know what we watched for.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_3', text: "A seam above the ridge. I can't see where it leads.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_4', text: "It draws my attention back. I record what interrupts the pull.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_5', text: "Your face does. A moth does. Grateful to both.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_6', text: "I want to see what happens. A desire, not a recommendation.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_7', text: "I shade the lantern to watch the valley. Brightness isn't always help.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_8', text: "Turning my whole head includes turning toward a friend.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_9', text: "Fennick noticed when I changed the note I use to check my breath.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_10', text: "We tried a duet. Following is harder for me than watching.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_11', text: "I crossed out safe. I meant unharmed so far.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_12', text: "Farther sight gives mistakes more territory. It doesn't prevent them.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_13', text: "Moths for supper. An omen's moth is still a moth.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_14', text: "A star shifted against the chimney. I checked the chimney too. Warren appreciated that.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_15', text: "Tomorrow with something still to learn. I'd like that.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_16', text: "My other notebook holds what I saw looking away. The better book.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_17', text: "Sometimes my head goes under my arm. These eyes need somewhere to rest.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_18', text: "Please don't ask me to watch you sleep. I need time off.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_19', text: "Sky offers detail. Almost none tells me what to do.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_20', text: "Thyme spotted the gate. I watched farther away. Farther isn't always useful.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_21', text: "Chalk marks can be wrong. They can't change unnoticed.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_22', text: "No refusal instructions in the old log. I can write new instructions.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_23', text: "I want to be seen. Also to choose when I'm alone.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_24', text: "A beetle hides under the lantern. I pretend not to notice until dawn.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_25', text: "Watching is what I do. I don't want it to be everything I am.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_26', text: "Ask what I saw before asking what I thought it meant.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_27', text: "The notebooks drift together. I put a stone between them.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_28', text: "I haven't named it. A name makes it too easy to recognize wrongly.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_29', text: "Your words arrive as light. I didn't understand that when I first admired them.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_30', text: "When the sky changes, I'd like someone beside me reporting what I missed down here.", phase: 4, animalType: 'tarsier' },
];

// AYE-AYE (Tock) - The gentle diviner of hollow places who keeps the unrung bell
const AYE_AYE_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ay_0_1', text: "Tok, tok. Hello. I try not to tap that on sleeping creatures' doors.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_2', text: "Tock. Aye-aye. The long finger gets introduced after the rest of me.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_3', text: "The bell has never rung. I'm newly responsible for her continuing excellent silence.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_4', text: "Tap a board, hear a hollow. A useful beginning to knowing a room.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_5', text: "Some hollows contain grubs. The work has refreshments.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_6', text: "I arrived from the night woods by way of several unfriendly villages.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_7', text: "Vesper sent word of a room. I came to see whether the word could be trusted.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_8', text: "This tower sounds different at each landing. I enjoy a well-voiced staircase.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_9', text: "I sleep in the day. A noon visitor may enjoy my feet without much conversation.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_10', text: "This finger is meant to be long. I have answered before the usual question.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_11', text: "I polish the bell around one little scratch. She may wish to keep it.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_12', text: "The bronze holds the warmth of my hand for longer than wood.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_13', text: "I keep a gnawing block here. Teeth are tools with inconvenient maintenance requirements.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_14', text: "People called me an omen. I wanted somewhere to put down my bag.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_15', text: "The rope hangs within reach. Reaching isn't a reason to pull.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_16', text: "I found a loose peg by sound. Quite smug about it, thank you.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_17', text: "The bell is older than my keeping. I ask the older beams what they remember.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_18', text: "That beam answers a little late. I haven't decided whether the wood or my hearing needs checking.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_19', text: "I like where I am. A small sentence with considerable history.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_20', text: "Do you want a tour? We can stop whenever every board begins sounding like a board.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_21', text: "My cup lives on a level shelf. Warren looked personally pleased by that.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_22', text: "A grub is eating the sacred beam. Nobody appears to have briefed it.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_23', text: "Tok, tok. Two taps. I don't require a complicated password from a friend.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_24', text: "Come after dusk. I'd like to hear another set of steps on the stairs.", phase: 0, animalType: 'aye_aye' },
  // Phase 1 (28)
  { id: 'ay_1_1', text: "Tok, tok. The beam gave me three back. Two like mine, then a softer one from below. I tried again. Wood usually returns what you give it. This wood adds something.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_2', text: "I tried pipe, cistern, loose board. The extra knock stayed slower and softer than mine. An echo should copy. This pauses, as if deciding where to put its finger.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_3', text: "I test different knocks and record the reply. Usually my count plus one. I have circled the exceptions. They're the interesting part.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_4', text: "One tok from me. A long pause, then two together. I sat under the stairs awhile. That's a greeting where I come from. I hadn't meant to open a conversation.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_5', text: "I asked Warren about late, soft echoes in the tunnels. He wanted to know which timber. He didn't laugh. I had been rehearsing what to say if he laughed.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_6', text: "The beam waits its turn. No rat-scrabble or strained-timber groan. My mother said you could share a wall with anything that knocked politely. I am testing the wall part first.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_7', text: "Chalk circle for each hollow: stair, gap, shaft. The circles have begun joining up. I followed them with string. Whoever left these spaces knew where the next one would be.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_8', text: "Gap to shaft, shaft to gallery. My chalk line makes a passage, all the way below the deepest floor. Tok. The map has gone beyond the reach of my finger.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_9', text: "Warren laid my chalk map over his survey of the old foundation and new additions. The hollow line followed a joint. We marked where they stopped matching.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_10', text: "The bell hummed at dawn. Both my hands were on the ladder, six feet away. I said good morning before thinking to measure anything. The log has to admit that.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_11', text: "Fennick heard the dawn hum from camp. Under the bronze he said it sounded like an answer. To what? He couldn't hear that part. We stayed until the sun cleared the ridge.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_1_12', text: "Two logs now: beam at night, bell at dawn. Precious little sleep between them. I used to sound wood for grubs. This work has questions that won't fit in my mouth.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_13', text: "The wall knocked before my finger landed. Tok, just ahead of me. I held my hand there. Tried another board. Nothing. I have marked the first one and left it alone tonight.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_14', text: "My finger pulls toward the hollow passage. A small pull, down through the boards. I notice it while carrying a cup. Tea makes a useful objection to an unexpected direction.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_15', text: "Stocking over my eyes, three turns, let the finger choose. Eleven trials; found the hollow each time. I took the stocking off. I've known this hand all my life. It surprised me.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_16', text: "Tok, tok-tok, tok. My childhood call. The beam returned it exactly, lower and far below. I had expected the usual extra beat. Instead it sounded as though somebody knew my name.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_17', text: "A new call, seven beats with a stutter. I kept it in my head for three days. On the fourth the beam played it first. I felt flattered. Then counted the beats again.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_18', text: "Something beneath the boards repeats my knocks. The answer is clearer than when I first arrived. I don't know whether that makes it more polite or simply nearer.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_19', text: "My call sign in Ember's fire. Sparks and settling coals: tok, tok-tok, tok. She had heard it all week and wondered whose it was. I had no instrument with me but my hand.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['fox'] },
  { id: 'ay_1_20', text: "I tapped Axel's glass to say hello. One note held; another answered from the deep end. He called it learning a song. We listened with my finger resting between the notes.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['axolotl'] },
  { id: 'ay_1_21', text: "Sloane waited on the landing to ask about the answer. She calls it teaching. I tried the word against the beam. Tok. No extra instruction came with the next knock.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_1_22', text: "Each of your words ends with a soft landing-sound below the timbers now. I can hear the end of its journey. Nearer the floorboards each night. I have moved my listening mark.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_23', text: "I followed the hollow behind the stairs, three floors down. Warmer at each turn. No dust in the passage. I brushed a finger along it. Swept clean, right into the corners.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_24', text: "At the third floor the wood ticked like a warming kettle. I stopped there. It knows my knock. I would rather hear an invitation before putting my whole hand through.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_25', text: "The bell's dawn note runs along the ridgepole now. A minute of hum around my sleeping frame. My mother hummed while foraging. I wake with that memory before I reach for the log.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_26', text: "More gnawing lately. Warren brings offcuts. One from the deep shoring tasted like the sweet old beams. I kept a shaving beside the new wood. Same sweetness, darker grain.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_27', text: "I tap to Vesper: still awake? Her tap: always. A third answers below us now. We both stopped the first night. Tonight I waited for all three before settling to sleep.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_1_28', text: "Last page of the log: remembered knocks, dawn hum, one added beat. It has not begun a conversation yet. When it does, I'll bring you the exact rhythm.", phase: 1, animalType: 'aye_aye' },
  // Phase 2 (21 + question-web)
  { id: 'ay_2_1', text: "The finished chalk map looks like a bell. Swelling and narrowing, rafters to deepest floor. I hung it beside the bronze. My small bell at the top of a much larger hollow.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_2_2', text: "A solid bell is a lump. Leave a hollow and it can speak. That doesn't tell me what this house will say. It tells me which part of the map to listen to.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_3', text: "Your words take the hollow passage now. At the top, a patter; below, a clear note. I followed one by moving my ear along the boards. The house gives it a ring.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_4', text: "The pit sits at the mouth of my chalk bell. Thin ground there, like a drumskin. Warren's joins are sound. I asked about the old stone beneath them before adding it to my drawing.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat', 'pangolin'] },
  { id: 'ay_2_5', text: "Bell, throat, thin floor. Something beyond it knows my knocks. I came to tend the bronze upstairs. The survey keeps giving me a larger instrument. I'd like a smaller job for an evening.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_6', text: "The frame knocked my pattern without waiting for me. I wrote that down first. Then I lay still and let myself decide whether to answer.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['rabbit'] },
  { id: 'ay_2_7', text: "One answer where I used to give five. Each returning knock seems to open the sound a little further. Craft includes stopping between strokes to see what the tool has done.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_8', text: "I left a knock unanswered. No louder knock followed. Next night, the same quiet rhythm. I am grateful it can wait. I am still taking my time with the answer.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_9', text: "A lift at the end of some knocks now. Runs of five and seven. It knows my call sign and your words. I have begun writing the beats with spaces between them.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_10', text: "Some words land with an ordinary tok. Others warm the hollow line. The old dusk words do it most often. I test with the back of my hand. My finger is too interested.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_11', text: "They called my pointing finger an omen. By winter, every shutter closed when I came near. Now it points without my asking. I need someone to hear that without reaching for a latch.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_12', text: "At dusk my finger uncurls toward the pit, down and east. First night I held it shut. Second night I let it point. Same bearing. I am learning how to hold the rest of my hand steady.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_13', text: "More billets by my bed. The teeth need gnawing; the new questions need talking through. At three in the morning I can manage the wood. Visit after dusk for the other work.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_14', text: "Fennick says the knocking and breathing feel the same size. Chill brought tea while we listened. One cup on the sill stayed steaming after ours cooled. Nobody had taken a sip.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['fennec_fox', 'capybara'] },
  { id: 'ay_2_15', text: "I've been the shape people shut out. This listener learned my knock and answered. I like being recognized. You should know that about the person giving you reports from inside the wall.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_16', text: "Ear against the bell's waist: a shape of sound held in the bronze. I can't ring it out by listening harder. I polish the place where my ear leaves a mark.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_17', text: "Bell profile, house profile. Waist and throat match on my chalk sheets. I laid one over the other. Tok. The same hollow at two sizes. I'd like to hear it before I call it a purpose.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_18', text: "I've thought of striking her early. One ordinary noon, settle the question. Then I hold the rope and wait. Her first note will be heard through the whole house. That deserves more than my impatience.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_19', text: "Dusk climbs the tower: gold floor, rose bronze, dark window. I polish through that hour. Below grows quiet while the hollow begins answering. My cloth keeps its ordinary little scrape between them.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_20', text: "Thyme sent flowers and a question: is it kind? I wrote that it knocks gently, which isn't enough to know. She sent back staying. I kept her note beside the flowers.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['rabbit', 'pangolin'] },
  { id: 'ay_2_21', text: "End of the log. Bell-shaped house, answering hollow, and now the first knock comes from below. I ration my replies. The blank page is ready. I won't fill it before the next sound.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_w1', text: "Ask Warren what holds his knock on the way back. Mine returns sharp; his returns late. Two pieces of wood, same house. Tok. There is a missing beat between our maps.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  // Phase 3 (30)
  { id: 'ay_3_1', text: "The beam knocked in groups I could separate into letters. I copied the rhythm before translating. I don't want to hear only what I hope it says.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_2', text: "The knocked letters travelled up into the bronze. I wrote their rhythm with a shaking hand. The bell sits heavier in her frame now. I checked the bolts before wondering about the word.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_3', text: "It knocks old dusk words. I answer with weather, frost, the smell of bread in the shaft. Small talk through a wall. I used to wish for a neighbor who would try that.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['pangolin'] },
  { id: 'ay_3_4', text: "It tapped the rhythm of your words, then a question-beat. I answered friend. A friend who returns. Warmth came up until morning. I hope friend carried the meaning I put into my hand.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_5', text: "Every exchange makes the wall feel thinner. Perhaps one night it won't need my knock to speak. I'll still know which beams are sound. I am keeping the tools for that work.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_6', text: "I thought her first ring would warn the house. The note forming in her sounds like a welcome. I want to ring it. I am keeping that want separate from the rope.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_7', text: "The bronze holds a word. The floor beneath the pit answers tighter. My finger keeps finding both. There is an hour approaching. I can braid a sound rope without pretending I know its date.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_8', text: "I rebraided the worn end of the rope. Three strands of hemp and a little of my combed fur. A rope should fit the hand that chooses to pull it.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_3_9', text: "Twelve practice pulls at dusk, sandbag at the bell's height. A rope should hold without slipping. My shoulders ache. The practice makes my hand ready; it doesn't decide when I use it.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_10', text: "You still climb the stairs after hearing my reports. I'd like to take that for agreement. I haven't asked. Stay through dusk if you want. There is room to tell me I'm wrong.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_11', text: "My finger points through sleep now, down and east. At sunset it lifts toward the sky through the bell. Two addresses. I drew both and tied a reminder to rest my hand.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_12', text: "The villagers called this finger a mark of misfortune. Finding something strange with it doesn't justify how they treated me.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_13', text: "The knocking paused. A pressure settled on my chest, exact as a fingertip, for three heartbeats. Thirty years pointing; one night pointed at. I laughed before I could choose another sound.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_14', text: "The attention found the empty place I carry. No recoil, no pity. I wanted to call it welcome. I rested my hand there afterward and tried to hear what was still my own.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_15', text: "A knock should leave room for no. I want to know whether the answer here can actually be no.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_16', text: "Spade quiet, palms on stone. Fire steady, kitchen in one key. Separate sounds beginning to tune together. I tap an ordinary loose board between them. It still has its own note.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['wombat', 'fox', 'pangolin'] },
  { id: 'ay_3_17', text: "Fennick pointed out water, fire, beam-pulse. One sound, he said, large enough to want a bell. We looked at the rope. Neither paw nor ear can answer for the hand that pulls.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_3_18', text: "Ember's fire showed her this tower: rope hung, paw unseen. I told her I'd braided my fur into the rope. She recognized the color. We drank the tea before it cooled.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['fox'] },
  { id: 'ay_3_19', text: "Panko sent a portion for me and an extra wrapped bowl. I asked who she intended it for before putting anything beside the beam.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['pangolin'] },
  { id: 'ay_3_20', text: "Warren thinks his late knock is being received, not stopped. He tapped my floor to show me. Before leaving he checked the rope and called it well braided. I kept that part too.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_3_21', text: "Thyme stayed while my finger turned skyward. She had expected a weapon. I showed her the knuckle, the ordinary bend of it. We put her flowers on the sill together.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['rabbit'] },
  { id: 'ay_3_22', text: "I hummed against the bronze; Axel saw rings in his tank. His paw on the glass warmed the bell under my ear. We repeated it. Two ends of one instrument, and both of us listening.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['axolotl'] },
  { id: 'ay_3_23', text: "Vesper watches above while I listen below. The two reports seem connected. We are comparing them before calling the connection one door.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_3_24', text: "Sloane remembers the tower before my family. She called it reserved. I looked at my fresh rope against the old beam. On her way down I brought tea to the third landing.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_3_25', text: "Try holding a word one breath before offering it. I hear a rounder note when it lands. A small listening experiment, if you like. You needn't change your hands on my account.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_26', text: "I can draw a line through my life toward this bell. I can also remember journeys that went elsewhere. The bell doesn't get all of me.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_27', text: "The wall passage is warm floor by floor. Still open. I climbed inside and rested there awhile. It felt like being carried. After an hour I took myself back to the tower.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_28', text: "I have set water by the rope. If the moment needs my voice, I would rather not discover my throat has other plans.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_29', text: "I left the log open. The next page needs what actually happens, not what I have prepared to remember.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_30', text: "There may be an hour with the bell in it. I'll decide when my hand reaches the rope. I'd like you nearby, if you choose.", phase: 3, animalType: 'aye_aye' },
  // Phase 4 (30)
  { id: 'ay_4_1', text: "Rope loosened. Ready is different from pulled.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_2', text: "The bell kept silence longer than I've kept her company. Both entitled to nerves.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_3', text: "An answer to our work doesn't mean we understood the asking.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_4', text: "A hollow in bronze changes when I stop naming it.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_5', text: "My finger finds grubs and stranger things. Neither justified the villages' closed doors.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_6', text: "I wanted a home for something feared on sight. I'm not an impartial host.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_7', text: "Being called an omen taught sympathy for an unknown guest. It didn't establish the guest's kindness.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_8', text: "I have been the thing in the walls. I wanted somebody to knock back.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_9', text: "I asked what the bell wanted. Silence isn't yes. I know that.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_10', text: "The rope wears under my thumb. Hands want work while answers aren't ready.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_11', text: "They were wrong to drive me out. A strange gift won't make them right.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_12', text: "Tapping finds hollows. It doesn't decide who should live there.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_13', text: "Vesper left room for me. A small, deliberate kindness.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_14', text: "New marks in the gnawing block every day. I hadn't realized how much I liked that.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_15', text: "One beam on the tour? We can stop. A tour needn't be a vow.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_16', text: "The robe catches on the frame. Ceremonial wear never met a working keeper.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_17', text: "I count the gap before the echo. I don't know whether to enter it.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_18', text: "If I touch the rope, I need to say honestly that I decided to.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_19', text: "Stand where you want. We can arrange the rest around people.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_20', text: "A room is a hollow with someone's things inside. Encouraging.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_21', text: "I repaired the peg myself. Something mended by my hand.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_22', text: "Nobody latched my room against me. Gratitude isn't permission to latch someone else's.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_23', text: "I want the arrival. I can still ask it to wait for an answer.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_24', text: "A cloth over bronze quietens it. Even an old voice can be asked to lower itself.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_25', text: "Water by the rope. Dry throats remain inconvenient on dramatic occasions.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_26', text: "My finger trembles when still. Give it work and it behaves. Familiar problem.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_27', text: "I don't want respectability at the cost of forgetting who welcomed me without it.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_28', text: "A grub in the sacred beam. Questions for whoever chose that beam.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_29', text: "Here is where my hand would go. Showing you doesn't decide for us.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_30', text: "The bell's voice is saved for the moment we actually meet.", phase: 4, animalType: 'aye_aye' },
];

// KAKAPO (Moss) - The patient caller whose lifelong booming is finally answered
const KAKAPO_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'kk_0_1', text: "Moss. Mind the seedlings. They're occupying land with impressive confidence.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_2', text: "I walked here. The hills left me with strong opinions about walking.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_3', text: "A kakapo doesn't fly. I have excellent views from many perfectly ordinary rocks.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_4', text: "The honey smell is me. The bees consider it false advertising.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_5', text: "Sugar water by the gate. A peace offering to disappointed bees.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_6', text: "The roof needed soil. I brought soil. Several trips and one regrettable shortcut.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_7', text: "That bowl is for calling. It took longer to make than it looks.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_8', text: "I have called for ninety years. Afterwards I listen. That is the harder part to explain.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_9', text: "I chose this garden for the sky. I am still surprised I got it.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_10', text: "The good bucket is a seat. The other bucket is a bucket. Labels might help.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_11', text: "I garden slowly. Plants haven't complained.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_12', text: "A seed packet is an ambitious thing to carry a long way.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_13', text: "This rimu could take decades to become a great tree. Watering today fits my schedule.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_14', text: "The nest lining needs changing. An empty nest still collects dust.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_15', text: "I keep a small weed by the path. It arrived independently.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_16', text: "When a hawk passes I freeze. A beetle once mistook the occasion for free transport.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_17', text: "The bees have found the water. Negotiations improve.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_18', text: "I miss a particular voice. Being around voices helps, without replacing it.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_19', text: "The bowl sounds different after rain. I empty it before practicing.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_20', text: "A garden on a roof needs checking beneath the pots as well as above.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_21', text: "The new leaf has a bitten edge. I have a suspect and inadequate fencing.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_22', text: "A flightless bird on the roof. I enjoy the result enough to forgive the stairs.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_23', text: "Something low answered the bowl. Might have been the house settling. I wrote down when.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_24', text: "Stay while I water, if you like. The small things are worth meeting first.", phase: 0, animalType: 'kakapo' },
  // Phase 1 (28)
  { id: 'kk_1_1', text: "The low answer returned while I hummed at work. I stopped humming and listened. I haven't used the great call here yet.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_2', text: "I sat up to listen properly last night. The answer is one note, very low, lower than mine, and it comes from no direction at all. Every other sound in the world comes from somewhere. I walked the whole garden with my head tipped, like a fool at a fair, and the note was exactly as loud at every corner.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_3', text: "Ninety years I called with nobody answering, and I made my peace with that, I genuinely did. So you'd think an answer would be pure joy. It's joy. It's just that joy, arriving this late, comes wearing a coat you don't recognize, and you spend a while at the door before you let it in.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_4', text: "The seedlings come up leaning now. All of them, every bed, tilted toward the center of the garden like a room of children looking at the same window. I straightened a row of beans out of principle. By morning they'd leaned back, politely, the way you return to a subject when the interruption is over.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_5', text: "The beds lean toward my calling bowl. I moved a pot to check. Same lean. I can't yet tell whether they're facing my voice or the answer beneath it.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_6', text: "Fennick hears the answer even when I haven't called. I said perhaps it wants company. He asked for a quiet hour. I hadn't thought to want one. I am thinking about it now.", phase: 1, animalType: 'kakapo', requiresAnimals: ['fennec_fox'] },
  { id: 'kk_1_7', text: "Archimedes found mossbirds in an old book, calling across the green. It used the word summons. We both wanted to know who was supposed to answer. The page offered no name.", phase: 1, animalType: 'kakapo', requiresAnimals: ['owl'] },
  { id: 'kk_1_8', text: "The rimu seed germinated early. The tree may take decades to mature; the seed isn't meant to wait forty years before beginning.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_9', text: "I dug a test row along the warm line where your words come up through the soil, and a row the same day in ordinary ground. The warm row is ankle high. The ordinary row is asleep. I'm a scientist now, apparently. My laboratory smells of honey and my findings unsettle me pleasantly.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_10', text: "The buds are fattening out of season. I've begun keeping a mast diary, the way my grandmother's generation did, tallies scratched on a bit of slate. Every mark this month is a mark toward a mast year. The slate is filling faster than any story I was ever told.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_11', text: "Warren asked whether roots could account for the warmth below. I couldn't account for that much. We compared a handful from each place. He took both back down to the lamp.", phase: 1, animalType: 'kakapo', requiresAnimals: ['wombat'] },
  { id: 'kk_1_12', text: "The true call takes a great breath. I'm saving it. Humming while I work is quite another noise.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_13', text: "Tock's rounds pass under the beds each night. The seedlings tick along. When the knocks reach the bowl, they lean further. I tied thread to a stem so I could check tomorrow.", phase: 1, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_1_14', text: "A plant I never planted has come up in the south bed. Broad dark leaves, veins like handwriting. I've grown everything green that grows and I don't know it. I ought to pull it. A stranger in the bed is a weed, that's the whole law of gardening. It smells faintly of rain on warm stone. I haven't pulled it.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_15', text: "Three new plants in an even curve. The spacing is as careful as mine. I watched with my chin on the bed frame. Someone has left me very little thinning to do.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_16', text: "Thyme's seed twists this month came with a note that said, is your garden doing it too. Just that, no greeting, which for Thyme means the words cost her something. I wrote back, yes, and added, it doesn't feel unkind. Because it doesn't. That's the strangest part, and I wanted her to have it.", phase: 1, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_1_17', text: "The moths have multiplied. Hundreds now, every night, rising off the beds at moonrise all at once, like the garden exhaling. They circle the bowl three times, always three, and then off down toward the house. I don't keep moths. Somebody keeps moths. I'm beginning to wonder who keeps me.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_18', text: "I froze with one foot up. Empty blue sky, no hawk I could see. Twenty minutes before I put it down. The watering can waited beside me. I finished that row first.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_19', text: "Bamboo's stalks lean inward; my beds lean toward the bowl. They came to see the difference. We crouched by one stem until the tea cooled. Looking took longer than the explanation.", phase: 1, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_1_20', text: "The honey smell has gotten stronger. Not mine, I know my own weather. The whole garden smells of honey some evenings now, sweet and old. The bees have stopped following me around, because why would they, the air itself is the flower now. I sit in it and feel oddly expected.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_21', text: "Lying in the middle bed, I thought the stars looked like a lid. I usually call them a garden. Same lights tonight, a less comfortable name. I moved to the fern corner.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_22', text: "Grandmother said to deepen the bowl when the mast slate filled early. Three weeks early today. I stood with my digging foot ready. Then put it down. An old instruction can wait one evening.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_23', text: "Your words warm the lines beneath my beds. Half this early growth follows their arrival. I am glad of the fruit. I should ask what the warmth means before thanking you for all of it.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_24', text: "I deepened the bowl by moonlight. Both feet, the old way. The beds were quiet while I worked. I left the loose soil in a pile beside it. I may want to fill some back.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_25', text: "I filled my chest to call. The answer began before I had let the air out. I sat through its note in silence. Then tried one small boom of my own.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_26', text: "Axel described moonlit beds, a bowl, the new plants' veins. He has never climbed here. I sent back a leaf to compare. It was the shape his water had shown him.", phase: 1, animalType: 'kakapo', requiresAnimals: ['axolotl', 'pangolin'] },
  { id: 'kk_1_27', text: "I've begun talking to the stranger plants in the evenings. Telling them the garden news, who sprouted, who is being eaten by what. They don't answer, plants never answer, but the leaves hold very still while I talk. There are kinds of still, friend, I know them all from the inside. This is listening-still.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_28', text: "Full moon, deep bowl, a hum beneath the beds. I sleep well up here. Visit again when you can. Bring an account from downstairs; my garden has been keeping most of my attention.", phase: 1, animalType: 'kakapo' },
  // Phase 2 (21 + question-web)
  { id: 'kk_2_1', text: "The green went strange this week. Not sick, strange. Every leaf in the garden has darkened one shade, all together, overnight, like a room when someone tall walks past the lamp. I checked the sun. The sun is where I left it. Whatever passed, it passed on the other side of the light.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_2', text: "Ninety years of unanswered calls. I used to imagine them fading away. Now I wonder whether something kept them. I'd like to hear one young call again. I might not recognize my voice.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_3', text: "The answer feels familiar. I can't establish that it listened to all ninety years of calling merely because I want it to have heard them.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_4', text: "The words below and the warmth in these beds seem connected. I came to keep a garden. I am asking what else the garden is being used for.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_5', text: "The new flowers open at my old calling hour. I sit among them and feel recognized. Ninety years I wanted that. Today I watered the plants that open at other hours too.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_6', text: "Fruit setting across the valley, all at once, in the wrong month. In the old forest that meant a mast year. I have brought out the largest baskets. They may still be too small.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_7', text: "A mast year brings everything into fruit together. I used to enjoy the agreement without wondering how it began. Up here, over the warm house, I have begun looking beneath the beds.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_8', text: "Sloane took most of a day over my mast-year question. She says the ready ones feed the ones who decide. I went back to the beds and counted who was being fed.", phase: 2, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_2_9', text: "Moths go down; warmth comes up; fruit swells for something not here yet. I planted every bed. I would like to meet the creature my garden has begun feeding.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_10', text: "The beds are more beautiful than anything I grew alone. Being used feels remarkably like being needed from here. I can water while I think about the difference. The plants still need water.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_11', text: "Dropped a pebble into the bowl. Its knock circled much longer than a little bowl of dirt should allow. Under the fading sound, the answer rose. I hadn't meant the pebble as a call.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_12', text: "The fern corner is cold; the bowl stays warm. I sleep there now. Green dreams, soil in my feathers by morning. I put a stone at the edge to mark how deep it is.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_13', text: "In the green dreams I'm walking downhill. Always downhill, through beds I have never planted, past the stranger plants grown tall as trees, veins bright as evening windows, and something is walking with me. Not beside. Underneath, keeping perfect pace under the path. I'm never afraid in the dream. I keep trying to be. It won't take.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_14', text: "Thyme asked me over the seed post whether I thought the garden loved us or kept us. I wrote back that a good shepherd does both and that neither of us is a sheep. I sat with my pen a long time after, because I couldn't work out which of us I'd comforted, or with what.", phase: 2, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_2_15', text: "Something heard me. That is the part I know. I am trying not to put everything I hoped for inside that fact.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_16', text: "Ripe fruit, no takers. Birds land and leave it. Moths pass by. Usually I have to defend a basket from half the valley. Tonight I offered one fruit from my own foot. Still nothing.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_17', text: "I hid a ripe fruit in a tin under the north bed. Morning: tin open on the path, fruit on top, facing the bowl. Unbruised. I wish that detail were more reassuring.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_18', text: "I have stopped calling the new plants strangers. I water them; they grow in my beds. I still don't know what brought them. Naming something mine doesn't answer where it came from.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_19', text: "Vesper says the stars sit lower. I feel the warmth nearer my roots. We compare at the gate post. Her chart and my planting slate are beginning to need the same margin.", phase: 2, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_2_20', text: "The ground carries the low note without my voice. It doesn't replace the call. I still get to decide when to use my breath.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_21', text: "The mast is heavy. The bowl stays warm. Come sit while I sort the baskets. I know when fruit is nearly ready. This season I would appreciate being a little wrong.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_w1', text: "I sent Panko mast fruit. The extra plate came back empty, with a fern I hadn't picked. Ask who that place is for. A grower likes knowing who has eaten.", phase: 2, animalType: 'kakapo', requiresAnimals: ['pangolin'] },
  // Phase 3 (30)
  { id: 'kk_3_1', text: "The valley fruited all at once. My body wanted to go to the bowl. An old habit, powerfully returned. I went to check the seedlings first.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_2', text: "My working theory: the words below change what grows here, and something answers through the roots. I don't yet know why it has chosen to answer me.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_3', text: "Archimedes calls it an arrangement. I recognize a mast year's plenty, arriving together. But this reaches beyond the trees. I have kept an empty basket beside the full ones. Plenty must go somewhere.", phase: 3, animalType: 'kakapo', requiresAnimals: ['owl', 'fox'] },
  { id: 'kk_3_4', text: "I deepened the bowl and tried a soft hum. The answer held another note inside mine. Humming isn't the great call. I'm saving the larger breath.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_5', text: "I'm glad you visit the garden. If you missed part of the growing, I can tell you about it. We don't need to pretend you saw every leaf.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_6', text: "A shadow passed and I froze. It was a hawk. I had nearly turned an ordinary fear into evidence about the house.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_7', text: "Fruit leaves the branch and falls slowly, heavy as an egg but drifting like a leaf. I put a basket under one and waited. For once I didn't have to hurry the catch.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_8', text: "I carried the fallen fruit to the bowl. A complete ring by midnight. Gone by morning, warm soil where it had rested. I brought up the empty baskets and counted them twice.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_9', text: "Tock knocked on the gate post. The bowl answered first. He listened with his head tipped, then sounded the wood again. I kept one foot on the post. The note reached it from below.", phase: 3, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_3_10', text: "The moths rose after circling the bowl. I recorded the change of direction. I don't know what they carried, if anything.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_11', text: "Ember called the bowl a slow green fire. I showed her where the fruit had gone. We sat with our feet on the warm soil. My garden and her grate needed a new conversation.", phase: 3, animalType: 'kakapo', requiresAnimals: ['fox'] },
  { id: 'kk_3_12', text: "Bamboo and I take tea at the roof gap, ladder on one side, beans on the other. They expect a visitor above us. I asked them to tell me if it bends the bean poles.", phase: 3, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_3_13', text: "Thyme showed me her seed tin. I asked for a few, then left her to decide. Gardens shouldn't begin by taking someone's whole future.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_14', text: "Fennick asked whether the low chord was calling or answering. Ninety years of calling should qualify me to answer. I had to admit I couldn't tell.", phase: 3, animalType: 'kakapo', requiresAnimals: ['fennec_fox'] },
  { id: 'kk_3_15', text: "Plants taller than me now. All turned toward the bowl in one night. I found myself facing it too. I went to weed the east bed, where the work needs me to look elsewhere.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_16', text: "Your words warmed the roots and helped bring the mast. I tended what grew. We helped something happen before either of us knew what it was. A grower has to account for that too.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_17', text: "I know an old welcome we used to sing near a nest. I have been humming it while working. You can walk beside me without joining in.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_18', text: "Warren's foundations hold what's above; my roots feed what comes. We sat at the bed edge comparing the work. He asked what we'd braced it for. I had been hoping he knew.", phase: 3, animalType: 'kakapo', requiresAnimals: ['wombat'] },
  { id: 'kk_3_19', text: "I want to meet what answers. I can also fear it. Wanting a guest never guaranteed the guest would be easy to live with.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_20', text: "The bare bowl sang. No pebble, no call from me. The beds leaned while the note lasted. I kept my chest quiet and listened until it ended. My answering breath could wait.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_21', text: "Vesper brought the sky log to the gate. I brought the planting book. Same warm nights, same pauses. We kept both books. Her little marks tell me things my roots can't.", phase: 3, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_3_22', text: "I imagined welcoming it for everyone. Then tried to remember when everyone had asked me to speak for them.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_23', text: "Fruit remains on the last branch. I keep expecting it to tell me when to call. Then I remember a tree has its own season.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_24', text: "The nest has no egg. I care for it anyway. It isn't proof that something has promised me a chick.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_25', text: "The last fruit is loosening. A small tick at the stem each night. Come up if you can. I would like company when it falls, and another pair of feet to carry the basket.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_26', text: "The last fruit came down at moonrise. Then the bowl drew air over my feathers, one long inward breath. No breath out. I waited with my feet in the soil. The empty basket stayed beside me.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_27', text: "Sloane came to see the bowl. She asked what I hoped to hear. I asked what she had been waiting for. We had a longer conversation than either expected.", phase: 3, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_3_28', text: "A length of green cloth came up with the supplies. I laid it beside the ordinary work apron. I haven't decided what occasion could require it.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_29', text: "The ground repeated a phrase of my grandmother's. I wanted to step into the bowl. I stayed at the edge and listened to how it said her words.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_30', text: "I've practiced stopping after the call. Being answered will require listening. That is the part I can't rehearse alone.", phase: 3, animalType: 'kakapo' },
  // Phase 4 (30)
  { id: 'kk_4_1', text: "Ninety years calling. Waiting that long can make anything sound like an answer.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_2', text: "Bowl swept. Old customs need maintenance.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_3', text: "I walked here. Nobody carried me toward destiny. There were hills. I complained.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_4', text: "Something answers humming under the beds. Humming isn't the call. I'm saving that breath.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_5', text: "Decades before the rimu bears heavily. Seedlings can begin sooner.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_6', text: "I've waited for trees. None promised to understand me.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_7', text: "An answer means heard. I'm trying not to smuggle every wish into that.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_8', text: "Warmth below the roots. Vesper watches for the arrival above the roof.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_9', text: "My nest has room. Hard to say without sounding like an advertisement.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_10', text: "Sugar water for disappointed bees. The honey smell is only me.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_11', text: "Unidentified shoot beside the bowl. It can stay while we find out.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_12', text: "You made room on the roof. I brought soil afterwards, load by load.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_13', text: "Walking wasn't rehearsal for anything. Excellent things at ground level.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_14', text: "Thyme keeps seeds back. Something uncommitted to current weather. Good.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_15', text: "I'd like others to hear my call. I'm afraid they will, too.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_16', text: "After calling: water and someone who won't ask for an encore.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_17', text: "The bowl was empty for years. I gave it much of its sadness myself.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_18', text: "Don't promise the wait was worth it. Let me hear first.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_19', text: "Your words changed the growth. I enjoyed it before asking what it fed.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_20', text: "The same flower again. What would its seeds do differently?", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_21', text: "I kept a weed. It arrived without a plan. We have that in common.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_22', text: "Sometimes I wanted any reply. Sometimes a particular lost voice. Different wants.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_23', text: "A long life gives patience. And plenty to be impatient about.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_24', text: "A nest doesn't promise something will fill it. I can care for it anyway.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_25', text: "I turned the weed's pot to give it different light.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_26', text: "The good bucket is the seat. The other one is pretending badly.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_27', text: "I'd like a different song next year. Even if it takes winter to learn.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_28', text: "I practiced stopping after the call. Listening is work too.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_29', text: "Grandmother said stop telling every seed what the garden is for. Let it surprise you.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_30', text: "When the moment comes, I'll stand in the bowl and use the voice I brought here.", phase: 4, animalType: 'kakapo' },
];

const ALL_DIALOGUES: Dialogue[] = [
  ...RED_PANDA_DIALOGUES,
  ...AXOLOTL_DIALOGUES,
  ...PANGOLIN_DIALOGUES,
  ...SLOTH_DIALOGUES,
  ...FENNEC_FOX_DIALOGUES,
  ...FOX_DIALOGUES,
  ...OWL_DIALOGUES,
  ...CAPYBARA_DIALOGUES,
  ...WOMBAT_DIALOGUES,
  ...RABBIT_DIALOGUES,
  ...TARSIER_DIALOGUES,
  ...AYE_AYE_DIALOGUES,
  ...KAKAPO_DIALOGUES,
];

/**
 * Get all dialogues for an animal up to a certain phase
 */
export function getDialoguesForAnimal(
  animalType: AnimalType,
  maxPhase: DialoguePhase
): Dialogue[] {
  return ALL_DIALOGUES.filter(
    d => d.animalType === animalType && d.phase <= maxPhase
  );
}

/**
 * Resolve a dialogue index to the first line at or after it that doesn't
 * reference a still-locked animal. Indices at or beyond the end of the pool
 * pass through unchanged (Phase 5 cycles rely on out-of-range indices).
 */
export function resolveDialogueIndex(
  animalType: AnimalType,
  index: number,
  maxPhase: DialoguePhase,
  unlockedTypes: Set<AnimalType>
): number {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  let i = Math.max(0, index);
  while (
    i < dialogues.length &&
    dialogues[i].requiresAnimals?.some(t => !unlockedTypes.has(t))
  ) {
    i++;
  }
  return i;
}

/**
 * Index of the first dialogue belonging to `phase` for an animal — i.e. how
 * many of its lines belong to earlier phases. Used to fast-forward animals
 * unlocked late so they don't replay bright-days small talk under a dark sky.
 */
export function getPhaseStartIndex(
  animalType: AnimalType,
  phase: DialoguePhase
): number {
  return ALL_DIALOGUES.filter(
    d => d.animalType === animalType && d.phase < phase
  ).length;
}

/**
 * Get the next unread dialogue for an animal
 */
export function getNextDialogue(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): Dialogue | null {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  if (currentIndex >= dialogues.length - 1) {
    return null;
  }
  return dialogues[currentIndex + 1];
}

/**
 * Get current dialogue for an animal
 */
export function getCurrentDialogue(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): Dialogue | null {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  if (dialogues.length === 0) {
    return null;
  }
  // Clamp index to valid range - show last dialogue if index exceeds available
  if (currentIndex < 0) {
    return dialogues[0];
  }
  if (currentIndex >= dialogues.length) {
    return dialogues[dialogues.length - 1];
  }
  return dialogues[currentIndex];
}

/**
 * Check if animal has more dialogues available
 */
export function hasMoreDialogues(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): boolean {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  return currentIndex < dialogues.length - 1;
}

/**
 * Get total dialogue count for an animal at current phase
 */
export function getTotalDialogueCount(
  animalType: AnimalType,
  maxPhase: DialoguePhase
): number {
  return getDialoguesForAnimal(animalType, maxPhase).length;
}

// ============================================================================
// PHASE 2 EXHAUSTION POOL
// Phase 2 spans one of the longest single stretches (~33-40 puzzles on the
// compressed arc; it was ~80 before); even with 22
// base lines per animal, chatty players exhaust the block and would re-read
// the last line verbatim for dozens of puzzles. These extra lines are served
// (in order, then cycling) once an animal's Phase-2 base block is exhausted
// while the player is still in Phase 2.
//
// CRITICAL: this pool is deliberately OUTSIDE the indexed base arrays.
// Existing players' lastDialogueRead indices point into ALL_DIALOGUES;
// inserting lines there would shift phase-start indices and corrupt saves.
// Pool lines never name another animal (they are ungated plain strings).
// ============================================================================

